window.__LEX={"G1400":"<h1>doulon</h1>\n<p>Strong n° 1400 <i>Prononciation [doo'-lon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un esclave, homme de condition servile\n<ol type=\"a\">\n<li>un esclave</li>\n<li>métaph : celui qui se donne ou se vend à un autre ceux dont le service est utilisé par Christ pour l'avancement de Sa cause parmi les hommes</li>\n<li>dévoué aux autres sans se soucier de ses propres intérêts</li>\n</ol>\n</li>\n<li>un serviteur, un intendant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>δοῦλος, η, ον :<br>   I</b> esclave : <i>en parl. de pers</i>. esclave (de naissance) EUR. <i>I.A. 330 ; différ. de</i> οἰκέτης, ATH. <i>267</i> b ; <i>ou de</i> ἀνδράποδον THC. <i>8, 28 ; p. opp. à</i> δεσπότης <i>et à</i> ἐλεύθερος, XÉN. <i>Cyr. 8, 1, 4 ; à</i> ἐλεύθερος, PLUT. <i>M. 213</i> c ; ἀνὴρ δ. SOPH. <i>O.R. 764 ;</i> γυνὴ δούλη, EUR. <i>Andr. 328,</i> un homme esclave, une femme esclave ; <i>en parl. de choses :</i> ψυχὴ δούλη, PLAT. <i>Leg. 776</i> e, âme esclave ; <i>avec un gén</i>. δοῦλός τινος, ESCHL. <i>Pers. 242,</i> esclave de qqn ; τοῦ θεοῦ δοῦλος, EUR. <i>Ion 309,</i> esclave de la divinité ; <i>p. anal</i>. δ. τῶν πέλας, SOPH. <i>Ant. 479,</i> qui est à la discrétion d’autrui ; <i>fig</i>. λιχνειῶν, λαγνειῶν δοῦλος, XÉN. <i>Œc. 1, 22,</i> esclave de la gourmandise, de la mollesse ; χρημάτων δ. EUR. <i>Hec. 865,</i> esclave de l’argent ; <i>subst</i>. τὸ δοῦλον, la servitude, EUR. <i>Ion 556 ; ou collect</i>. les esclaves, EUR. <i>Ion 983, Or. 1115 ;</i><br><b>   II</b> d’esclave :<br><b>      1</b> servile : δοῦλον ζυγόν, EUR. <i>Tr. 673,</i> joug de la servitude ; γνῶμαι δοῦλαι, SOPH. <i>Tr. 53,</i> sentiments d’esclaves ; δ. βίος, SOPH. <i>Tr. 302,</i> vie d’esclave ; δ. ἡδοναί, PLAT. <i>Rsp. 587</i> c, plaisirs d’esclaves, <i>càd</i>. grossiers ;<br><b>      2</b> habité par des esclaves, <i>en parl. d’une ville,</i> SOPH. <i>O.C. 917</i>.<br><span>•<i> Cp</i>. -ότερος, HDT. <i>7, 7 ;</i> SUID. <i>v°</i> δοῦλος.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δουλον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (2)</li>\n</ul>\n</td></tr>\n</table>","G1401":"<h1>doulos</h1>\n<p>Strong n° 1401 <i>Prononciation [doo'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un esclave, homme de condition servile</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δοῦλος, η, ον :<br>   I</b> esclave : <i>en parl. de pers</i>. esclave (de naissance) EUR. <i>I.A. 330 ; différ. de</i> οἰκέτης, ATH. <i>267</i> b ; <i>ou de</i> ἀνδράποδον THC. <i>8, 28 ; p. opp. à</i> δεσπότης <i>et à</i> ἐλεύθερος, XÉN. <i>Cyr. 8, 1, 4 ; à</i> ἐλεύθερος, PLUT. <i>M. 213</i> c ; ἀνὴρ δ. SOPH. <i>O.R. 764 ;</i> γυνὴ δούλη, EUR. <i>Andr. 328,</i> un homme esclave, une femme esclave ; <i>en parl. de choses :</i> ψυχὴ δούλη, PLAT. <i>Leg. 776</i> e, âme esclave ; <i>avec un gén</i>. δοῦλός τινος, ESCHL. <i>Pers. 242,</i> esclave de qqn ; τοῦ θεοῦ δοῦλος, EUR. <i>Ion 309,</i> esclave de la divinité ; <i>p. anal</i>. δ. τῶν πέλας, SOPH. <i>Ant. 479,</i> qui est à la discrétion d’autrui ; <i>fig</i>. λιχνειῶν, λαγνειῶν δοῦλος, XÉN. <i>Œc. 1, 22,</i> esclave de la gourmandise, de la mollesse ; χρημάτων δ. EUR. <i>Hec. 865,</i> esclave de l’argent ; <i>subst</i>. τὸ δοῦλον, la servitude, EUR. <i>Ion 556 ; ou collect</i>. les esclaves, EUR. <i>Ion 983, Or. 1115 ;</i><br><b>   II</b> d’esclave :<br><b>      1</b> servile : δοῦλον ζυγόν, EUR. <i>Tr. 673,</i> joug de la servitude ; γνῶμαι δοῦλαι, SOPH. <i>Tr. 53,</i> sentiments d’esclaves ; δ. βίος, SOPH. <i>Tr. 302,</i> vie d’esclave ; δ. ἡδοναί, PLAT. <i>Rsp. 587</i> c, plaisirs d’esclaves, <i>càd</i>. grossiers ;<br><b>      2</b> habité par des esclaves, <i>en parl. d’une ville,</i> SOPH. <i>O.C. 917</i>.<br><span>•<i> Cp</i>. -ότερος, HDT. <i>7, 7 ;</i> SUID. <i>v°</i> δοῦλος.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοῦλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n125 fois dans 118 versets de 21 livres bibliques (NT)\n<ul>\n<li>Matthieu (30)</li>\n<li>Marc (5)</li>\n<li>Luc (27)</li>\n<li>Jean (11)</li>\n<li>Actes (3)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (5)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (4)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (4)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (2)</li>\n<li>Philémon (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (14)</li>\n</ul>\n</td></tr>\n</table>","G1402":"<h1>douloo</h1>\n<p>Strong n° 1402 <i>Prononciation [doo-lo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre esclave de, réduire à l'esclavage au passif être asservi par quelqu'un, sous la domination de asservir pour soi, soumettre à sa puissance</li>\n<li>métaph : se donner entièrement, se rendre esclave de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δουλόω-ῶ</b> <span>(<i>f</i>. ώσω, <i>ao</i>. ἐδούλωσα, <i>pf</i>. δεδούλωκα ; <i>pass. ao</i>. ἐδουλώθην, <i>pf</i>. δεδούλωμαι)</span> réduire en esclavage, asservir, <i>acc</i>. HDT. <i>1, 27 ;</i> ESCHL. <i>Sept. 254 ;</i> SOPH. <i>Tr. 467 ; etc. ; fig</i>. THC. <i>2, 61 ; au pass</i>. être asservi : ὑπό τινος, HDT. <i>1, 94,</i> par qqn, être asservi sous la domination de qqn ; δουλοῦσθαι νόμῳ, MÉN. <i>fr. inc. 150 Meineke,</i> être l’esclave de la loi ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. δουλώσομαι, <i>ao</i>. ἐδουλωσάμην)</span> asservir pour soi, soumettre à sa puissance, EUR. <i>Suppl. 493 ;</i> THC. <i>5, 29, etc. ;</i> PLAT. <i>Menex. 239</i> d.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. pass. au sens pass</i>. HDT. <i>8, 101 ;</i> THC. <i>1, 68, etc. ; au sens moy</i>. THC. <i>6, 82. Pl.q.pf</i>. ἐδεδουλώμην, HDT. <i>1, 95 (sel. d’autres,</i> δεδουλώμην) ; <i>1, 169 ; 7, 108</i>.<br><span><b>Étym</b>. δοῦλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δουλοω - δουλόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> représente le serviteur dans son activité au travail ; non dans sa relation avec une personne, que cette relation soit servile, comme celle de , ou plus volontaire, comme dans le cas de .  contrairement à  indique un esclave, celui qui est en relation servile permanente avec un autre.\n<br><br> est l'exécutant volontaire de tâches, qu'il soit un homme libre ou un esclave; ce mot a plus de noblesse que .  suggère la subordination.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>Tite (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1403":"<h1>doche</h1>\n<p>Strong n° 1403 <i>Prononciation [dokh-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un festin, un banquet, action d'accueillir, accueil</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δοχή, ῆς (ἡ)</b> <i>propr</i>. action de recevoir, <i>d’où :</i><br><b>      1</b> réception, festin, MACH. (ATH. <i>348</i> f) ; SPT. <i>Gen. 21, 8 ; 26, 30 ; Esth. 1, 3 ;</i> NT. <i>Luc. 5, 29 ; 14, 13 ;</i><br><b>      2</b> récipient, réservoir, PLAT. <i>Tim. 71</i> c ; δοχαὶ χολῆς, EUR. <i>El. 828,</i> la vésicule biliaire.<br><span><b>Étym</b>. δέχομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοχη - δοχή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G1404":"<h1>drakon</h1>\n<p>Strong n° 1404 <i>Prononciation [drak'-own]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un dragon, un grand serpent, un nom pour Satan</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δράκων, οντος (ὁ)</b> <span>[ᾰ]</span><br><b>   I</b> dragon, <i>animal fabuleux,</i> IL. <i>2, 308, etc. ;</i> PD. <i>P. 4, 434 ;</i> ESCHL. <i>Ch. 1050 ;</i> SOPH. <i>Tr. 12 et 834 ;</i> EUR. <i>Ph. 935, El. 1256, etc. ; p. ext. :</i><br><b>      1</b> serpent, IL. <i>12, 202, etc. ;</i><br><b>      2</b> sorte de poisson (<i>trachinus draco</i> L.) EPICH. (ATH. <i>287</i> b) ; ARSTT. <i>H.A. 8, 13, 3 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> dragon, <i>enseigne militaire, à Rome,</i> THÉM. <i>2 ;</i><br><b>      2</b> collier <i>ou</i> bracelet en forme de serpent, LUC. <i>Am. 41 ;</i> ANTH. <i>6, 206 ;</i><br><b>      3</b> sorte de lacet <i>ou</i> de bandage, ORIB. <i>172 Cocch</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *drḱ-, regarder <i>à cause du regard paralysant</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δρακων - δράκων</font>\n<br><br>vient probablement d'une forme de derkomai (regarder)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 12 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (13)</li>\n</ul>\n</td></tr>\n</table>","G1405":"<h1>drassomai</h1>\n<p>Strong n° 1405 <i>Prononciation [dras'-som-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>saisir avec la main, prendre quelqu'un (par un piège)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δράσσομαι</b>, <i>att</i>. δράττομαι <span>(<i>f</i>. δράξομαι, <i>ao</i>. ἐδραξάμην, <i>pf</i>. δέδραγμαι)</span><br><b>      1</b> prendre avec la main, prendre : τινος, IL. <i>13, 393 ; 16, 486,</i> qqe ch. ; <i>avec idée de violence :</i> τινὸς δρ. χερσί, EUR. <i>Tr. 745,</i> mettre la main sur qqn, se saisir de qqn ; δρ. φάρυγος, THCR. <i>Idyl. 24, 28,</i> saisir qqn à la gorge ; <i>rar. avec l’acc</i>. HDT. <i>3, 13 ;</i> Q. SM. <i>1, 350 ;</i> δρ. καιροῦ, DS. <i>12, 67,</i> saisir l’occasion ;<br><b>      2</b> <i>p. ext</i>. prendre, remporter : τινος, ANTH. <i>11, 238 ; 15, 50 ;</i> CALL. <i>Ep. 37, 15,</i> qqe ch. (la victoire, <i>etc</i>.).<br><span><b><span class=\"arrow\"></span></b> <i>Att</i>. δράττομαι, THÉM. <i>1, 15. Impf</i>. ἐδραττόμην, AR. <i>Ran. 545 ;</i> PHILSTR. <i>2, 40. Ao. 2 sg. poét</i>. ἐδράξαο, CALL. <i>Ap. 76 ;</i> ANTH. <i>15, 50. — Act. seul</i>. POLL. <i>3, 155</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δρασσομαι - δράσσομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1406":"<h1>drachme</h1>\n<p>Strong n° 1406 <i>Prononciation [drakh-may']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une drachme, une pièce d'argent Grecque du même poids que le denier Romain</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δραχμή, ῆς (ἡ)</b> <span>[ᾰ]</span> drachme, <i>poids, puis monnaie de six oboles, càd. d’un peu moins d’un franc,</i> HDT. <i>7, 144 ;</i> THC. <i>8, 45 ;</i> AND. <i>32, 34 ;</i> PLUT. <i>M. 759</i> e ; <i>p. ext</i>. faible somme d’argent : μίαν δραχμὴν οὐκ ἔχειν, PLUT. <i>M. 1058</i> c, n’avoir pas une drachme (<i>cf. franç</i>. n’avoir pas le sou) ; <i>cf</i>. D. CHRYS. <i>1, 146, 204, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ᾱ]</span> AR. <i>Vesp. 689, Pax 1200, Pl. 1020 ;</i> COM. (ATH. <i>230</i> b, <i>297</i> e, <i>442</i> a, <i>581</i> b) ; <i>dans ces ex. sel. Bgk</i> δαρχμή, <i>sel. Gaisf</i>. δραγμή ; <i>cf</i>. SUID. <i>v°</i> δράγμη.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δραχμη - δραχμή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G1407":"<h1>drepanon</h1>\n<p>Strong n° 1407 <i>Prononciation [drep'-an-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une faucille, un greffoir, une serpe, outil utilisé par les moissonneurs ou les vendangeurs</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δρέπανον, ου (τὸ)</b> <span>[ᾰ]</span><br><b>      1</b> faux, OD. <i>18, 368, etc. ;</i> serpe, serpette, PLAT. <i>Rsp. 333</i> d, <i>etc. ;</i><br><b>      2</b> sabre recourbé en forme de faux, cimeterre, HDT. <i>5, 112</i>.<br><span><b>Étym</b>. δρέπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δρεπανον - δρέπανον</font>\n<br><br>vient de drepo (cueillir)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G1408":"<h1>dromos</h1>\n<p>Strong n° 1408 <i>Prononciation [drom'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une course\n<ol type=\"a\">\n<li>dans le N.T. au figuré, la course de la vie ou du labeur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δρόμος, ου (ὁ) :<br>   I</b> action de courir, <i>d’où :</i><br><b>      1</b> course, <i>en parl. de chevaux,</i> IL. <i>18, 281 ; en parl. de pers</i>. THC. <i>4, 127, etc. ;</i> ESCHN. <i>71, 6, etc. ; au plur</i>. ESCHL. <i>Pr. 838 ;</i> HPC. <i>351, 14 ;</i> PLAT. <i>Euthyd. 273</i> a ; <i>p. opp. à</i> βάδην, PLUT. <i>M. 817</i> a ; <i>en parl. des nuages,</i> EUR. <i>Ph. 163 ; de la course du soleil,</i> PLAT. <i>Ax. 370</i> b ; δρόμῳ ἰέναι, PLAT. <i>Crat. 397</i> d ; <i>ou</i> χρῆσθαι, HDT. <i>6, 112 ; ou</i> χωρεῖν, THC. <i>4, 31,</i> aller <i>ou</i> s’avancer en courant ; ἅπαντι χρῆσθαι τῷ δρόμῳ, LUC. <i>Dom. 10,</i> courir de toutes ses forces ;<br><b>      2</b> lutte à la course, <i>soit à pied, soit en char,</i> IL. <i>23, 758 ;</i> OD. <i>8, 121 ;</i> BATR. <i>96 ;</i> PD. <i>O. 3, 59 ; 13, 42 ;</i> SOPH. <i>El. 684, 726, 741 ;</i> PLAT. <i>Leg. 625</i> d ; <i>fig</i>. δρόμον θεῖν, HDT. <i>8, 74 ; ou</i> δραμεῖν, AR. <i>Vesp. 376,</i> disputer le prix de la course, <i>d’où en gén</i>. lutter (pour qqe ch.) ;<br><b>      3</b> course, tour de promenade : δύ' ἢ τρεῖς δρόμους περιεληλυθότε, PLAT. <i>Euthyd. 273</i> a, après avoir fait tous deux, deux ou trois tours de promenade ;<br><b>   II</b> emplacement pour courir, IL. <i>23, 321 ;</i> OD. <i>4, 605 ; particul</i>. emplacement pour la course à pied <i>ou</i> en char, stade, carrière, SOPH. <i>El. 713 et 748 ;</i> ἔξω δρόμου φέρεσθαι, ESCHL. <i>Pr. 883, etc. ; ou</i> ἐκτὸς δρόμου φέρεσθαι, PLAT. <i>Crat. 414</i> b ; ἐκ δρόμου πίπτειν, ESCHL. <i>Ag. 1245,</i> être emporté hors de la carrière, <i>càd</i>. s’écarter du but ; <i>fig</i>. οὐδέν ἐστ' ἔξω δρόμου, ESCHL. <i>Ch. 514, litt</i>. cela n’est en rien en dehors de la carrière à parcourir, <i>càd</i>. hors de propos ; <i>p. ext</i>. lieu de promenade, espace pour aller et venir, PLAT. <i>Phædr. 227</i> b ; κατάστεγος δρ. PLAT. <i>Euthyd. 273</i> a, espace couvert, sorte de préau pour se promener ; ἐν δρόμοισιν Ἀκαδήμου, EUP. (DL. <i>3, 7</i>) dans les allées d’Akadèmos, <i>càd</i>. à l’Académie ; <i>en parl. du vestibule d’un temple,</i> STR. <i>805</i> (δραμεῖν, <i>v</i>. τρέχω).<br><span><b>Étym</b>. <i>R. indo-europ</i>. *drem-, courir ; <i>de</i> δραμεῖν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δρομος - δρόμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1409":"<h1>Drousilla</h1>\n<p>Strong n° 1409 <i>Prononciation [droo'-sil-lah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Drusille (Angl. Drusilla) = « arrosée par la rosée »\n<ol><li>la fille d'Hérode Agrippa I, épouse de Félix, le gouverneur de Judée, femme très licencieuse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Δρούσιλλα, ης (ἡ)</b> = <i>lat</i>. Drusilla, <i>n. de f. rom</i>. NT. <i>Ap. 24, 24 etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Δρουσιλλα - Δρούσιλλα</font>\n<br><br>diminutif de Drusus (un nom Romain)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1410":"<h1>dunamai</h1>\n<p>Strong n° 1410 <i>Prononciation [doo'-nam-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être capable, avoir le pouvoir par sa vertu ou son habilité et ses moyens, à travers des circonstances favorables, par une permission légale, par des coutumes</li>\n<li>être capable de faire quelque chose</li>\n<li>être capable : être fort et puissant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δύναμαι</b> <span>(<i>impf</i>. ἐδυνάμην, <i>postér</i>. ἠδυνάμην, <i>f</i>. δυνήσομαι, <i>ao</i>. ἐδυνήθην, <i>postér</i>. ἠδυνήθην, <i>pf</i>. δεδύνημαι)</span> <span>[ῠ]</span><br><b>A</b> pouvoir, <i>càd. :</i><br><b>   I</b> avoir la faculté de, être capable de, <i>avec l’acc. :</i> δ. ἅπαντα, OD. <i>4, 237,</i> pouvoir tout ; <i>avec l’inf. prés</i>. ATT. (SOPH. <i>Tr. 546, Ant. 686 ;</i> EUR. <i>Ion 598, etc.) ou ao</i>. (ESCHL. <i>Pr. 326, etc.) ; rar. avec l’inf. fut. et d’ord. par attract. après un verbe principal au fut. :</i> εἰ σέ γε πείσειν δυνησόμεσθα μηδέν, <i>etc</i>. SOPH. <i>Ph. 1394,</i> si nous ne pouvons te persuader ; <i>cf</i>. THC. <i>2, 29 ;</i> POL. <i>21, 9, 13 ;</i> ZOS. <i>3, 1 ;</i> MAN. <i>1, 199 ; avec un inf. pass</i>. οὐδὲ δυνάμενοι πολιορκεῖσθαι, THC. <i>3, 52,</i> et ne pouvant pas soutenir le siège ; <i>cf</i>. HDT. <i>9, 108 ;</i> PLUT. <i>M. 88</i> f, <i>etc. ; abs</i>. εἰ δύνασαί γε, IL. <i>1, 393,</i> si du moins tu le peux ; δύναμαι γάρ, OD. <i>4, 612</i> car je le puis ; <i>souv. dans la loc</i>. οὐ δύναμαι μὴ οὐ, <i>avec l’inf</i>. ATT. (<i>sans</i> οὐ, AR. <i>Ran. 42, etc</i>.) je ne puis pas ne pas, je ne puis m’empêcher de, <i>etc. ; avec un superl. précédé de</i> ὡς, ᾗ, <i>etc. ou un relat</i>. (ὅσος, <i>etc</i>.) : ὡς ἠδύνατο κάλλιστον, CIA. <i>2, 420, 12 (2<sup>e</sup> siècle av. J.C.) ; ou abs</i>. ὡς κάλλιστα, CIA. <i>2, 86, 1-2 (376/364 av. J.C.) etc</i>. le plus beau, les plus beaux possible ; ἐπορεύοντο ᾗ ἐδύναντο τάχιστα, XÉN. <i>An. 6, 3, 21,</i> les troupes marchèrent le plus rapidement possible ; ὡς ἐδυνάμεθα ἀρίστην, PLAT. <i>Rsp. 437</i> e, la meilleure que nous pouvions ; ὅσους ἐδύνατο πλείστους ἁθροίσας, XÉN. <i>Hell. 2, 2, 9,</i> ayant réuni le plus d’hommes qu’il put ;<br><b>   II</b> <i>abs. :</i><br><b>      1</b> être puissant, avoir du crédit : μέγα δυνάμενος, OD. <i>1, 276 ; 11, 414,</i> très puissant ; οἱ δυνάμενοι, EUR. <i>Or. 887,</i> les puissants ; οἱ τὸ μέγιστον δυνάμενοι, XÉN. <i>An. 7, 6, 37,</i> ceux qui sont le plus puissants ; μέγα δύνασθαι παρά τινι, HDT. <i>7, 5 ;</i> ESCHL. <i>Eum. 950 ;</i> THC. <i>6, 59 ;</i> AND. <i>32, 31, etc</i>. être puissant auprès de qqn ; <i>avec un dat</i>. χρήμασι δυνάμενος, LYS. <i>107, 25,</i> puissant par sa fortune ; δύνασθαι τῷ σώματι, LYS. <i>168, 26,</i> être robuste ; δυνάμενος τῷ τε πράττειν τῷ τε λέγειν, DÉM. <i>1187, 8,</i> puissant par l’action et par la parole ; <i>avec un adj. plur</i>. πολλὰ δυνάμενος, DÉM. <i>511, 9 ;</i> μεγάλα δυνάμενος, X. ÉPH. <i>p. 81, 13,</i> très puissant ; <i>d’où abs</i>. prévaloir : τινι, SPT. <i>Judith 16, 5 ; Jer. 20, 10,</i> contre qqn ;<br><b>      2</b> avoir un sens, une signification : δύναται δὲ τὸ νεοδαμῶδες ἐλεύθερον ἤδη εἶναι, THC. <i>7, 58,</i> or « néodamode » signifie « affranchi » ; τὸ κολάζειν τί ποτε δύναται ; PLAT. <i>Prot. 324</i> a, punir qu’est-ce que cela signifie ? τοῦτο γὰρ δύναται ὁ λόγος, PLAT. <i>Euthyd. 286</i> c, car voilà ce que signifie ce langage ; τοῦτο δύνανται αἱ ἀγγελίαι, THC. <i>6, 36,</i> voilà où tendent ces nouvelles ; <i>cf</i>. HDT. <i>2, 30 ; 4, 192 ; 6, 98 ;</i> ARSTT. <i>Rhet. 1, 9 ;</i> PAUS. <i>3, 11, 4 ; qqf. avec</i> λέγειν : τοῦτο δὲ δύναται βασιλέα λέγειν, EUN. <i>7 Boiss</i>. cela veut dire « roi » ;<br><b>      3</b> <i>en parl. de monnaies ou de nombres,</i> avoir une valeur : δύναται παρ' ἐκείνοις Ἀττικὸς ὀϐολός, LUC. <i>Luct. 10,</i> l’obole attique a cours (<i>litt</i>. a de la valeur) chez eux ; ὁ σίγλος δύναται ἑπτὰ ὀϐολοὺς καὶ ἡμιωϐόλιον, XÉN. <i>An. 1, 5, 6,</i> le sigle vaut sept oboles et demie ; τριηκόσιαι γενεαὶ δυνέαται μύρια ἔτεα, HDT. <i>2, 142,</i> trois cents générations équivalent à dix mille années ; <i>cf</i>. ARSTT. <i>Œc. 2, 20 ;</i> EL. <i>V.H. 1, 22 ; etc. ;</i><br><b>      4</b> <i>t. de math</i>. être élevé au carré : αὔξησις δυναμένη, PLAT. <i>Rsp. 546</i> b, quantité élevée au carré ; τριγώνου ὀρθογωνίου ἡ τὴν ὀρθὴν γωνίαν ὑποτείνουσα ἴσον δύναται ταῖς περιεχούσαις, ATH. <i>418</i> f, dans un triangle à angle droit le carré de l’hypoténuse est égal aux carrés des deux autres côtés ;<br><b>   III</b> pouvoir, consentir à, supporter de : σὲ οὐ δύναμαι προλιπεῖν δύστηνον ἐόντα, OD. <i>13, 331,</i> je ne puis pas t’abandonner malheureux comme tu es ; οὐκ ἔτι ἐδύνατο βιοτεύειν, THC. <i>1, 130,</i> il ne pouvait plus supporter de vivre (dans son ancien état) ;<br><b>   IV</b> pouvoir, <i>au sens d’un verbe auxiliaire, càd</i>. être capable de, être exposé à, SPT. <i>Sap. 11, 21 ;</i> ORIG. <i>1, 660</i> a ;<br><b>B</b> <i>impers</i>. δύναται, il est possible, <i>avec la prop. inf</i>. PLUT. <i>M. 440</i> e ; <i>avec l’inf</i>. τοῖσι Σπαρτιήτῃσι καλλιερῆσαι οὐκ ἐδύνατο, HDT. <i>7, 134 (cf. 9, 45</i>) il n’était pas possible aux Spartiates d’obtenir d’heureux présages.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 2 sg</i>. δύνασαι <span>[ᾰ]</span> IL. <i>1, 193 ;</i> OD. <i>4, 374 ;</i> PD. <i>P. 4, 158 ;</i> SOPH. <i>Aj. 1164 ;</i> AR. <i>Nub. 811, Pl. 574 ;</i> XÉN. <i>An. 7, 7, 8 ; Mem. 2, 8, 6 ;</i> PLAT. <i>Rsp. 400, etc. ; sel. Pors. Dind. Ellendt, etc. 2 sg. att</i>. δύνᾳ, SOPH. <i>Ph. 798 ;</i> EUR. <i>Hec. 253, Andr. 239 ; en poésie ou en prose réc. qqf</i>. δύνῃ, PYTHAG. <i>Aur. carm. 19 ;</i> EL. <i>V.H. 13, 32 ;</i> POL. <i>7, 11, 24, etc. ; dor</i>. δύνᾳ, THCR. <i>Idyl. 10, 2 ; 1 pl. poét</i>. δυνάμεσθα, IL. <i>2, 343, etc. ; 3 pl. ion</i>. δυνέαται, HDT. <i>4, 30 ; sbj. 2 sg</i>. δύνῃ, AR. <i>Eq. 491 ; épq</i>. δύνηαι, IL. <i>6, 229 ;</i> HÉS. <i>O. 350 ; 1 pl. ion</i>. δυνεώμεθα (<i>sel. d’autres</i> δυνώμεθα) HDT. <i>4, 97 ; 3 pl. ion</i>. δυνέωνται (<i>sel. d’autres</i> δύνωνται) HDT. <i>7, 163. Impf</i>. ἐδυνάμην, IL. <i>12, 417 ;</i> HÉS. <i>O. 134 ; touj. dans</i> HDT. <i>1, 26 ; 2, 29 ;</i> ATT. (AR. <i>Eccl. 316, 343 ;</i> THC. <i>2, 52 ; etc.) ; la forme att. primit. est</i> ἐδυνάμην, CIA. <i>2, 89, 5 (356/352 av. J.C</i>.) ; ἠδυνάμην <i>ne se rencontre qu’en poésie, par nécessité métrique, et dans les inscr. att. après 300 av. J.C. ;</i> ἠδύνατο, CIA. <i>2, 329, 12 (av. 250 av. J.C.) ; 331, 42 (av. 250 av. J. C</i>) ; ἠδύνατο, ἠδύναντο, CIA. <i>2, 420, 12, 37 (après 200 av. J.C.) ; poét</i>. δυνάμην, IL. <i>19, 136 ; 16, 509 ; dor. poét</i>. δυνάμαν, THCR. <i>Idyl. 2, 108 ; 2 sg</i>. ἐδύνω, XÉN. <i>An. 1, 6, 7 ; 7, 5, 5 ; ou</i> ἠδύνω, PHILIPPID. (<i>Com. fr. 4, 472) ; postér</i>. ἐδύνασο, LUC. <i>D. mort. 9, 1 ; 3 pl. ion</i>. ἐδυνέατο, HDT. <i>9, 70. — Fut</i>. δυνήσομαι, IL. <i>19, 163 ;</i> HDT. <i>8, 57 ;</i> ATT. (THC. <i>4, 60 ;</i> SOPH. <i>Ph. 742, etc.) ; f. dor</i>. δυνάσομαι <span>[ᾱ]</span> EUR. <i>Med. 862, ou</i> δυνασοῦμαι <span>[ᾱ]</span> HIPPODAM. (STOB. <i>Fl. 43, 93</i>) ; ARCHYT. (<i>ibid. 46, 61</i>) ; PHINTYS <i>(ibid. 74, 61).- Fut. réc</i>. δυνηθήσομαι (<i>sel. d’autres</i> δυνήσομαι) DC. <i>52, 37 ; 69, 4. — Ao. att</i>. ἐδυνήθην, XÉN. <i>Cyr. 3, 1, 30 ; An. 3, 1, 35 ;</i> SOPH. <i>Aj. 1067 ; etc. ; ou</i> ἠδυνήθην, ESCHL. <i>Pr. 206 ;</i> THC. <i>4, 43 ; 7, 25</i> (<i>var</i>. ἐδυν-) ; XÉN. <i>Mem. 3, 13, 6 ; Cyr. 5, 4, 31</i> (<i>var</i>. ἐδυν-) ; DÉM. <i>19, 209 ; 30, 1 Bkk. et Baiter-Sauppe ; ao. dor</i>. ἐδυνάθην <span>[ᾱ]</span> THCR. <i>Idyl. 11, 59 ; ion. et poét</i>. ἐδυνάσθην, IL. <i>23, 465 ;</i> OD. <i>5, 319 ;</i> PD. <i>O. 1, 56 ;</i> HDT. <i>2, 19 et 140 ; 7, 6 ; rar. en prose att</i>. XÉN. <i>Cyr. 1, 1, 5 ; 8, 2, 9 ; Mem. 1, 2, 24 ; Hell. 7, 3, 3 ; etc. ;</i> SOPH. <i>O.R. 1212. Ao. moy. épq. ou de prose réc</i>. ἐδυνησάμην, IL. <i>14, 33 ;</i> ARAT. <i>375, ou</i> δυνησάμην, IL. <i>5, 621 ; 13, 510 ; 14, 423 ;</i> OD. <i>17, 303 ;</i> ANTH. <i>7, 148. — Pf</i>. δεδύνημαι, DIN. <i>106, 35 ;</i> DÉM. <i>48, 16 ; 2 sg</i>. δεδύνησαι, A. CAR. (ATH. <i>345</i> d) ; <i>3 pl</i>. δεδύνηνται, GAL. <i>4, 307. - Fut. ant</i>. δεδυνήσομαι, SOPATER (<i>W. 8, 97</i>). — δυναμένοιο, <i>avec</i> ῡ <i>à l’arsis,</i> OD. <i>1, 276 ; 11, 414</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυναμαι - δύναμαι</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n210 fois dans 201 versets de 19 livres bibliques (NT)\n<ul>\n<li>Matthieu (27)</li>\n<li>Marc (33)</li>\n<li>Luc (26)</li>\n<li>Jean (37)</li>\n<li>Actes (21)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (15)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (5)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (3)</li>\n<li>Hébreux (9)</li>\n<li>Jacques (6)</li>\n<li>1 Jean (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (10)</li>\n</ul>\n</td></tr>\n</table>","G1411":"<h1>dunamis</h1>\n<p>Strong n° 1411 <i>Prononciation [doo'-nam-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>force, pouvoir, talent\n<ol type=\"a\">\n<li>pouvoir inhérent, par vertu ou par nature, que toute personne ou toute chose exerce</li>\n<li>pouvoir d'accomplir des miracles</li>\n<li>puissance morale et excellence de l'âme</li>\n<li>pouvoir et influence qui proviennent des richesses</li>\n<li>puissance et moyens provenant du nombre, de l'effectif</li>\n<li>pouvoir reposant sur les armées</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δύναμις, εως (ἡ)</b> <span>[ῠᾰ]</span> puissance, <i>càd. :</i><br><b>   I</b> faculté de pouvoir, OD. <i>2, 62, etc. ;</i> κατὰ δύναμιν, PLAT. <i>Phædr. 249</i> c ; κὰδ δύναμιν, HÉS. <i>O. 336 ;</i> πρὸς τὴν δύναμιν, PLAT. <i>Phædr. 231</i> a, autant qu’on peut ; κατὰ δύναμιν πᾶσαν, PLAT. <i>Leg. 865</i> e, de tout son pouvoir ; εἰς δύναμιν ὅτι μάλιστα, PLAT. <i>Rsp. 458</i> e ; κατὰ δύναμιν ὅτι μάλιστα, PLAT. <i>Pol. 279</i> c, le plus possible, tout le possible ; καὶ ποδὶ καὶ χειρὶ καὶ φωνῇ καὶ πάσῃ δυνάμει, ESCHN. <i>43, 17,</i> avec le pied, la main, la parole, par tous les moyens possibles ; εἰς δύναμιν παντὶ τρόπῳ, PLAT. <i>Rsp. 427</i> e, autant qu’on peut, par tous les moyens ; εἰς δύναμιν ἀνθρωπίνην, PLAT. <i>Leg. 697</i> b, autant qu’il est au pouvoir de l’homme ; παρὰ δύναμιν, THC. <i>1, 70 ;</i> ὑπὲρ δύναμιν, DÉM. <i>292, 25 ;</i> EPICT. <i>Ench. 31, 5,</i> au delà du possible ;<br><b>   II</b> <i>t. de philos</i>. puissance, <i>càd</i>. aptitude à être <i>ou</i> à devenir (<i>p. opp. à</i> ἐνέργεια, ἐντελέχεια) ARSTT. <i>An. post. 1, 24 fin ; Metaph. 3, 5, 1, etc. ;</i><br><b>   III</b> <i>abs</i>. pouvoir, puissance, force :<br><b>      1</b> force physique ; <i>d’ord. en ce sens dans Homère,</i> IL. <i>8, 294 ; joint à</i> χεῖρες, OD. <i>20, 237 ;</i> πὰρ δύναμιν, IL. <i>13, 787,</i> au-dessus des forces (de qqn) ; αἱ τοῦ σώματος δυνάμεις, PLAT. <i>Theæt. 185</i> e, <i>ou</i> σωματικὴ δύναμις, POL. <i>1, 69, 4 ; 37, 3, 5,</i> les forces du corps ;<br><b>      2</b> force morale (du caractère, de l’intelligence, de la parole, <i>etc</i>.) : αἱ σωματικαὶ καὶ θυμικαὶ δυνάμεις, POL. <i>6, 7, 3,</i> la force du corps et de l’âme ; ἡ τῶν λεγόντων δ. DÉM. <i>596, 21 ;</i> ἡ τῶν λόγων δ. ARSTT. <i>Rhet. 1, 1,</i> puissance des orateurs, de la parole ; ἡγεμονικὴ δ. POL. <i>10, 22, 4,</i> puissance morale du commandement, ascendant d’un général (<i>cf</i>. POL. <i>18, 11, 8</i>) ; δ. ἐν πραγματείᾳ, POL. <i>2, 56, 5,</i> puissance <i>ou</i> habileté (d’un historien) à traiter un sujet ; <i>abs</i>. faculté, art, science (rhétorique, logique, médecine) ARSTT. <i>Metaph. 4, 12, 11 ; Top. 1, 3 ;</i> ARR. <i>Epict. 1, 1, 1, etc. ;</i><br><b>      3</b> <i>en gén</i>. puissance des choses (forces de la nature, plantes, sol, <i>etc</i>.) : δ. τῶν φυομένων, XÉN. <i>Cyr. 8, 8, 74,</i> vertu des plantes ; <i>d’où abs. au plur</i>. plantes médicinales, PLUT. <i>M. 134</i> d ; φάρμακα καὶ δυνάμεις ἁπλαῖ, HPC. <i>Medic. p. 24,</i> les remèdes préparés et les simples ; δ. τῆς γῆς, XÉN. <i>Œc. 16, 4,</i> fécondité de la terre ; <i>p. anal</i>. action miraculeuse, miracle, NT. <i>Matth. 11, 20, etc. ;</i> efficacité d’un remède, HPC. <i>16, 15 ;</i> GAL. <i>7, 323, 327 ;</i> valeur d’une monnaie, THC. <i>6, 46 ;</i> PLUT. <i>Lyc. 9, Sol. 15 ;</i> valeur <i>ou</i> signification d’un mot, PLAT. <i>Crat. 394</i> b, <i>Phil. 24</i> c, <i>etc. ;</i> DÉM. <i>9, 16 Baiter-Sauppe ;</i> POL. <i>3, 20, 5 ; 20, 9, 11 ; t. d’arithm</i>. puissance d’un nombre, <i>particul</i>. le carré, PLAT. <i>Theæt. 147</i> d ; THEOL. <i>4 ; p. opp. à</i> κύϐος <i>et à</i> δυναμοδύναμις, DIOPH. <i>2 ; — ou</i> le produit d’un nombre, PHIL. <i>1, 3 ; — ou</i> le dernier terme d’une progression arithmétique par rapport au total, <i>p. ex. 4 est la</i> δύναμις <i>de 10, parce que 1 + 2 + 3 + 4 = 10,</i> PLUT. <i>M. 877</i> a ;<br><b>      4</b> force militaire, forces, troupes, <i>au sg</i>. HDT. <i>5, 100 ;</i> XÉN. <i>An. 1, 1, 6 ; etc. ;</i> PLAT. <i>Menex. 240</i> d ; POL. <i>1, 41, 2, etc. ;</i> δ. καὶ πεζὴ καὶ ἱππικὴ καὶ ναυτική, XÉN. <i>An. 1, 3, 12,</i> forces en infanterie, en cavalerie et en vaisseaux ; <i>au plur</i>. POL. <i>2, 1, 5, etc. ;</i><br><b>   IV</b> <i>abs</i>. la puissance, le pouvoir, HDT. <i>1, 90 ;</i> ESCHL. <i>Pers. 174, Ag. 779 ;</i> θεῶν δύναμις, EUR. <i>Alc. 219,</i> le pouvoir des Dieux ; ἐν δυνάμει εἶναι, XÉN. <i>Hell. 4, 4, 5, ou</i> γίγνεσθαι, DÉM. <i>174, 27,</i> être <i>ou</i> devenir puissant ; αἱ δυνάμεις, moyens d’influence, instruments de puissance, PLAT. <i>Rsp. 447</i> c ; <i>joint à</i> χρήματα, <i>ibid. 423</i> e (<i>cf. ibid. 364</i> a) ; <i>p. ext. en parl. de pers</i>. αἱ δυνάμεις <i>avec ou</i> sans τῶν οὐρανῶν, les puissances célestes, SPT. <i>3Reg. 17, 1 ; Esaï. 34, 4 ;</i> NT. <i>Matth. 24, 29 ; en parl. des anges,</i> PHIL. <i>1, 587</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. ion</i>. δυνάμιος, HDT. <i>3, 88, etc</i>.<br><span><b>Étym</b>. δύναμαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυναμις - δύναμις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – force, puissance, pouvoir souvent oppressif s'exerçant par des actes de violence.\n<br><br> – puissance, capacité naturelle, générale et inhérente.\n<br><br> – action, efficacité, pouvoir dans l'exercice, pouvoir opérant  – d'abord liberté d'action ; donc autorité – soit un pouvoir qui a été délégué, ou un pouvoir sans restriction, arbitraire.\n<br><br> – force, vertu, puissance (spécialement physique), comme reçue en don.\n<br><br> – puissance, force souveraine, le pouvoir manifesté ; – dans le NT il s'agit surtout de la force et du pouvoir de Dieu.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n120 fois dans 116 versets de 18 livres bibliques (NT)\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (10)</li>\n<li>Luc (15)</li>\n<li>Actes (10)</li>\n<li>Romains (8)</li>\n<li>1 Corinthiens (15)</li>\n<li>2 Corinthiens (10)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (5)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (3)</li>\n<li>2 Timothée (3)</li>\n<li>Hébreux (6)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (3)</li>\n<li>Apocalypse (12)</li>\n</ul>\n</td></tr>\n</table>","G1412":"<h1>dunamoo</h1>\n<p>Strong n° 1412 <i>Prononciation [doo-nam-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rendu fort, confirmé, fortifié, rendre puissant, renforcé, revigorer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυναμόω-ῶ</b> <span>[ῠᾰ]</span> fortifier, rendre puissant, SPT. <i>Ps. 67, 29 ; Eccl. 10, 10 ; Dan. 2, 27 ;</i> AQU. <i>Job 36, 9 ;</i> NYSS. <i>3, 1109 a Migne</i>.<br><span><b>Étym</b>. δύναμις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυναμοω - δυναμόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1413":"<h1>dunastes</h1>\n<p>Strong n° 1413 <i>Prononciation [doo-nas'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un prince, un potentat, personnage puissant, dominateur</li>\n<li>grand officier, ministre royal de grande autorité</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυνάστης, ου (ὁ)</b> <span>[ῠ]</span> tout homme qui a une part de souveraineté, <i>particul. :</i><br><b>      1</b> chef <i>ou</i> gouverneur d’une ville, d’un territoire ; <i>joint à</i> τυράννων καὶ βασιλέων, PLAT. <i>Gorg. 525</i> d ; <i>à</i> βασιλῆς, PLAT. <i>Rsp. 473</i> d ;<br><b>      2</b> <i>post</i>. petit prince, principicule (<i>d’Espagne, d’Illyrie, de Thrace etc</i>.) POL. <i>4, 45, 2 ; 5, 4, 3 ; 5, 34, 7 ; 5, 90, 1 ; 10, 34, 2, etc. ;</i><br><b>      3</b> <i>p. ext</i>. roi, souverain, <i>en gén. (après</i> ἐθνῶν καὶ πόλεων) POL. <i>9, 1, 4 ;</i><br><b>      4</b> <i>abs</i>. maître souverain, <i>en parl. de Zeus,</i> SOPH. <i>Ant. 608 ; fig. en parl. des astres,</i> ESCHL. <i>Ag. 6</i>.<br><span><b>Étym</b>. δύναμαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυναστης - δυνάστης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1414":"<h1>dunateo</h1>\n<p>Strong n° 1414 <i>Prononciation [doo-nat-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir du pouvoir, être puissant</li>\n<li>montrer son propre pouvoir</li>\n<li>être capable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυνατέω-ῶ</b> (<i>seul. prés</i>. -εῖ) <span>[ῠᾰ]</span> être puissant, NT. <i>2Cor. 13, 3</i>.<br><span><b>Étym</b>. δυνατός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυνατεω - δυνατέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1415":"<h1>dunatos</h1>\n<p>Strong n° 1415 <i>Prononciation [doo-nat-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>capable, puissant, fort\n<ol type=\"a\">\n<li>puissant en richesse et influence</li>\n<li>fort dans l'âme\n<ol>\n<li>supporter calamités et épreuves avec patience</li>\n<li>fort dans la vertu Chrétienne</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>être capable (de faire quelque chose)\n<ol type=\"a\">\n<li>puissant, qui excelle dans quelque chose</li>\n<li>ayant du pouvoir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυνατός, ή, όν</b> <span>[ῠᾰ]</span><br><b>   I</b> qui peut, <i>càd. :</i><br><b>      1</b> capable de : δ. πρός τι, XÉN. <i>Œc. 7, 23,</i> apte à qqe ch. ; <i>avec l’inf</i>. PD. <i>O. 10, 11 ;</i> λέγειν τε καὶ πράσσειν δυνατώτατος, THC. <i>1, 139,</i> tout à fait capable de parler et d’agir ; <i>cf</i>. PLAT. <i>Gorg. 319</i> a ; δυνατώτατός τε καὶ σοφώτατος κατὰ ταῦτα, PLAT. <i>Hipp. mi. 366</i> d, très capable et très habile en ces matières ; <i>avec le gén</i>. δυνατοὶ πολέμου, SPT. <i>Par. 2, 17, 18,</i> capables de faire la guerre ; <i>cf. ibid. 1, 12, 14 ;</i><br><b>      2</b> <i>abs</i>. qui peut remplir son office, <i>en parl. d’animaux et de choses :</i> ἵππος δ. XÉN. <i>Hipp. 3, 9,</i> bon cheval ; ναῦς δ. THC. <i>7, 60,</i> navire capable de tenir la mer ; προτείχισμα δ. POL. <i>10, 31, 8,</i> rempart solide ; χώρα δ. GEOP. <i>2, 21,</i> terre capable de produire, <i>p. opp. à</i> ἀδυνατοῦσα ; <i>en parl. de pers</i>. fort, vigoureux : δ. τοῖς σώμασι καὶ ταῖς ψυχαῖς, XÉN. <i>Mem. 2, 1, 19,</i> vigoureux de corps et d’âme ; <i>cf</i>. PD. <i>N. 9, 92 ;</i> XÉN. <i>Hipp. 1, 9 ;</i><br><b>      3</b> <i>p. suite, en gén</i>. puissant, influent (par le rang, la fortune, <i>etc</i>.) ; δ. χρήμασι, THC. <i>1, 13 ;</i> PLAT. <i>Lach. 186</i> c, puissant par la fortune ; ἄνδρες δυνατοί, XÉN. <i>Cyr. 5, 4, 1 ; ou abs</i>. οἱ δυνατοί, les riches, THC. <i>2, 65 ; ou</i> les puissants, les grands, XÉN. <i>Ath. 1, 3 ;</i> PLAT. <i>Pol. 308</i> a ; SOPH. <i>El. 219 ;</i> οἱ Ἑλλήνων δυνατώτατοι, HDT. <i>1, 53,</i> les plus puissants des Grecs ;<br><b>   II</b> ce qui se peut, possible, PLUT. <i>M. 8</i> f, <i>etc. ;</i> ὁδὸς δυνατὴ καὶ ὑποζυγίοις πορεύεσθαι, XÉN. <i>An. 4, 1, 24,</i> route praticable même aux bêtes de somme ; δυνατόν ἐστι, <i>avec l’inf</i>. il est possible de, <i>etc</i>. PD. <i>N. 10, 84 ;</i> ESCHL. <i>Ag. 97 ;</i> PLAT. <i>Leg. 839</i> c ; <i>avec un dat</i>. ποῖ μολεῖν μοι δυνατόν ; SOPH. <i>Aj. 1006,</i> où m’est-il possible d’aller ? <i>cf</i>. HDT. <i>9, 111 ;</i> DH. <i>3, 29, etc. ; abs</i>. οὐχὶ ἐσώσαμέν σε, οἷον τε ὂν καὶ δυνατόν, PLAT. <i>Crit. 46</i> a, nous ne t’aurons pas (<i>litt</i>. nous ne t’avons pas) sauvé, lorsque cela était possible et en notre pouvoir ; <i>adv</i>., ἐπὶ τὸ δυνατόν, XÉN. <i>Cyn. 5, 8 ;</i> εἰς τὸ δυνατόν, XÉN. <i>Cyr. 2, 1, 22 ; Mem. 3, 3, 4 ;</i> PLAT. <i>Rsp. 381</i> c, <i>500</i> d ; κατὰ τὸ δυνατόν, PLAT. <i>Conv. 207</i> d ; κατά γε τὸ δ. PLAT. <i>Crat. 435</i> c ; <i>ou</i> ἐκ τῶν δυνατῶν, XÉN. <i>An. 4, 2, 23 ; Œc. 7, 11,</i> selon le possible ; ὅσον γε δυνατόν, EUR. <i>I.A. 997 ;</i> ὅσον καθ' ἡμᾶς δυνατόν, EUR. <i>Bacch. 183 ; avec un</i> <i>• Sup</i>. ὡς δυνατὸν πλεῖστον, ISOCR. <i>284</i> e, autant que possible, le plus possible ; <i>avec un adj. au</i> <i>• Sup</i>. ὡς δυνατὸν κάκιστους, XÉN. <i>Mem. 4, 5, 5,</i> les plus mauvais possible ; γνώμην ὡς δυνατὸν δικαιοτάτην, DÉM. <i>704, 6,</i> l’avis le plus juste possible.<br><span>•<i> Cp</i>. -ώτερος, XÉN. <i>Cyr. 5, 2, 28 ;</i> PLAT. <i>Lach. 186</i> c, <i>etc.</i> <i>• Sup</i>. -ώτατος, HDT. <i>1, 53 ;</i> XÉN. <i>Ath. 1, 3 ;</i> HIPP. <i>1, 9 ;</i> PLAT. <i>Gorg. 319</i> a, <i>Hipp. mi. 366</i> d, <i>etc. ; cf. ci-dessus</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, PD. <i>N. 2, 21</i>.<br><span><b>Étym</b>. <i>vb. de</i> δύναμαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυνατος - δυνατός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n34 fois dans 34 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (5)</li>\n<li>Luc (4)</li>\n<li>Actes (5)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (4)</li>\n<li>Galates (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1416":"<h1>duno</h1>\n<p>Strong n° 1416 <i>Prononciation [doo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>entrer, rentrer</li>\n<li>aller sous, être plongé dans, enfoncer dans\n<ol type=\"a\">\n<li>utilisé dans le N.T pour le coucher du soleil</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δύνω</b> (<i>seul. prés. impf. et ao</i>.) <span>[ῡ]</span><br><b>      1</b> s’enfoncer, se plonger : πόντον, IL. <i>15, 219 ;</i> ἐς θάλασσαν, HDT. <i>8, 8,</i> dans la mer ; <i>particul. en parl. des astres :</i> δύνοντος ἡλίου, XÉN. <i>An. 2, 2, 3 ;</i> ESCHN. <i>2, 32 (loi), etc. litt</i>. le soleil se plongeant (dans la mer), <i>càd</i>. au coucher du soleil ; ἡλίου δύναντος, POL. <i>9, 15, 9 ;</i> EL. <i>V.H. 4, 1 ;</i> PAUS. <i>2, 11, 7,</i> après le coucher du soleil ;<br><b>      2</b> <i>p. suite,</i> pénétrer dans, entrer dans : δ. δόμον, OD. <i>7, 81,</i> s’engager dans une maison ; <i>en parl. de vêtements, d’armures :</i> ἔντεα, τεύχεα δύνειν, HOM. <i>ou</i> ἐν τεύχεσσιν δύνειν, IL. <i>23, 131,</i> revêtir des armes ; <i>fig</i>. ἄχος ἔδυνεν ἦτορ, IL. <i>19, 367 ;</i> ὀδύναι δῦνον μένος, IL. <i>11, 268,</i> la douleur pénétra dans son cœur ;<br><b><i>Moy.</i></b> (<i>seul. part. prés</i>.) se plonger dans, CALL. <i>Epigr. 19, 6 ; 21, 2</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind</i>. IL. <i>17, 202 ;</i> HÉS. <i>Sc. 151, etc. ; sbj. 3 sg</i>. δύνῃ, SOPH. <i>Ph. 1331 ; 3 pl</i>. δύνωσι, HÉS. <i>O. 616 ; inf</i>. δύνειν, CALL. <i>Epigr. 26 ; part</i>. δύνοντος, ESCHL. <i>Suppl. 255 ;</i> EUR. <i>Ph. 1117 ; cf. ci-dessus. — Impf</i>. ἔδυνον, IL. <i>3, 339 ; poét</i>. δῦνον, IL. <i>11, 268 ;</i> ORPH. <i>Arg. 539. — Ao. réc</i>. ἔδυνα, BATR. <i>242, 256 ; part</i>. δύναντος (<i>v. ci-dessus</i>).<br><span><b>Étym</b>. δύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυνω - δύνω</font>\n<br><br>forme d'un mot non usuel « duo » (doo'-o) (enfoncer)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1417":"<h1>duo</h1>\n<p>Strong n° 1417 <i>Prononciation [doo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>les deux, deux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δύο</b>, <i>gén.-dat</i>. δυοῖν (<i>v. ci-dessous la décl. ; indécl. dans Homère</i>) :<br><b>      1</b> <i>n. de n</i>. deux, <i>avec un subst. masc. fém. ou neutre, d’ord. au duel,</i> HOM. ATT. ; <i>qqf. au plur. dans Homère</i> (δύο ἄνδρες, IL. <i>18, 498 ;</i> δύ' οἴους, OD. <i>3, 424 ; 12, 154 ;</i> δύο ἤματα, OD. <i>10, 142) ; et dans les Att</i>. (δύο κριούς, SOPH. <i>Aj. 237 ;</i> δύο ψυχάς, EUR. <i>Alc. 900 ;</i> δύο ἡλίους, EUR. <i>Bacch. 916 ;</i> δύο ἄνδρας, XÉN. <i>An. 4, 1, 12 ;</i> δύο τέχνας, PLAT. <i>Gorg. 464</i> b ; δυοῖν μιασμάτων, ESCHL. <i>Eum. 600 ;</i> δυοῖν οἰμώγμασιν, ESCHL. <i>Ag. 1384 ; etc.) ; pour l’emploi du duel <i>ou</i> du pluriel avec</i> δύο <i>dans les inscr. att. on peut distinguer cinq périodes : 1° jusqu’en 409 av. J.C. le duel seul us. ; — 2° de 409 à 378 av. J.C. le plur. qqf. us. ; — 3° de 378 à 329 av. J.C. le plur. plus us. que le duel (dans une inscr. de 373 av. J.C. un accus. duel, 21 nom. ou accus. plur</i>.) ; — <i>4° de 329 à 30 av. J.C. (époque macédonienne) le plur. presque seul us. ; — 5° à l’époque romaine, par imitation des écrivains classiques, le duel redevient la forme usuelle (v. Meisterhans, p. 161 et suiv.). Lorsque</i> δύο <i>est précédé d’un n. de nombre au plur. le subst. se construit au duel :</i> πεντακοσίαις εἴκοσι δυοῖν δραχμαῖν, CIA. <i>1, 273 f, 31 (426/422 av. J.C</i>.) 522 drachmes (<i>v. Meisterhans, p. 161</i>) ; ἕνα καὶ δύο, IL. <i>2, 346 ; ou</i> δύ' ἢ τρεῖς, AR. <i>Pax 829 ;</i> δύο ἢ τρεῖς, XÉN. <i>Hell. 3, 5, 20 ;</i> δύο ἢ τρία, XÉN. <i>Cyr. 5, 4, 4,</i> un ou deux, deux ou trois, <i>pour marquer une petite quantité indéterminée ;</i> εἶς δύο, XÉN. <i>Cyr. 7, 5, 17 ;</i> δύο δύο, SPT. <i>Gen. 7, 2,</i> deux par deux ; δυοῖν θάτερον ἤ… ἤ… DÉM. <i>274, 10,</i> de deux choses l’une, ou… ou… ; δυοῖν… ἢ γὰρ… ἤ, DÉM. <i>388, 16,</i> de deux choses l’une : en effet, ou… ou, <i>etc. ;</i> δύο ποιεῖν τὴν πόλιν, ARSTT. <i>Pol. 5, 9, 10,</i> diviser l’État en deux partis, y créer des divisions ;<br><b>      2</b> <i>abs. pour marquer</i> deux parties (sur trois), <i>càd</i>. les deux tiers, THC. <i>2, 2, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Poét</i>. δύω, IL. <i>1, 16 ;</i> HÉS. <i>O. 12 ;</i> THGN. <i>955 ;</i> THCR. <i>Idyl. 22, 137 ;</i> ANTH. <i>13, 14 ;</i> LUC. <i>Trag. 212</i>. δύο (<i>poét</i>. δύω) <i>indécl. dans</i> HOM. HDT. <i>et qqf. les Att. : gén</i>. δύο μοιράων, IL. <i>10, 253 ;</i> δύω ποταμῶν, OD. <i>10, 515 ;</i> μετὰ δύο τῶν σφετέρων, HDT. <i>7, 149 ;</i> δύο νηῶν, HDT. <i>8, 82 ;</i> δύο νεῶν, THC. <i>3, 89 ;</i> ἐτῶν δύο καὶ τριῶν, THC. <i>1, 82 ; dat</i>. δύω κανόνεσσι, IL. <i>13, 407 ;</i> δύο ζεύγεσι, HDT. <i>3, 130 ;</i> δύο μναῖν, XÉN. <i>Mem. 2, 5, 2 ;</i> δύο συνέργοις, POL. <i>2, 38, 8 ; etc. — Décl. régul. : nom</i>. δύο, <i>poét</i>. δύω (<i>v. ci-dessus). — Gén</i>. δυοῖν (ποδῶν δυοῖν, PD. <i>N. 8, 82 ;</i> δυοῖν μιασμάτων, ESCHL. <i>Eum. 600, etc. cf. ci-dessus) ; ion</i>. δυῶν, HDT. <i>1, 94, 130, etc. dout. ; dans les inscr. att. (v. Meisterhans, p. 124, § 60</i>), δυοῖν <i>seul us. j. en 329 av. J.C. ; de 329 à 229 av. J.C</i>. δυεῖν CIA. <i>2, 167, 78 (pas av. 307 av. J.C.) ; 2, 281, 5 (époque macédonienne) ; 1138, 7 (302 av. J.C.) ; 380, 27 (229 av. J.C.) ; à l’époque romaine</i> δύο, CIA. <i>3, 1443, etc. ; de même</i> δύο <i>en poésie,</i> KE. <i>149, 5. — Dat</i>. δυοῖν (πόλεσι δυοῖν, PLAT. <i>Leg. 638</i> e ; δυοῖν ὀνόμασι, PLAT. <i>Pol. 291</i> e, <i>etc.) ; ion</i>. δυοῖσι, HDT. <i>1, 32, 7, 104 dout. ; dans les inscr. att</i>. δυοῖν <i>seul us. j. en 329 av. J.C. ; de 329 à 229 av. J.C</i>. δυεῖν (<i>contrair. à la doctrine de</i> PHRYN. <i>210 ; du</i> SCH.-EUR. <i>Hec. 45</i>) CIA. <i>2, 591, 4 (av. 300 av. J.C.) ; à l’époque romaine</i> δυσί, CIA. <i>2, 467, 27 ; 469, 76 (1<sup>er</sup> siècle av. J.C.) ; etc. ; déjà us. depuis Aristote,</i> ARSTT. <i>Pol. 3, 6, 7 ; etc. et en poésie,</i> KE. <i>199, 3. — Acc</i>. δύο, <i>poét</i>. δύω (δύο κρίους, SOPH. <i>Aj. 237 ;</i> δύο ἄνδρας, XÉN. <i>An. 4, 1, 12 ;</i> δύω κακά, THGN. <i>955 ; cf. ci-dessus</i>). — δυοῖν <i>monosyll</i>. SOPH. <i>O.R. 640</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *duu̯o, *duu̯-eh₃-, deux ; <i>cf</i>. δίς, <i>lat</i>. dŭŏ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυο - δύο</font>\n<br><br>nombre primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nombre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n134 fois dans 123 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (40)</li>\n<li>Marc (18)</li>\n<li>Luc (27)</li>\n<li>Jean (13)</li>\n<li>Actes (13)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (11)</li>\n</ul>\n</td></tr>\n</table>","G1418":"<h1>dus-</h1>\n<p>Strong n° 1418 <i>Prononciation [doos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>préfixe contenant l'idée de difficulté, d'opposition, similaire à nos préfixes « més- » ou « in- » (mésentente, inaction...)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυσ–</b> <span>[ῠ]</span> <i>préfixe marquant une idée de difficulté, de malheur, c</i>. δυσάγγελος, δύσαγνος, <i>etc</i>.<br><span><b>Étym</b>. <i>p.-ê. de même orig. que la rac. sscrite</i> dush, gâter.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυς - δυσ-</font>\n<br><br>particule primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Particule</td></tr>\n</table>","G1419":"<h1>dusbastaktos</h1>\n<p>Strong n° 1419 <i>Prononciation [doos-bas'-tak-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lourd, encombrant, difficile à porter, à supporter, accablant, insupportable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυσ·ϐάστακτος, ος, ον</b>, difficile à supporter, accablant, PLUT. <i>M. 915</i> f ; SPT. <i>Prov. 27, 3 ;</i> NT. <i>Matth. 23, 4 ; fig. en parl. de choses,</i> CHRYS. <i>2, 512 ; en parl. de pers</i>. insupportable, PHIL. <i>2, 449</i>.<br><span><b>Étym</b>. δ. βαστάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυσβαστακτος - δυσβάστακτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1420":"<h1>dusenteria</h1>\n<p>Strong n° 1420 <i>Prononciation [doos-en-ter-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dysenterie, indisposition des entrailles, perte de sang</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυσ·εντερία, ας (ἡ)</b> <span>[ῠ]</span> dysenterie, affection des intestins, HDT. <i>8, 115 ;</i> HPC. <i>1161</i> e ; PLAT. <i>Tim. 86</i> a, <i>Theæt. 142</i> b ; ARSTT. <i>H.A. 10, 7, 1 ;</i> POL. <i>32, 25, 14</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HDT. HPC. <i>ll. cc</i>.<br><span><b>Étym</b>. δ. ἔντερα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυσεντερια - δυσεντερία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1421":"<h1>dusermeneutos</h1>\n<p>Strong n° 1421 <i>Prononciation [doos-er-mane'-yoo-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dur à interpréter, difficile à expliquer, obscur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυσ·ερμήνευτος, ος, ον</b> <span>[ῠ]</span> difficile à expliquer, obscur, DS. <i>2, 52 ;</i> NT. <i>Hebr. 5, 11 ;</i> PHIL. <i>1, 649</i>.<br><span><b>Étym</b>. δ. ἑρμηνεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυσερμηνευτος - δυσερμήνευτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1422":"<h1>duskolos</h1>\n<p>Strong n° 1422 <i>Prononciation [doo'-kol-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>difficile sur la nourriture</li>\n<li>difficile sur tout, trouvant toujours des défauts</li>\n<li>une chose difficile</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δύσ·κολος, ος, ον :<br>   I</b> dont l’estomac est difficile, ATH. <i>262</i> a ;<br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> d’humeur difficile, morose, chagrin, <i>en parl. de pers. joint à</i> ἀηδής <i>et à</i> δύσερις, ARSTT. <i>Nic. 4, 6 ; à</i> δύστροπος, DÉM. <i>73, 5 ; à</i> χαλεπός, AR. <i>Vesp. 942 ; à</i> ὀξύθυμος, AR. <i>Vesp. 1104 ; en parl. d’un animal rétif,</i> PLAT. <i>Theæt. 174</i> d ; <i>en parl. de choses</i> (âme, vieillesse) PLAT. <i>Leg. 649</i> e, <i>etc. ;</i> EUR. <i>Bacch. 1249 ;</i><br><b>      2</b> <i>p. suite, en parl. de choses,</i> déplaisant, désagréable, DÉM. <i>286, 25 ; 291, 21, 174</i> d ; <i>particul. en parl. de maladies ou d’infirmités, p. opp. à</i> « dangereux, mortel », <i>etc</i>. HPC. <i>77</i> g ; <i>synon. de</i> ἀκίνδυνος, <i>ibid</i>.<br><span>•<i> Cp</i>. -ώτερος, AR. <i>Vesp. 1104 ;</i> PLAT. <i>Theæt. 174</i> d, <i>etc</i>.<br><span><b>Étym</b>. <i>p.-ê. p</i>. *δύσπολος, inabordable <i>de</i> δ. πέλομαι ; <i>cf</i>. βουκόλος <i>et</i> αἰπόλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυσκολος - δύσκολος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G1423":"<h1>duskolos</h1>\n<p>Strong n° 1423 <i>Prononciation [doos-kol'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avec difficulté, dans des dispositions chagrines</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυσκόλως</b>, <i>adv. :</i><br><b>      1</b> dans des dispositions chagrines, PLAT. <i>Phæd. 84</i> e ; ISOCR. <i>190</i> b ; DÉM. <i>381, 29 ;</i> δ. διακεῖσθαι πρός τινα, ISOCR. <i>33</i> d, <i>ou</i> ἔχειν, ISOCR. <i>161</i> e, être mal disposé pour qqn ; <i>p. opp. à</i> εὔνουν εἶναι, ISOCR. <i>169</i> e ; δ. ἔχειν πρός τι, ISOCR. <i>67</i> c, être mal disposé pour qqe ch. ;<br><b>      2</b> difficilement, NT. <i>Marc. 10, 23</i>.<br><span>•<i> Cp</i>. -ώτερον, PLAT. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυσκολως - δυσκόλως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1424":"<h1>dusme</h1>\n<p>Strong n° 1424 <i>Prononciation [doos-may']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le côté du coucher du soleil</li>\n<li>le coucher du soleil, l'ouest</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυσμή, ῆς (ἡ)</b> <i>seul. plur. :</i><br><b>      1</b> le coucher du soleil, des astres : μικρὸν πρὸ ἡλίου δυσμῶν, XÉN. <i>Hell. 5, 1, 7,</i> peu avant le coucher du soleil ; ἐπὶ δυσμῇσιν, HDT. <i>3, 104,</i> au coucher du soleil ; περὶ ἡλίου δυσμάς, LYS. <i>95, 22,</i> vers le coucher du soleil ; <i>fig</i>. déclin de la vie, EMPÉD. (ARSTT. <i>Poet. 21, 13</i>) ; DH. <i>2, 827 Reiske ;</i> SEXT. <i>411, 25 Bkk. ;</i> CLÉM. <i>1, 224 Migne ;</i><br><b>      2</b> <i>p. ext</i>. la région où le soleil se couche, le couchant, occident : ἀπὸ ἑσπέρης τε καὶ ἡλίου δυσμέων (<i>ion</i>.) HDT. <i>2, 31,</i> du midi et du couchant ; <i>cf</i>. HDT. <i>7, 115 ;</i> ESCHL. <i>Pers. 237</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Sg. seul. dor</i>. δυθμή, CALL. (SCH.-IL. <i>11, 62</i>).<br><span><b>Étym</b>. δύνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυσμη - δυσμή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1425":"<h1>dusnoetos</h1>\n<p>Strong n° 1425 <i>Prononciation [doos-no'-ay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>difficile à comprendre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυσνόητος, ος, ον</b>, difficile à comprendre, DL. <i>9, 13 ;</i> NT. <i>2Petr. 3, 16</i>.<br><span><b>Étym</b>. δυσνοέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυσνοητος - δυσνόητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1426":"<h1>dusphemia</h1>\n<p>Strong n° 1426 <i>Prononciation [doos-fay-mee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la condition de celui qui est diffamé\n<ol type=\"a\">\n<li>action de celui qui utilise un langage honteux, calomnie, injure</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δυσφημία, ας (ἡ) :<br>   I</b> <i>act. :</i><br><b>      1</b> parole de mauvais augure, SOPH. <i>Ph. 10,</i> PLUT. <i>M. 587</i> f ;<br><b>      2</b> blasphème, DH. <i>6, 48 ; d’où</i> injure, mauvais propos, <i>en gén</i>. D. PHAL. <i>§ 326 ;</i> ARSTD. <i>t. 2, 482 ;</i><br><b>   II</b> <i>pass</i>. mauvaise réputation, SOPH. <i>fr. 185 au plur</i>.<br><span><b>Étym</b>. δύσφημος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δυσφημια - δυσφημία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1427":"<h1>dodeka</h1>\n<p>Strong n° 1427 <i>Prononciation [do'-dek-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>douze\n<ol type=\"a\">\n<li>les douze apôtres de Jésus, ceux qui ont été appelés</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δώδεκα (οἱ, αἱ, τὰ</b>) <span>[ᾰ]</span> <i>indécl</i>. douze, IL. <i>6, 248 ;</i> OD. <i>10, 5 ;</i> ATT. <i>etc. ;</i> οἱ δ. πίνακες <i>ou</i> αἱ δ. δέλτοι, DS. <i>2, 26 ;</i> DH. <i>1, 295, 7 Reiske, etc</i>. les Douze tables, la loi des Douze tables, <i>à Rome</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att</i>. δώδεκα <i>se construit tantôt avant, tantôt après le subst</i>. δώδεκα θεοῖς, CIA. <i>2, 652 b, 57, 7 (362 av. J.C.) etc. ;</i> κρατευταὶ δώδεκα, CIA. <i>1, 319, 13 (420/410 av. J.C.) etc. (v. Meisterh. p. 126, 9) ; vers la fin du 2<sup>e</sup> siècle ou le commencement du 1<sup>er</sup> av. J.C. on rencontre l’équival</i>. δέκα δύο, CIA. <i>2, 476, 31 (v. Meisterh. ibid. ; cf. Riemann, Rev. de phil. 5, 164</i>).<br><span><b>Étym</b>. δύο, δέκα ; <i>cf</i>. δυόδεκα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δωδεκα - δώδεκα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom indéclinable</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n70 fois dans 57 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (14)</li>\n<li>Luc (11)</li>\n<li>Jean (6)</li>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (22)</li>\n</ul>\n</td></tr>\n</table>","G1428":"<h1>dodekatos</h1>\n<p>Strong n° 1428 <i>Prononciation [do-dek'-at-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un douzième</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δωδέκατος, η, ον</b> <span>[ᾰ]</span> douzième, IL. <i>1, 425, etc. ;</i> OD. <i>4, 747 ;</i> SOPH. <i>Tr. 825 ;</i> PLAT. <i>Leg. 758</i> b, <i>etc</i>.<br><span><b>Étym</b>. δώδεκα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δωδεκατος - δωδέκατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1429":"<h1>dodekaphulon</h1>\n<p>Strong n° 1429 <i>Prononciation [do-dek-af'-oo-lon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>les douze tribus, pour l'ensemble du peuple Israélite</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δωδεκά·φυλος, ος, ον</b> <span>[ᾰῡ]</span> de douze tribus, SIB. <i>2, 171 ;</i> τὸ δ. NT. <i>Ap. 26, 7,</i> les douze tribus d’Israël.<br><span><b>Étym</b>. δ. φυλή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δωδεκαφυλον - δωδεκάφυλον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1430":"<h1>doma</h1>\n<p>Strong n° 1430 <i>Prononciation [do'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une construction, une maison</li>\n<li>une pièce de la maison, salle à manger, couloir</li>\n<li>le sommet de la maison, le toit\n<ol type=\"a\">\n<li>les toits orientaux, en terrasses, étaient (et sont encore) utilisés pour se reposer, mais aussi pour la méditation et la prière</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δῶμα, ατος (τὸ) :<br>A</b> construction, <i>d’où :</i><br><b>   I</b> maison, demeure, <i>en parl. des dieux et des hommes,</i> IL. <i>5, 907, etc. ;</i> OD. <i>4, 46, etc. ; plur. au sens du sg. :</i> IL. <i>1, 600, etc. ;</i> OD. <i>4, 811, etc. ;</i> δῶμ' Ἀΐδαο, OD. <i>12, 21,</i> Ἀΐδου, SOPH. <i>El. 110 ;</i> Πλούτωνος, EUR. <i>H.f. 808,</i> demeure d’Hadès, de Pluton, <i>càd</i>. les enfers ; <i>particul. :</i><br><b>      1</b> chambre principale, salle où l’on se réunit = μέγαρον, IL. <i>6, 316 ;</i> OD. <i>17, 541 ; 22, 494, etc. ;</i><br><b>      2</b> salle pour les repas, CALL. <i>Cer. 64 ;</i><br><b>      3</b> temple, PD. <i>P. 4, 95 ;</i> ESCHL. <i>Eum. 242, Suppl. 291 ;</i> SOPH. <i>O.R. 71 ;</i><br><b>      4</b> <i>p. ext</i>. demeure, <i>en gén. d’où</i> ville, cité, SOPH. <i>O.R. 29 ;</i><br><b>   II</b> toit plat des maisons orientales servant de terrasse, SPT. <i>Deut. 22, 8 ; Jos. 2, 6 ; 1Reg. 9, 25 ; 2, 11, 2 ; etc. ;</i> NT. <i>Matth. 24, 17 ; Marc. 13, 15 ; Luc. 12, 3, etc. ;</i><br><b>B</b> <i>fig</i>. maison, famille, ESCHL. <i>Ag. 1468, Eum. 354 ;</i> SOPH. <i>O.R. 1226 ;</i> EUR. <i>Hec. 624, Or. 61</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *dem-, maison ; <i>cf</i>. δεσπότης, δέμω, δόμος, <i>v</i>. δῶ 1.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δωμα - δῶμα</font>\n<br><br>vient de demo (bâtir)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1431":"<h1>dorea</h1>\n<p>Strong n° 1431 <i>Prononciation [do-reh-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un don, présent, gratification</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δωρεά, ᾶς (ἡ) :<br>      1</b> don, présent, gratification (<i>sans idée de retour</i> = δόσις ἀναπόδοτος, ARSTT. <i>Top. 4, 4, 11</i>) HDT. <i>3, 130 ;</i> ESCHL. <i>Pr. 619,</i> SOPH. <i>Aj. 1032 ;</i> PLAT. <i>Leg. 844</i> d ; δωρεὰν διδόναι, HDT. <i>6, 130 ;</i> PLAT. <i>Rsp. 468</i> a ; ISOCR. <i>100</i> d ; δωρεῖσθαι, PLAT. <i>Pol. 290</i> c, faire un présent ; δωρεὰν δέχεσθαι, ISOCR. <i>122</i> a, λαμϐάνειν, ISOCR. <i>318</i> b, <i>382</i> c ; DÉM. <i>569, 26, etc</i>. recevoir un présent ; <i>adv</i>., δωρεάν (<i>ion</i>. -εήν) HDT. <i>5, 23 ;</i> DÉM. <i>394, 20 ;</i> POL. <i>18, 17, 17 ;</i> ἐν δωρεᾷ, POL. <i>23, 3, 4, etc</i>. en pur don, gratuitement ; <i>d’où</i> δωρεάν, <i>m. sign</i>. NT. <i>2Cor. 11, 7 ; ou</i> en pure perte, en vain, SPT. <i>Job 1, 9, etc. ;</i> εἰς δωρεάν, SPT. <i>Ezech. 16, 10, m. sign. ;</i><br><b>      2</b> <i>particul</i>. legs, donation, DÉM. <i>826, 11 ; 834, 11</i>.<br><span><b><span class=\"arrow\"></span></b> <i>La plus anc. forme du mot dans les inscr. att. paraît être</i> δωρειά, CIA. <i>1, 8, 20 (après 444 av. J.C.) ; 4, 25, a, 5, etc. ;</i> δωρεά <i>se rencontre pour la 1<sup>re</sup> fois à partir de la fin du 5<sup>e</sup> siècle av. J.C</i>. CIA. <i>2 add. 1, b, 32 (403 av. J. C), etc. et devient dominant à partir de 268 av. J.C. (v. Meisterh. p. 31, 11, 1). Ion</i>. δωρεή, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. δῶρον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δωρεα - δωρεά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 6 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (4)</li>\n<li>Romains (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1432":"<h1>dorean</h1>\n<p>Strong n° 1432 <i>Prononciation [do-reh-an']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>librement, gratuitement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>mot apparenté</u> : <b>δωρεά, ᾶς (ἡ) :<br>      1</b> don, présent, gratification (<i>sans idée de retour</i> = δόσις ἀναπόδοτος, ARSTT. <i>Top. 4, 4, 11</i>) HDT. <i>3, 130 ;</i> ESCHL. <i>Pr. 619,</i> SOPH. <i>Aj. 1032 ;</i> PLAT. <i>Leg. 844</i> d ; δωρεὰν διδόναι, HDT. <i>6, 130 ;</i> PLAT. <i>Rsp. 468</i> a ; ISOCR. <i>100</i> d ; δωρεῖσθαι, PLAT. <i>Pol. 290</i> c, faire un présent ; δωρεὰν δέχεσθαι, ISOCR. <i>122</i> a, λαμϐάνειν, ISOCR. <i>318</i> b, <i>382</i> c ; DÉM. <i>569, 26, etc</i>. recevoir un présent ; <i>adv</i>., δωρεάν (<i>ion</i>. -εήν) HDT. <i>5, 23 ;</i> DÉM. <i>394, 20 ;</i> POL. <i>18, 17, 17 ;</i> ἐν δωρεᾷ, POL. <i>23, 3, 4, etc</i>. en pur don, gratuitement ; <i>d’où</i> δωρεάν, <i>m. sign</i>. NT. <i>2Cor. 11, 7 ; ou</i> en pure perte, en vain, SPT. <i>Job 1, 9, etc. ;</i> εἰς δωρεάν, SPT. <i>Ezech. 16, 10, m. sign. ;</i><br><b>      2</b> <i>particul</i>. legs, donation, DÉM. <i>826, 11 ; 834, 11</i>.<br><span><b><span class=\"arrow\"></span></b> <i>La plus anc. forme du mot dans les inscr. att. paraît être</i> δωρειά, CIA. <i>1, 8, 20 (après 444 av. J.C.) ; 4, 25, a, 5, etc. ;</i> δωρεά <i>se rencontre pour la 1<sup>re</sup> fois à partir de la fin du 5<sup>e</sup> siècle av. J.C</i>. CIA. <i>2 add. 1, b, 32 (403 av. J. C), etc. et devient dominant à partir de 268 av. J.C. (v. Meisterh. p. 31, 11, 1). Ion</i>. δωρεή, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. δῶρον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δωρεαν - δωρεάν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 8 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Jean (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1433":"<h1>doreomai</h1>\n<p>Strong n° 1433 <i>Prononciation [do-reh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>présenter, accorder, donner</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>mot apparenté</u> :<b>δωρέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao</i>. ἐδώρησα, <i>pf. inus. ; pass. ao</i>. ἐδωρήθην, <i>pf</i>. δεδώρημαι)</span> donner en présent : δ. δῶρον, HÉS. <i>O. 82,</i> faire un présent ; δ. θυσίαις τινά, PD. <i>O. 6, 131,</i> honorer un dieu par des sacrifices, <i>d’où au pass. (particul. à l’ao</i>. δωρηθῆναι, <i>et au pf</i>. δεδωρῆσθαι) être offert en présent, HDT. <i>8, 85 ;</i> SOPH. <i>Aj. 1030 ;</i> PLAT. <i>Ep. 314</i> d ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. δωρήσομαι, <i>ao</i>. ἐδωρησάμην, <i>pf</i>. δεδώρημαι)</span><br><b>      1</b> faire un présent : δ. τινί τι, IL. <i>10, 557 ;</i> HDT. <i>5, 37 ;</i> ESCHL. <i>Pr. 251 ;</i> XÉN. <i>Cyr. 8, 4, 24 ;</i> PLAT. <i>2 Alc. 148</i> e, faire présent de qqe ch. à qqn ; δ. τινα, HDT. <i>4, 110,</i> faire un présent à qqn ; δ. τινά τινι, HDT. <i>1, 54 ; 3, 130 ;</i> ESCHL. <i>Pr. 780 ;</i> PLAT. <i>2 Alc. 149</i> c, gratifier qqn d’un présent <i>ou</i> honorer qqn par un présent ;<br><b>      2</b> (<i>au prés. ; cf. de même en ce sens le prés. de</i> δίδωμι) avoir l’intention de donner, <i>d’où</i> offrir, EUR. <i>Suppl. 875</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Moy. prés. 3 sg. ion</i>. δωρέεται, HDT. <i>6, 125. Impf. 3 sg. ion</i>. ἐδωρέετο, HDT. <i>3, 130. Ao. opt. 3 sg</i>. δωρήσαιτο, IL. <i>10, 557 (seul. ex. du moy. dans Hom.). Pf</i>. δεδώρημαι, <i>au sens pass</i>. PLAT. <i>Pol. 274</i> c, <i>etc. ; au sens act</i>. XÉN. <i>Cyr. 5, 2, 8 ;</i> PLAT. <i>Tim. 46</i> e, <i>Leg. 672</i> b.<br><span><b>Étym</b>. δῶρον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δωρεομαι - δωρέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G1434":"<h1>dorema</h1>\n<p>Strong n° 1434 <i>Prononciation [do'-ray-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un don, largesse, bienfaisance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δώρημα, ατος (τὸ)</b> don, présent, ESCHL. <i>Pr. 626, Pers. 523 ;</i> SOPH. <i>Aj. 662 ;</i> EUR. <i>Hel. 889 ; en prose,</i> XÉN. <i>Hier. 8, 4 ;</i> ARSTT. <i>Nic. 1, 9, 2 ; avec un dat</i>. τῶν σῶν Ἡρακλεῖ δωρημάτων, SOPH. <i>Tr. 668,</i> de tes dons à Hèraklès.<br><span><b>Étym</b>. δωρέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δωρημα - δώρημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1435":"<h1>doron</h1>\n<p>Strong n° 1435 <i>Prononciation [do'-ron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un don, un présent\n<ol type=\"a\">\n<li>présents remis pour honorer\n<ol>\n<li>sacrifices et autres dons offerts à Dieu</li>\n<li>argent remis pour les besoins du temple et pour aider les pauvres</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>l'offrande d'un don</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δῶρον, ου</b> (τό) :<br><b>   I</b> don, présent, HOM. <i>etc. plur</i>. δῶρα <i>au sens du sg</i>. IL. <i>14, 238 ; 20, 268, etc. ;</i> ORACL. (HDT. <i>6, 19</i>) ; ἄδωρα δῶρα, SOPH. <i>Aj. 665,</i> présents qui n’en sont pas ; <i>avec le gén. de la personne qui fait le présent :</i> θεοῦ δῶρον, ESCHL. <i>Sept. 625,</i> présent de la divinité, présent ; δ. θεῶν, IL. <i>20, 265 ;</i> OD. <i>18, 142,</i> présent des dieux ; δ. Μουσῶν καὶ Ἀπόλλωνος, PLAT. <i>Leg. 796</i> e, présent des Muses et d’Apollon, <i>en parl. de la poésie ; avec le gén. de la chose offerte en présent :</i> ὕπνου δ. IL. <i>7, 482,</i> le présent <i>ou</i> le bienfait du sommeil ; <i>particul. :</i><br><b>      1</b> offrande aux dieux, IL. <i>6, 293 ;</i> ESCHL. <i>Ag. 91 ; etc. ; dans les Livres saints,</i> offrande à la divinité, SPT. <i>Gen. 4, 4 ; Lev. 1, 2, etc</i>. NT. <i>Matth. 5, 23, etc. Marc. 7, 11 ; Luc. 21, 1, 4 ;</i><br><b>      2</b> tribut, IL. <i>17, 225 ;</i><br><b>      3</b> <i>au plur</i>. présents pour corrompre : ἕνεκα δώρων, PLAT. <i>Leg. 907</i> a, par vénalité ; <i>d’où</i> δώρων γραφή, ESCHN. <i>87, 3,</i> accusation de corruption ; δώρων δίωξις, PLUT. <i>Per. 10,</i> poursuite pour corruption ; δώρων κριθῆναι, LYS. <i>178, 7,</i> être jugé pour corruption ; δώρων ἑλεῖν τινα, AR. <i>Nub. 591,</i> convaincre qqn de vénalité ; δώρων ὀφλεῖν, AND. <i>10, 20,</i> être condamné pour vénalité ;<br><b>   II</b> paume de la main, palme, <i>mesure de longueur (cf</i>. παλαιστή) NIC. <i>Th. 348 ; cf</i>. ἑκκαιδεκάδωρος.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *deh₃-ro-, don ; <i>cf</i>. δίδωμι, <i>lat</i>. dōnum.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δωρον - δῶρον</font>\n<br><br>un présent</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 17 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (5)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1436":"<h1>ea</h1>\n<p>Strong n° 1436 <i>Prononciation [eh'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>interjection exprimant l'indignation, ou une surprise mêlée de crainte : oh ! ah !</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔα</b> <span>[ᾱ]</span><br><b>      1</b> <i>cri de surprise,</i> hé ! EUR. <i>Hec. 501, etc. ;</i> AR. <i>Pl. 824 ;</i><br><b>      2</b> <i>cri de douleur,</i> hélas ! <i>souv. redoublé en ce sens,</i> ESCHL. <i>Pr. 688 ;</i> SOPH. <i>O.C. 1477 ;</i><br><b>      3</b> <i>cri d’encouragement,</i> eh bien ! allons ! PLAT. <i>Prot. 314</i> d.<br><span><b><span class=\"arrow\"></span></b> <i>Rare en prose, v. ci-dessus</i>, PLAT. <i>l. c. Qqf. monosyll. par synizèse, en poésie</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εα - ἔα</font>\n<br><br>impératif apparent de </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Interjection</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1437":"<h1>ean</h1>\n<p>Strong n° 1437 <i>Prononciation [eh-an']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>si, dans le cas</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐάν</b> (<i>pour</i> εἰ ἄν), <i>par contract</i>. <b>ἤν</b> <i>ou</i> <b>ἄν</b> <span>[ᾱ]</span> <i>conj. marquant une idée d’hypothèse ou de condition,</i> si, au cas où :<br><b>A</b> <i>dans le discours direct :</i><br><b>   I</b> <i>d’ord. avec le sbj. :</i><br><b>      1</b> <i>quand l’action exprimée par la prop. qu’annonce ἐάν marque une hypothèse de réalisation incertaine :</i> ἐάν τι φάγωσιν, ἀναστήσονται, XÉN. <i>An. 4, 5, 8,</i> s’ils mangent qqe ch., ils se relèveront, <i>en parl. de soldats malades de boulimie ;</i> ἐὰν ζητῇς καλῶς, εὑρήσεις, PLAT. <i>Gorg. 503</i> d, si tu cherches bien, tu trouveras ; χάριν εἴσομαι, ἐὰν ἀκούητε, PLAT. <i>Prot. 310</i> a, je vous saurai gré, si vous voulez bien écouter ;<br><b>      2</b> <i>quand la condition exprimée par la prop. qu’annonce ἐάν se trouve remplie, càd. dans les prop. qui expriment un fait d’habitude :</i> ἐάν τις τὸν ἥλιον ἀναιδῶς ἐγχειρῇ θεᾶσθαι, τὴν ὄψιν ἀφαιρεῖται, XÉN. <i>Mem. 4, 3, 14,</i> quiconque a l’audace de vouloir regarder fixement le soleil, perd la vue ; ἢν ἐγγὺς ἔλθῃ θάνατος, οὐδεὶς βούλεται θνῄσκειν, EUR. <i>Alc. 671,</i> que la mort approche, et personne ne veut mourir ; <i>en ce sens dans les inscr. att. tantôt avec le sbj. prés</i>. CIA. <i>1, 31, a, 20 (444/440 av. J.C.) tantôt avec le sbj. ao</i>. CIA. <i>1, 32, b, 16 (435/416 av. J.C</i>.) ; CIA. <i>2, 17, a, 51 (378 av. J.C.) (v. Meisterh. p. 201, 10) ; lorsqu’en ce sens la condition marquée par ἐάν est double, l’alternative s’exprime par</i> ἐάν τε… ἐάν τε (<i>ou</i> ἤν τε… ἤν τε) <i>avec le sbj</i>. τά τε πηγαῖα ὕδατα, ἐάν τέ τις ποταμός, ἐάν τε καὶ κρήνη ᾖ, PLAT. <i>Leg. 761</i> b, les eaux de source, qu’elles soient fleuve ou fontaine ; ἴσοι ὄντες μαχούμεθα, ἤν τε ἐνθάδε ἐπιόντας αὐτοὺς δεχώμεθα, ἤν τε ἐπ' ἐκείνους ἰόντες τὴν μάχην συνάπτωμεν, XÉN. <i>Cyr. 3, 3, 17,</i> nous combattrons avec un égal courage, soit que nous attendions ici l’attaque de l’ennemi, soit que nous marchions sur lui pour en venir aux mains ; <i>cf</i>. ἤν τε… ἤν τε <i>quatre fois répété,</i> XÉN. <i>Œc. 11, 16 ; Cyr. 1, 1, 5 ;</i><br><b>   II</b> <i>avec l’opt. au lieu du sbj. après Aristote,</i> MAN. <i>1, 24, 45, 119, 158 ;</i> GEOP. <i>10, 21, 4 et 5 ;</i><br><b>B</b> <i>dans le discours indir. avec le sbj. si la prop. d’interr. indir. dépend d’un verbe impliquant l’idée exprimée ou s.-ent. de</i> « savoir, rechercher, examiner, <i>etc</i>. » : εἶμι γὰρ ἐς Σπάρτην, νόστον πευσόμενος πατρὸς φίλου, ἤν που ἀκούσω, OD. <i>2, 360,</i> car je vais à Sparte m’informer du retour de mon père et savoir si j’entendrai dire qqe ch. de lui ; ζητοῦσ' ἦλθ', ἤν που 'πιτύχῃ, <i>etc</i>. AR. <i>Nub. 535,</i> elle est venue chercher, si par hasard elle rencontrerait, <i>etc. ;</i> Θέτιδος εἰς ἀνάκτορον θάσσω τόδ' ἐλθοῦσ', ἤν με κωλύσῃ θανεῖν, EUR. <i>Andr. 43,</i> je suis venue me reposer dans ce temple de Thétis pour savoir si elle m’empêchera de mourir ;<br><b>C</b> <i>au sens de</i> ἄν, <i>pour marquer une simple possibilité, rar. dans les classiques :</i> ᾧ ἐὰν ἁρμόττῃ, XÉN. <i>Mem. 3, 10, 12,</i> à qui cela pourrait aller ; <i>surt. après Aristote :</i> οὗ ἐὰν ᾖ, TH. <i>H.P. 3, 10, 3,</i> là où il serait ; <i>particul. dans la traduct. des Livres saints :</i> ὃς ἐάν, <i>avec le sbj.,</i> quiconque, <i>etc</i>. NT. <i>Ap. 2, 21 ;</i> ὅπου ἐὰν ἀπέρχῃ, NT. <i>Matth. 8, 19,</i> en qqe lieu que tu t’éloignes ; <i>cf</i>. ᾧ ἐάν, SPT. <i>Gen. 15, 14 ;</i> οἷς ἐάν, <i>Gen. 21, 12, 22 ;</i> ὅσα ἐάν, <i>Gen. 44, 1 ;</i><br><b>D</b> ἐάν <i>se joint à diverses particules :</i><br><b>      1</b> ἐάν τε… ἐάν τε <i>ou</i> ἤν τε… ἤν τε (<i>v. ci-dessus</i>) ;<br><b>      2</b> ἐάν τε <i>en relat. avec</i> καί, SOPH. <i>Ant. 327 ;</i><br><b>      3</b> ἐάνπερ, ESCHL. <i>Pers. 529 ;</i> SOPH. <i>El. 593 ; ou</i> ἤνπερ, AR. <i>Th. 926, etc. ;</i> XÉN. <i>Cyr. 4, 6, 4 ; ou</i> ἤνπερ γε, XÉN. <i>Eq. 10, 11,</i> si d’ailleurs, au cas d’ailleurs où, au moins si ;<br><b>      4</b> ἐὰν <i>ou</i> ἢν ἄρα, THC. <i>4, 8 et 18 ;</i> XÉN. <i>An. 5, 1, 13,</i> si toutefois, si en vérité ;<br><b>      5</b> ἐάν πως, SOPH. <i>Tr. 584, ou</i> ἤν πως, AR. <i>Vesp. 399 ;</i> PLAT. <i>Rsp. 455,</i> si peut-être, si par hasard ;<br><b>      6</b> ἐὰν καί, XÉN. <i>Conv. 7, 35 ; ou</i> ἢν καί, THC. <i>5, 91 ;</i> καὶ ἐάν, THC. <i>5, 38, 103 ; ou</i> καὶ ἤν, THC. <i>3, 46, 94 ; 5, 45,</i> même si, quand bien même ;<br><b>      7</b> ἐὰν μή <i>ou</i> ἢν μή, HPC. <i>903</i> f ; EUR. <i>Med. 30 ;</i> ἢν μή περ, HDT. <i>6, 57,</i> à moins que.<br><span><b><span class=\"arrow\"></span></b> ἐάν <i>se rencontre dans des inscr. att. des 6<sup>e</sup> et 5<sup>e</sup> siècles av. J.C.,</i> CIA. <i>I, 1, c, 28 ; 19, 3, etc. (v. Meisterh. p. 35, 18, 1) et est antérieur à l’écriture</i> εἰάν <i>de la fin du 4<sup>e</sup> siècle av. J.C.,</i> CIA. <i>2, add. nov. 14, b, 11 (387 av. J.C.) ; etc. (après 350 av. J.C.). La forme contr</i>. ἤν <i>inus. dans ces inscr</i>.<br><span><b>Étym</b>. εἰ, ἄν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εαν - ἐάν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n274 fois dans 252 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (54)</li>\n<li>Marc (30)</li>\n<li>Luc (28)</li>\n<li>Jean (42)</li>\n<li>Actes (5)</li>\n<li>Romains (19)</li>\n<li>1 Corinthiens (37)</li>\n<li>2 Corinthiens (6)</li>\n<li>Galates (4)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (3)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (8)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (1)</li>\n<li>1 Jean (18)</li>\n<li>3 Jean (2)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G1438":"<h1>heautou</h1>\n<p>Strong n° 1438 <i>Prononciation [incluant tous les autres cas]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lui-même, elle-même, par lui-même, eux-mêmes, ...</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑαυτοῦ, ῆς, οῦ</b> (<i>contr</i>. αὑτοῦ, ῆς, οῦ) ; <i>acc. neutre</i> ἑαυτό ; <i>gén. pl</i>. ἑαυτῶν, <i>etc. :</i><br><b>      1</b> de soi-même, à soi-même, soi-même : ἑαυτὸν σφάττειν, XÉN. <i>Cyr. 7, 3, 5 ;</i> ARSTT. <i>Nic. 5, 11,</i> s’égorger soi-même ; πλουσιώτεροι ἑαυτῶν γιγνόμενοι, THC. <i>1, 8,</i> devenant plus riches qu’ils n’étaient ; <i>qqf. renforcé par αὐτός construit avec le sujet de la prop. :</i> οὐχ οἷός τέ ἐστιν αὐτὸς αὑτῷ βοηθεῖν, PLAT. <i>Gorg. 483</i> b, il n’est pas en état de se défendre lui-même ; τὸ γιγνώσκειν αὐτὸν ἑαυτόν, PLAT. <i>Charm. 165</i> b, se connaître soi-même ; <i>abs. dans un grand nombre de loc. :</i> τὸ ἑαυτοῦ μόνον σκοπεῖν, THC. <i>6, 12,</i> ne regarder que soi-même, <i>càd</i>. que son propre intérêt ; ἐν τοῖς ἑαυτοῦ, ATH. <i>1</i> a, <i>ou</i> παρ' ἑαυτῷ, XÉN. <i>Mem. 3, 13, 3 ;</i> NT. <i>1Cor. 16, 2,</i> dans sa propre maison, chez soi ; <i>avec mouv</i>. πρὸς ἑαυτόν, NT. <i>Luc. 24, 12, ou, en parl. de plus. pers</i>. εἰς ἑαυτῶν, AR. <i>Lys. 1070 ;</i> πρὸς ἑαυτούς, NT. <i>Joh. 20, 10,</i> à sa maison, chez soi ; αὐτὸ καθ' αὑτό, PLAT. <i>Theæt. 157</i> a ; αὐτὸ ἐφ' ἑαυτό, <i>Theæt. 152</i> b ; αὐτὸ ἐφ' αὑτοῦ, <i>Theæt. 160</i> c, de soi-même, <i>càd</i>. absolument ; ἑαυτοῦ εἶναι, PLUT. <i>M. 233</i> d, être son maître, être indépendant ; ἐξ ἑαυτοῦ γίγνεσθαι, SPT. <i>3Reg. 10, 5,</i> être hors de soi, être frappé d’étonnement ; ἐν ἑαυτῷ γίγνεσθαι, XÉN. <i>An. 1, 5, 17,</i> revenir à soi, redevenir maître de soi ;<br><b>      2</b> <i>chez les Att., au plur. et qqf. au sg., pour les pronoms de la 1<sup>re</sup> et de la 2<sup>e</sup> pers. : p</i>. ἐμαυτοῦ, ESCHL. <i>Ch. 221, 1014 ;</i> SOPH. <i>O.R. 138 ;</i> POL. <i>2, 37, 2 ;</i> SPT. <i>Gen. 11, 4 ; 1 Macc. 5, 57 ; etc. ; p</i>. σεαυτοῦ, ESCHL. <i>Ag. 1142, 1297 ; etc. ;</i> POL. <i>3, 109, 9 ; 18, 6, 4 ;</i> SPT. <i>Sir. 51, 25 ; Jer. 4, 3, etc. ; au pl. p</i>. ἡμῶν αὐτῶν, ἡμᾶς αὐτούς, <i>etc. ;</i> ἴστε ἡμᾶς Φωκίδα ὑφ' ἑαυτοὺς πεποιημένους, DÉM. <i>238, 26,</i> vous savez que nous avons soumis la Phocide à notre propre domination ; <i>cf</i>. ESCHL. <i>Suppl. 806 ;</i> POL. <i>2, 37, 2, etc. ;</i><br><b>      3</b> <i>au pl. p</i>. ἀλλήλων, ἀλλήλοις, des uns aux autres, les uns aux autres : φθονοῦντες ἑαυτοῖς μισοῦσιν ἀλλήλους, XÉN. <i>Mem. 2, 6, 20,</i> se portant mutuellement envie, ils se haïssent les uns les autres ; περιϊόντες αὑτῶν πυνθάνονται, DÉM. <i>43, 7,</i> circulant (sur la place) ils s’informent les uns auprès des autres ; <i>cf</i>. HDT. <i>3, 49 ;</i> THC. <i>4, 25, etc. ;</i> SPT. <i>Sap. 5, 3, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἑωϋτοῦ <i>ou mieux</i> ἑωυτοῦ, ἑωυτῷ, ἑωυτόν, HPC. <i>1207</i> b, <i>1210</i> e, <i>1222 d, e, 1233</i> e, <i>etc. ; ou</i> ωὑτέου, ARÉT. <i>Caus. m. acut. 1, 7, p. 5 ; plur</i>. ωὑτέων, <i>Caus. m. acut. 1, 7, p. 34 ;</i> ωὑτέοισι, <i>Caus. m. acut. 2, 4, p. 17. — Dans les inscr. att. du 4<sup>e</sup> siècle av. J.C. la forme pleine au sg. et au plur</i>. (ἑαυτοῦ, ἑαυτῶν) <i>et la forme contracte</i> (αὑτοῦ, αὑτῶν) <i>sont à peu près aussi usitées (la forme pleine un peu plus, 31</i> ἑαυτ. <i>contre 23</i> αὑτ.) ; <i>de 300 à 30 av. J.C. la forme pleine devient dominante (100</i> ἑαυτ. <i>contre 7</i> αὑτ.), <i>p.-ê. parce que la prononciat. de l’esprit rude s’étant affaiblie,</i> αὑτοῦ <i>ne se distinguait plus assez nettement de</i> αὐτοῦ (<i>v. Meisterh. p. 121, 4). À partir de 74 av. J.C. environ,</i> ἑαυτοῦ, <i>etc. s’affaiblit qqf. dans les inscr. att. en</i> ἑατοῦ, ἑατῆς, ἑατῷ, ἑατόν, ἑατῶν, ἑατούς, <i>et même en</i> ἁτῶν (<i>v. Meisterh. p. 121, 5). Enfin, sous l’empire, αὑτοῦ, αὑτῶν est qqf. remplacé par le pron. pers</i>. αὐτοῦ, αὐτῶν (<i>v. Meisterh. p. 122</i>).<br><span><b>Étym</b>. ἕ, αὐτός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εαυτου - ἑαυτοῦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n339 fois dans 312 versets de 25 livres bibliques (NT)\n<ul>\n<li>Matthieu (31)</li>\n<li>Marc (27)</li>\n<li>Luc (61)</li>\n<li>Jean (27)</li>\n<li>Actes (21)</li>\n<li>Romains (24)</li>\n<li>1 Corinthiens (16)</li>\n<li>2 Corinthiens (30)</li>\n<li>Galates (8)</li>\n<li>Ephésiens (16)</li>\n<li>Philippiens (7)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (6)</li>\n<li>2 Thessaloniciens (4)</li>\n<li>1 Timothée (5)</li>\n<li>2 Timothée (3)</li>\n<li>Tite (2)</li>\n<li>Hébreux (13)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (5)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (5)</li>\n<li>2 Jean (1)</li>\n<li>Jude (7)</li>\n<li>Apocalypse (12)</li>\n</ul>\n</td></tr>\n</table>","G1439":"<h1>eao</h1>\n<p>Strong n° 1439 <i>Prononciation [eh-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>admettre, permettre, laisser</li>\n<li>laisser faire, ne pas retenir</li>\n<li>renoncer à, laisser aller, quitter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐάω-εῶ</b> <span>(<i>impf</i>. εἴων, <i>f</i>. ἐάσω, <i>ao</i>. εἴασα, <i>pf</i>. εἴακα ; <i>pass. ao</i>. εἰάθην, <i>pf</i>. εἴαμαι)</span> <span>[ᾰ <i>au prés. et à l’impf. ;</i> ᾱ <i>aux autres temps act. pass. et moy</i>.]</span><br><b>   I</b> laisser, <i>d’où :</i><br><b>      1</b> souffrir, permettre, <i>avec une prop. inf</i>. τινα ἐᾶν φθινύθειν, IL. <i>2, 346, ou</i> ζώειν, OD. <i>13, 359,</i> laisser périr, laisser vivre qqn ; <i>qqf. avec omission du verbe :</i> αὐτονόμους ἐᾶν πολίτας, XÉN. <i>Hell. 3, 1, 17 (cf. la construct. complète avec</i> εἶναι, <i>Hell. 6, 4, 2</i>) laisser les citoyens vivre autonomes ; οὐκ ἐᾶν, <i>avec une prop. inf</i>. ne pas permettre ; τρεῖν μ' οὐκ ἐᾷ Πάλλας, IL. <i>6, 256,</i> Pallas ne permet pas que je tremble ; <i>d’où</i> défendre, empêcher que : οὐκ ἐάσουσιν ἐμοὶ δόμεναι βιόν, OD. <i>21, 233</i> (les prétendants) refuseront de me donner l’arc ; κἂν μηδεὶς ἐᾷ, SOPH. <i>Aj. 1184,</i> quand bien même personne n’y consentirait, <i>càd</i>. quand bien même tous s’y opposeraient, IL. <i>4, 55 ;</i> OD. <i>19, 25 ;</i> HÉS. <i>Th. 772 ; en parl. d’une défense faite par la loi,</i> ESCHN. <i>3, 21, 176 Baiter-Sauppe (cf. ci-dessous</i> HDT. <i>7, 104) ; cf</i>. CIA. <i>2 add. 841, b, 55 (396 av. J.C.) ; ou simpl</i>. ne pas admettre : πόλεμον οὐκ εἴων ποιεῖν, THC. <i>1, 28,</i> ils ne voulaient pas faire la guerre ; <i>en ce sens souv. opp. à</i> κελεύω : οἱ μὲν κελεύοντες ἐξιέναι, οἱ δέ τινες οὐκ ἐῶντες, THC. <i>2, 21,</i> les uns conseillant de s’en aller, qqes autres s’y opposant ; <i>ou à</i> ὁρμάω : οὐκ εἴα ὑπείκειν, ἀλλ' ἐς τὸν πόλεμον ὥρμα τοὺς Ἀθηναίους, THC. <i>1, 127,</i> (Périclès) n’admettait pas qu’ils cédassent, loin de là il excitait les Athéniens à la guerre ; <i>qqf. en opp. avec</i> ἀλλά (<i>s.-e</i>. κελεύω) : οὐκ ἐῶν φεύγειν, ἀλλὰ (κελεύων) μένοντας ἐπικρατέειν, HDT. <i>7, 104,</i> (la loi) ne leur permettant pas de fuir, loin de là, leur ordonnant d’attendre de pied ferme et de tenir bon ; <i>au pass</i>. οὐκ ἐᾶσθαι, EUR. <i>I.T. 1344 ;</i> THC. <i>1, 142 ;</i> DÉM. <i>2, 16 Baiter-Sauppe,</i> n’être pas libre de ;<br><b>      2</b> <i>rar. avec un acc. de chose,</i> laisser, abandonner, concéder : τινί τι, SOPH. <i>O.C. 368 ;</i> PLUT. <i>M. 233</i> d, laisser qqe ch. à qqn ;<br><b>   II</b> laisser aller, <i>d’où</i> congédier : τινα, IL. <i>24, 557,</i> qqn ;<br><b>   III</b> laisser de côté, <i>d’où :</i><br><b>      1</b> renoncer à : ἔα χόλον, IL. <i>9, 260,</i> laisse se calmer ta colère ; ἐᾶν φιλοσοφίαν, PLAT. <i>Gorg. 484</i> c, renoncer à la philosophie ; <i>avec un inf</i>. ἐᾶν ἰέναι, HDT. <i>3, 134,</i> renoncer à aller ;<br><b>      2</b> ne pas s’occuper de, négliger, omettre, <i>avec l’inf</i>. κλέψαι μὲν ἐάσομεν (<i>sbj. poét</i>.) Ἕκτορα, IL. <i>24, 71,</i> ne nous occupons pas de voler le corps d’Hector ; θεὸς τὸ μὲν δώσει, τὸ δ' ἐάσει (δοῦναι), OD. <i>14, 444,</i> la divinité donnera ceci, négligera de donner cela ; <i>abs</i>. ἥδ' οὖν ἐάσθω, SOPH. <i>Tr. 329,</i> qu’on cesse donc de se préoccuper de celle-ci ;<br><b>      3</b> <i>p. suite,</i> délaisser, abandonner : τινα ἐᾶν ἄκλαυτον, ἄταφον, SOPH. <i>Ant. 29,</i> laisser (un mort) sans lamentations, sans sépulture.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. (formes se rapportant à deux types de radical : rad</i>. ἐα-, <i>rad. épq</i>. εἰα-) :<br><b>      1</b> <i>rad</i>. ἐά- : ἐῶ, IL. <i>8, 428 ;</i> ATT. (ESCHL. <i>Sept. 378 ;</i> SOPH. <i>El. 632 ;</i> THC. <i>3, 48, etc.) ; 2 sg. épq</i>. ἐάᾳς, OD. <i>12, 282 ; 19, 374 ; 3 sg. épq</i>. ἐάᾳ, IL. <i>8, 414 (mais aussi la forme att</i>. ἐᾷ, IL. <i>5, 256, monosyll. par syniz.). Sbj. 2 sg. épq</i>. ἐάᾳς, OD. <i>11, 110 ; 12, 137 (mais aussi la forme att</i>. ἐᾷς, OD. <i>11, 147) ; 1 pl. dissyll. par syniz</i>. ἐῶμεν, IL. <i>10, 344 ; opt. poét</i>. ἐῷμι, OD. <i>16, 85 ; 3 sg</i>. ἐῷ, OD. <i>20, 12 ; opt. att</i>. ἐῴην, PLAT. <i>Gorg. 458 ; 3 sg</i>. ἐῴη, SOPH. <i>Ph. 444 ;</i> XÉN. <i>Cyr. 1, 5, 10, etc. Inf. épq</i>. ἐάαν, OD. <i>8, 509 (mais aussi la forme att</i>. ἐᾶν, IL. <i>2, 131, etc</i>.) ;<br><b>      2</b> <i>rad. épq</i>. εἰα- : <i>prés. ind. 3 pl</i>. εἰῶσι, IL. <i>2, 131 ; 11, 550 ; 17, 659 (mais aussi la forme</i> ἐῶσι, IL. <i>23, 73 ;</i> OD. <i>4, 805). Sbj</i>. εἰῶ, IL. <i>4, 55 ; 1 pl</i>. εἰῶμεν, OD. <i>21, 260 ; 3 pl</i>. εἰῶσι, IL. <i>20, 139. — Impf. ion</i>. ἔων, HDT. <i>9, 2 ; 3 sg. épq. et ion</i>. ἔα, IL. <i>5, 517 ;</i> HDT. <i>1, 17 (mais aussi la forme</i> εἴα, OD. <i>7, 41). — Impf. itér. avec double rad. en</i> ἐα- <i>ou en</i> εἰα- (<i>vraisembl. sans augment, cf. le prés. épq</i>. εἰάω) : *ἔασκον, <i>d’où 2 sg</i>. ἔασκες, IL. <i>19, 295 ; 3 sg</i>. ἔασκε, IL. <i>2, 832 ; 11, 330 ; 24, 17 ; et</i> εἴασκον, IL. <i>5, 802 ; 3 sg</i>. εἴασκε, IL. <i>20, 408 ;</i> OD. <i>22, 427 ; avec élis. dev. un esprit rude :</i> εἴασχ', IL. <i>11, 125. — Ao. poét</i>. ἔασα, IL. <i>11, 437 ;</i> CALL. <i>Cer. 62 ; sbj. 1 pl. poét</i>. ἐάσομεν, IL. <i>19, 65. — Pass. ao</i>. εἰάθην, ISOCR. <i>60</i> e. — <i>Pf</i>. εἴαμαι, DÉM. <i>1108, 1. — Moy. fut. au sens pass</i>. ἐάσομαι, EUR. <i>I.A. 331 ;</i> THC. <i>1, 142</i>. — ἐα- <i>ou</i> ἐω- <i>monosyll. par syniz. dans les formes suiv. : prés. ind</i>. ἐῶ, AR. <i>Lys. 734 ; 3 sg</i>. ἐᾷ, IL. <i>5, 256 ; impér. 2 sg</i>. ἔα, SOPH. <i>O.R. 1451 ; Ant. 95 ;</i> AR. <i>Nub. 932 ; sbj. 1 pl</i>. ἐῶμεν, IL. <i>10, 344 ; 19, 402 ; fut. 3 pl</i>. ἐάσουσιν, OD. <i>21, 233. — Par licence</i> <span>[ᾰ]</span> <i>dans</i> εἴασε, ANTH. <i>3, 14, 4</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εαω - ἐάω</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 13 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n<li>Actes (9)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1440":"<h1>hebdomekonta</h1>\n<p>Strong n° 1440 <i>Prononciation [heb-dom-ay'-kon-tah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>soixante-dix\n<ol type=\"a\">\n<li>les soixante-dix disciples envoyés par Jésus en plus des douze apôtres</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑϐδομήκοντα (οἱ, αἱ, τὰ</b>) <i>indécl</i>. soixante-dix, HDT. <i>1, 32, etc. ;</i> ATT. <i>etc. ;</i> οἱ ἑ. πρεσϐύτεροι, JOS. <i>A.J. 12, 2, 7,</i> les Septante, <i>càd</i>. les 70 interprètes (<i>exactement non 70, mais 72</i>) qui traduisirent en grec le texte hébreu de l’Ancien Testament.<br><span><b>Étym</b>. ἕϐδομος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εβδομηκοντα - ἑβδομήκοντα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nombre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G1441":"<h1>hebdomekontakis</h1>\n<p>Strong n° 1441 <i>Prononciation [heb-dom-ay-kon-tak-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>septante (soixante-dix) fois sept fois\n<ol type=\"a\">\n<li>un nombre incalculable</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑϐδομηκοντάκις</b> <span>[ᾰῐ]</span> <i>adv</i>., soixante-dix fois, SPT. <i>Gen. 4, 24 ;</i> NT. <i>Matth. 18, 22</i>.<br><span><b>Étym</b>. ἑϐδομήκοντα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εβδομηκοντακις - ἑβδομηκοντάκις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G1442":"<h1>hebdomos</h1>\n<p>Strong n° 1442 <i>Prononciation [heb'-dom-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>septième</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἕϐδομος, η, ον</b>, septième, IL. <i>19, 117 ;</i> OD. <i>12, 399, etc. ;</i> ἕϐδομος ἀριθμός, PHIL. <i>2, 5,</i> le nombre sept ; ἡ ἑϐδόμη (<i>s.-e</i>. ἡμέρα) le septième jour (du mois lunaire) HDT. <i>6, 57 ;</i> PLUT. <i>M. 1027</i> e ; <i>p. suite,</i> le sabbat, PHIL. <i>1, 675 ; 2, 137, 166</i>.<br><span><b>Étym</b>. ἕπτα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εβδομος - ἕβδομος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Hébreux (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G1443":"<h1>Eber</h1>\n<p>Strong n° 1443 <i>Prononciation [eb-er']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Eber (Angl. Eber ou Hebrew) = « l'autre côté, la région au delà »\n<ol><li>le fils de Schéla, et descendant de Sem, un des ancêtres d'Abraham</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εβερ</font> &lt; עבר - <font face=\"Georgia\">Ἐβέρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1444":"<h1>Hebraikos</h1>\n<p>Strong n° 1444 <i>Prononciation [heb-rah-ee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>Hébreu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἑϐραϊκός, ή, όν</b>, hébraïque, NT. <i>Luc. 23, 38</i>.<br><span><b>Étym</b>. Ἑϐραῖος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εβραικος - Ἑβραϊκός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>","G1445":"<h1>Hebraios</h1>\n<p>Strong n° 1445 <i>Prononciation [heb-rah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>Hébreu\n<ol type=\"a\">\n<li>qui est de la nation Juive ou Israélite</li>\n</ol>\n</li>\n<li>dans un sens plus étroit, celui qui vit en Palestine et utilise la langue de cette contrée</li>\n<li>les Chrétiens Juifs, qu'ils parlent Araméen ou Grec</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἑϐραῖος, α, ον</b>, hébreu ; οἱ Ἑϐραῖοι, les Hébreux, PAUS. <i>1, 5, 5 ;</i> APP. <i>Civ. 2, 71 ; etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εβραιος - Ἑβραῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (2)</li>\n</ul>\n</td></tr>\n</table>","G1446":"<h1>Hebrais</h1>\n<p>Strong n° 1446 <i>Prononciation [heb-rah-is']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>l'hébreu, la langue hébraïque, pas le langage utilisé dans l'A.T, mais le Chaldéen, langue du temps de Jésus et des apôtres</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑϐραΐς, ΐδος</b>, <i>adj. f</i>. hébraïque ; <i>subst</i>. ἡ ἑ. la langue hébraïque, NT. <i>Ap. 21, 40 ;</i> JOS. <i>Macc. 16</i>.<br><span><b>Étym</b>. Ἑϐραῖος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εβραις - Ἑβραΐς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G1447":"<h1>Hebraisti</h1>\n<p>Strong n° 1447 <i>Prononciation [heb-rah-is-tee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>en Hébreu, c.à.d en Chaldéen</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑϐραϊστί</b>, <i>adv</i>., en hébreu, SPT. <i>Sir. prol. ;</i> NT. <i>Joh. 5, 2 ; 19, 13</i>.<br><span><b>Étym</b>. Ἑϐραῖος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εβραιστι - Ἑβραϊστί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (4)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1448":"<h1>eggizo</h1>\n<p>Strong n° 1448 <i>Prononciation [eng-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amener près de, joindre une chose à une autre</li>\n<li>aller ou venir près de, s'approcher de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγγίζω<br>   I <i>tr</i>.<br>      1</b> approcher : τινί τι, POL. <i>8, 6, 7 ;</i> A. TAT. <i>2, 37,</i> une chose d’une autre ; τινὰ πρός τινα, SPT. <i>Gen. 48, 10,</i> faire avancer une personne auprès d’une autre ;<br><b>      2</b> activer, accélérer, hâter (un travail) <i>acc</i>. SPT. <i>Esaï. 5, 19 ;</i><br><b>   II <i>intr.</i></b> s’approcher : τινός, POL. <i>4, 62, 5 ; 8, 6, 6, etc. ;</i> τινί, POL. <i>17, 4, 1 ;</i> DS. <i>2, 19 ;</i> πρός τι, HÉRON <i>Aut. 269 ;</i> πρός τινα, SPT. <i>Ex. 24, 2,</i> de qqe ch. <i>ou</i> de qqn, rejoindre qqe ch. <i>ou</i> qqn ; <i>fig</i>. être proche parent de, <i>dat</i>. SPT. <i>Lev. 21, 3 ; abs</i>. SPT. <i>Deut. 25, 5 ;</i> D. CHR. <i>1, 138</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf</i>. ἤγγιζον, DS. <i>13, 77. Fut. 3 sg</i>. ἐγγιεῖ, SPT. <i>Ex. 24, 2. Ao. 3 sg</i>. ἤγγισεν, DS. <i>13, 109 ;</i> SPT. <i>Gen. 48, 10 ; Job 33, 22 ; 3 pl</i>. ἤγγισαν, DS. <i>2, 19 ; 14, 23 ; impér. 2 pl</i>. ἐγγίσατε, NT. <i>Jac. 4, 8 ; sbj. 3 sg</i>. ἐγγίσῃ, SPT. <i>Agg. 2, 14 ; 3 pl</i>. ἐγγίσωσι, POL. <i>8, 6, 6 ; part</i>. ἐγγίσας, POL. <i>17, 4, 1 ;</i> ἐγγίσαντες, POL. <i>15, 31, 3. Pf. 3 sg</i>. ἤγγικεν, SPT. <i>Ezech. 7, 7</i>.<br><span><b>Étym</b>. ἐγγύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγγιζω - ἐγγίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 41 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (3)</li>\n<li>Luc (18)</li>\n<li>Actes (6)</li>\n<li>Romains (1)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (3)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1449":"<h1>eggrapho</h1>\n<p>Strong n° 1449 <i>Prononciation [eng-graf'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>graver, inscrire, écrire dans ou sur\n<ol type=\"a\">\n<li>enregistrer, enrôler</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·γράφω</b> <span>[ᾰ]</span><br><b>   I</b> faire une incision dans, <i>acc</i>. TH. <i>H.P. 5, 1, 2 ;</i><br><b>   II</b> <i>p. suite,</i> inscrire, <i>d’où :</i><br><b>      1</b> écrire dans : ἐν ἐπιστολῇ, THC. <i>1, 128,</i> dans une lettre ;<br><b>      2</b> graver <i>ou</i> inscrire dans : γράμματα στήλῃ, HDT. <i>4, 91 ou</i> ἐν στήλῃ, HDT. <i>2, 102,</i> graver des lettres, <i>càd</i>. une inscription sur une colonne ; ἐγγ. νόμους, LYS. <i>183, 16,</i> graver des lois (sur des tables <i>ou</i> des colonnes) ; <i>fig</i>. εἰ μέλλουσι τοιαῦται διάνοιαι ἐγγραφήσεσθαι ἀνθρώποις, XÉN. <i>Cyr. 3, 3, 32,</i> si de telles pensées doivent se graver dans le cœur des hommes ; <i>particul. à Athènes,</i> inscrire sur un registre public, <i>en parl. des registres d’état civil :</i> τινὰ εἰς τοὺς ἐφήϐους, PLAT. <i>Ax. 366</i> e ; εἰς ἄνδρας, DÉM. <i>412, 25 ;</i> εἰς τοὺς φράτερας, DÉM. <i>995, 28,</i> inscrire parmi les éphèbes, parmi les membres d’une phratrie, parmi les hommes faits ; <i>au pass</i>. εἰς τοὺς δημότας ἐγγραφῆναι, DÉM. <i>314, 4,</i> avoir été inscrit parmi les citoyens d’un dème ; <i>abs. au pass</i>. être inscrit sur un registre public : Μαντίθεος ἐνεγεγράμμην, DÉM. <i>995,</i> j’avais été inscrit sous le nom de Mantithéos ; τοὺς μήπω διὰ τὴν ἡλικίαν ἐγγεγραμμένους, ARSTT. <i>Pol. 3, 1, 5,</i> ceux qui ne sont pas encore inscrits faute d’avoir l’âge (légal) ; — <i>en parl. des registres de finances, particul. pour les débiteurs envers l’État,</i> PLAT. <i>Leg. 784</i> d ; DÉM. <i>771, 6, etc. ; — en parl. des rôles de justice, pour les accusés,</i> AR. <i>Pax 1180 ;</i> DÉM. <i>973, 25 ;</i> ESCHN. <i>48, 1 ; pour les condamnés,</i> PLUT. <i>Them. 6 ;</i><br><b>      3</b> peindre <i>ou</i> broder sur : ζῷα ἐς ἐσθῆτα, HDT. <i>1, 203,</i> broder des animaux sur un vêtement ;<br><b><i>Moy.</i></b> inscrire pour soi : τι δέλτοις φρενῶν, ESCHL. <i>Pr. 789,</i> une chose sur les tablettes de son esprit, <i>càd</i>. dans sa mémoire.<br><span><b>Étym</b>. ἐν, γρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγγραφω - ἐγγράφω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G1450":"<h1>egguos</h1>\n<p>Strong n° 1450 <i>Prononciation [eng'-goo-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une caution, un garant, répondant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔγγυος, ος, ον</b> <span>[ῠ]</span><br><b>      1</b> qui sert de caution, répondant, garant, XÉN. <i>Vect. 4, 20 ;</i> ARSTT. <i>Œc. 2, 23 ;</i> ESCHN. <i>128</i> a ; POL. <i>5, 27, 1 ;</i><br><b>      2</b> garanti sur caution, assuré, LYS. <i>902, 3</i>.<br><span>•<i> Cp</i>. -ώτερος, THÉM. <i>197</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, ESCHN. <i>l. c</i>.<br><span><b>Étym</b>. ἐγγύη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγγυος - ἔγγυος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1451":"<h1>eggus</h1>\n<p>Strong n° 1451 <i>Prononciation [eng-goos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>proche, en lieu et position\n<ol type=\"a\">\n<li>près de</li>\n<li>ceux qui sont proches de l'accès à Dieu\n<ol>\n<li>les Juifs, par opposition à ceux qui sont loin de Dieu et de ses bénédictions</li>\n<li>les Rabbins utilisaient « rendre proche » comme équivalent à « faire un prosélyte »</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>pour le temps\n<ol type=\"a\">\n<li>imminent et proche dans le passé</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγγύς</b> <span>[ῠ]</span> <i>adv. et prép</i>. près, proche, auprès :<br><b>      1</b> (<i>avec idée de lieu) p. opp. à</i> πόρρω, PLAT. <i>Prot. 356</i> e ; <i>avec ou sans mouv</i>. ἐγγ. εἶναι, HÉS. <i>O. 247 ;</i> THC. <i>3, 55,</i> être auprès ; ἐγγ. ἑστάναι, ESCHL. <i>Pers. 686,</i> se tenir auprès ; ἐγγ. χωρεῖν, ESCHL. <i>Sept. 59,</i> aller auprès ; προσέρχεσθαι ἐγγ. SOPH. <i>Ph. 788 ou</i> προσιέναι, PLAT. <i>Charm. 154</i> a, s’avancer auprès ; μάλ' ἐγγ. IL. <i>4, 496,</i> tout auprès ; <i>avec un gén</i>. ἐγγ. ὁδοῖο, IL. <i>10, 274 ;</i> πόλιος, HÉS. <i>O. 473,</i> près de la route, de la ville ; <i>avec le dat. en poésie,</i> EUR. <i>Her. 37 ; arch</i>. ἐνγὺς ὁδῷ (<i>poét</i>.) CIA. <i>1, 465, 2-3 (6<sup>e</sup> siècle av. J.C</i>.) près de la route ;<br><b>      2</b> (<i>avec idée de temps</i>) proche, IL. <i>22, 453 ;</i> OD. <i>10, 86 ;</i> XÉN. <i>Cyr. 2, 3, 2 ;</i> PLAT. <i>Pol. 273</i> c ;<br><b>      3</b> (<i>avec idée de nombre) avec un gén</i>. ἐγγ. μυρίων, XÉN. <i>An. 5, 7, 9,</i> près de 10 000 ; <i>cf</i>. HPC. <i>1217</i> d ; DH. <i>3, 10 ;</i><br><b>      4</b> <i>fig. très souv. au comp. ou au sup. avec le gén. ou le dat. avec idée de parenté ;</i> Ζηνὸς ἐγγ. ESCHL. <i>fr. 155,</i> parent de Zeus ; ἐγγ. γένους, CIA. <i>1, 8, 6 (500/450 av. J.C</i>.) ; ESCHL. <i>Suppl. 388 ;</i> AR. <i>Av. 1666 ;</i> PLAT. <i>Hipp. ma. 304</i> d ; <i>ou</i> ἐγγ. γένει, PLAT. <i>Ap. 30</i> a, proche par la naissance ;<br><b>      5</b> (<i>avec idée de ressemblance</i>) ἐγγ. τι ἢ παραπλήσιον, PLAT. <i>Gorg. 520</i> a, qqe ch. de très proche <i>ou</i> de voisin ; ἐγγύς τι τοῦ τεθνάναι, PLAT. <i>Phæd. 65</i> a, bien près d’être mort, ressembler presque à un mort ; ἐγγ. φαίνονται τυφλῶν, PLAT. <i>Rsp. 508</i> c, ils sont bien près de ressembler à des aveugles ; οὐκ ἐποίουν ταῦτα οὐδ' ἐγγύς, DÉM. <i>524, 2,</i> ils ne faisaient ni cela, ni même à peu près cela.<br><span>•<i> Cp</i>. ἐγγύτερον, XÉN. <i>Cyr. 7, 1, 23, etc. ; An. 1, 8, 8, etc. ; ou</i> ἐγγυτέρω, SOPH. <i>O.R. 1215 ;</i> THC. <i>2, 21 et 89 ; 4, 73 ; etc. ;</i> ἔγγιον, HPC. <i>356, 32, etc. ;</i> POL. <i>16, 17, 3 ;</i> ἐξ ἐγγίονος, <i>m. sign</i>. APP. <i>Civ. 4, 108</i>. <i>• Sup</i>. ἐγγύτατα, THC. <i>1, 13, 22, 143 ; 3, 40 ;</i> XÉN. <i>Cyr. 5, 4, 42 ;</i> PLAT. <i>Phæd. 65</i> e ; ἐγγυτάτω, SOPH. <i>Ant. 933 ;</i> THC. <i>3, 61 ;</i> XÉN. <i>Mem. 1, 6, 10 ; etc. ;</i> ἔγγιστα, HPC. <i>353, 32, etc.,</i> DÉM. <i>282, 28 ;</i> ANT. <i>129, 14 ;</i> SPT. <i>Num. 27, 11, etc</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγγυς - ἐγγύς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n30 fois dans 30 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Jean (11)</li>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1452":"<h1>egguteron</h1>\n<p>Strong n° 1452 <i>Prononciation [eng-goo'-ter-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>plus près de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγγύτερος, α, ον</b>, <i>cp. de</i> ἐγγύς, plus proche, plus voisin, <i>avec le gén. ou le dat</i>. JUL. <i>Ep. 1, p. 4</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγγυτερον - ἐγγύτερον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G1453":"<h1>egeiro</h1>\n<p>Strong n° 1453 <i>Prononciation [eg-i'-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>réveiller, faire lever\n<ol type=\"a\">\n<li>réveiller du sommeil, s'éveiller</li>\n<li>se réveiller du sommeil de la mort, revenir à la vie</li>\n<li>faire lever d'un lit, d'un siège ...</li>\n<li>se lever, apparaître\n<ol>\n<li>faire apparaître, présenter au public</li>\n<li>un immeuble : élever, construire, ériger</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγείρω</b> <span>(<i>impf</i>. ἤγειρον, <i>f</i>. ἐγερῶ, <i>ao</i>. ἤγειρα, <i>pf</i>. ἐγήγερκα, <i>pl.q.pf</i>. ἐγηγέρκειν ; <i>pf. et pl.q.pf.2 au sens intr</i>. ἐγρήγορα, ἐγρηγόρειν <i>et</i> ἠγρηγόρειν ; <i>pass. f</i>. ἐγερθήσομαι, <i>ao</i>. ἠγέρθην, <i>pf</i>. ἐγήγερμαι, <i>pl.q.pf</i>. ἐγηγέρμην)</span><br><b>   I <i>tr</i>.<br>      1</b> faire lever, <i>d’où</i> éveiller : τινὰ ἐξ ὕπνου, IL. <i>5, 413, litt</i>. éveiller qqn de son sommeil ; <i>abs</i>. ESCHL. <i>Eum. 140, etc</i>. réveiller qqn ; <i>p. anal</i>. ἐγ. νεκρούς, NT. <i>Matth. 10, 8 ; Joh. 5, 21 ; ou</i> ἐκ νεκρῶν, NT. <i>1Cor. 15, 42,</i> ressusciter des morts <i>ou</i> d’entre les morts ;<br><b>      2</b> ériger, dresser, mettre debout (une construction) CALL. <i>Ap. 64 ;</i> πύργους, DC. <i>42, 12,</i> élever des tours ; τρόπαιον, DC. <i>42, 48,</i> ériger un trophée ; ναόν, NT. <i>Joh. 2, 20,</i> rebâtir un temple ;<br><b>      3</b> <i>fig</i>. exciter : τινά, HÉS. <i>O. 571, etc</i>. exciter qqn (au travail, <i>etc</i>.) ; τινὰ ἐπὶ ἔργον, HÉS. <i>O. 20,</i> exciter qqn à un travail ; ὀργήν, HDN <i>5, 1,</i> exciter la colère ; μάχην, HÉS. <i>Th. 666, 713 ;</i> πόλεμον, THC. <i>1, 121,</i> provoquer un combat, une guerre ; λύραν, PD. <i>N. 10, 21 ;</i> θρῆνον, SOPH. <i>O.C. 1779 ;</i> μῦθον, PLAT. <i>Pol. 272</i> d, faire résonner la lyre, faire retentir des gémissements, faire entendre une parole ;<br><b>   II <i>intr.</i></b> s’éveiller : ἔγειρ', EUR. <i>I.A. 624 (dout</i>.) éveille-toi ; <i>d’ord. en ce sens au pf</i>. ἐγρήγορα, IL. <i>7, 371 ; 10, 419, etc. ; p. opp. à</i> καθεύδω, PLAT. <i>Theæt. 158</i> b ;<br><b><i>Moy</i>. ἐγείρομαι</b> <span>(<i>f</i>. ἐγεροῦμαι, <i>ao.2</i> ἐγρόμην)</span><br><b>      1</b> s’éveiller : ἐξ ὕπνου, IL. <i>2, 41,</i> s’éveiller de son sommeil ; <i>abs</i>. OD. <i>15, 46 ;</i> AR. <i>Vesp. 774 ;</i><br><b>      2</b> <i>p. suite,</i> être éveillé, <i>fig</i>. être vigilant, ESCHL. <i>Eum. 676 ;</i><br><b>      3</b> se lever, IL. <i>7, 434</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impf. épq</i>. ἔγειρον, IL. <i>15, 594. Ao. poét</i>. ἔγειρα, OD. <i>15, 45 ;</i> HÉS. <i>Th. 713 ;</i> PD. <i>N. 10, 21 ; sbj. 3 sg. épq</i>. ἐγείρῃσιν, IL. <i>10, 511 ; 1 pl. épq</i>. ἐγείρομεν, IL. <i>2, 440. Pf. réc</i>. ἐγήγερκα, PHILSTR. <i>Ep. 16. Pl.q.pf</i>. ἐγηγέρκειν, DC. <i>42, 48 ;</i> JOS. <i>A.J. 17, 7, 4. Pf. 2</i> ἐγρήγορα, AR. <i>Lys. 306 ;</i> XÉN. <i>Cyr. 4, 5, 7, etc. ; d’où pl.q.pf</i>. ἐγρηγόρειν (<i>sel. d’autres</i> ἐγρηγόρη) AR. <i>Eccl. 32, etc. ; rar</i>. ἠγρηγόρειν, MÉN. (<i>Com. fr. 4, 309). Pf. épq</i>. ἐγρήγορθα, <i>d’où 3 pl</i>. ἐγρηγόρθασι <span>[ᾰ]</span> IL. <i>10, 419 ; impér</i>. ἐγρήγορθε, IL. <i>7, 371 ; inf</i>. ἐγρηγόρθαι <i>ou</i> ἐγρήγορθαι, IL. <i>10, 67. — Pass. fut. réc</i>. ἐγερθήσομαι, BABR. <i>49, 3. Ao</i>. ἠγέρθην, POLYEN <i>1, 30, 4, 3 pl. épq</i>. ἔγερθεν (<i>p</i>. -ησαν) IL. <i>23, 287 (var</i>. ἄγερθεν). — <i>Moy. prés</i>. ἐγείρομαι, OD. <i>20, 100 (part</i>. -όμενος) <i>etc. Fut. réc. inf</i>. ἐγερεῖσθαι, POLYEN <i>1, 30, 4. Ao.2 épq</i>. ἐγρόμην, IL. <i>2, 41 ; 15, 4 ;</i> OD. <i>13, 187, etc. ; impér. 2 sg</i>. ἔγρεο, IL. <i>10, 159 ;</i> OD. <i>23, 5 ; etc. ; 2 pl</i>. ἔγρεσθε, EUR. <i>Rhes. 532, 533 ;</i> A. RH. <i>2, 884 ; sbj. 2 sg</i>. ἔγρῃ, AR. <i>Vesp. 774 ; 3 sg</i>. ἔγρηται, HPC. <i>8, 324 Littré ; opt. 3 sg</i>. ἔγροιτο, OD. <i>6, 113 ; inf</i>. ἐγρέσθαι (<i>sel. d’autres</i> ἔγρεσθαι) OD. <i>13, 124 ; part</i>. ἐγρόμενος, OD. <i>10, 50 ;</i> PLAT. <i>Lys. 204</i> d, <i>etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₁ger-, éveiller, <i>cf</i>. ἔγρω ; <i>p</i>. ἐγρήγορα, <i>cf. sanscr</i>. jāgā́ra.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγειρω - ἐγείρω</font>\n<br><br>probablement parent de  (à travers l'idée de rassembler ses facultés)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n141 fois dans 135 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (33)</li>\n<li>Marc (18)</li>\n<li>Luc (19)</li>\n<li>Jean (13)</li>\n<li>Actes (14)</li>\n<li>Romains (10)</li>\n<li>1 Corinthiens (20)</li>\n<li>2 Corinthiens (4)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1454":"<h1>egersis</h1>\n<p>Strong n° 1454 <i>Prononciation [eg'-er-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un réveil, une excitation</li>\n<li>se lever</li>\n<li>résurrection de la mort</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔγερσις, εως (ἡ) :<br>      1</b> érection, construction, HDN <i>8, 5 ;</i><br><b>      2</b> action d’éveiller, <i>d’où</i> réveil, HPC. <i>129 au plur. ; d’où</i> résurrection, NT. <i>Matth. 27, 53 ; fig</i>. excitation, PLAT. <i>Tim. 70</i> a ; ARSTT. <i>Nic. 3, 11</i>.<br><span><b>Étym</b>. ἐγείρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγερσις - ἔγερσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G1455":"<h1>egkathetos</h1>\n<p>Strong n° 1455 <i>Prononciation [eng-kath'-et-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>envoyé secret, un espion</li>\n<li>celui qui est payé par d'autres pour tromper par des paroles rusées</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·κάθετος, ος, ον :<br>      1</b> aposté, suborné, PLAT. <i>Ax. 368</i> e ; POL. <i>13, 5, 1 ;</i> JOS. <i>B.J. 2, 2, 5 ;</i> NT. <i>Luc. 20, 20 ;</i><br><b>      2</b> supposé, simulé, HYPÉR. (<i>Bkk. 96, 30</i>).<br><span><b>Étym</b>. ἐγκατατίθημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκαθετος - ἐγκάθετος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1456":"<h1>egkainia</h1>\n<p>Strong n° 1456 <i>Prononciation [eng-kah'-ee-nee-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dédicace, consécration\n<ol type=\"a\">\n<li>fête annuelle célébrée pendant huit jours, commençant le 25 de Chisleu (mi-décembre pour nous) instituée par Judas Maccabaeus (164 Av. JC) en mémoire de la purification du temple qui avait était profané par Antiochus Epiphanes</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·καίνια, ων (τὰ)</b> fête d’inauguration (d’un temple) <i>chez les Juifs,</i> SPT. <i>Dan. 3, 2 ;</i> NT. <i>Joh. 10, 22</i>.<br><span><b>Étym</b>. ἐν, καινός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκαινια - ἐγκαίνια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1457":"<h1>egkainizo</h1>\n<p>Strong n° 1457 <i>Prononciation [eng-kahee-nid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>renouveler, faire renouvellement</li>\n<li>faire à nouveau, refaire, faire nouvellement, frayer récemment</li>\n<li>commencer, inaugurer, consacrer, dédier, dédicacer, renouveler d'où consacrer</li>\n<li>le verbe grec καινιζω signifie : faire une chose pour la première fois, innover, inaugurer\n<ol type=\"a\">\n<li>faire quelque chose de nouveau, d'inusité, d'étrange ce verbe est employé deux fois dans le N.T, une fois en rapport avec l'inauguration de la nouvelle Alliance et une fois avec l'inauguration du nouveau chemin menant dans le Lieu très Saint, dans les deux cas au moyen du sang de Jésus-Christ.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·καινίζω :<br>      1</b> faire nouvellement : ἣν ἐνεκαίνισεν ὁδόν, NT. <i>Hebr. 10, 20,</i> la route qu’il a frayée récemment ;<br><b>      2</b> restaurer : τεῖχος, SPT. <i>Esaï. 16, 11,</i> un mur ; τὴν βασιλείαν, SPT. <i>1Reg. 11, 14,</i> la royauté ; πνεῦμα, SPT. <i>Ps. 51, 10,</i> ranimer le souffle ;<br><b>      3</b> <i>p. suite,</i> renouveler, <i>d’où</i> consacrer, SPT. <i>1Reg. 11, 14 ; 3Reg. 8, 63 ;</i> NT. <i>Hebr. 9, 18</i>.<br><span><b>Étym</b>. ἐν, καινός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκαινιζω - ἐγκαινίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G1458":"<h1>egkaleo</h1>\n<p>Strong n° 1458 <i>Prononciation [eng-kal-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'avancer en accusateur, apporter des charges contre</li>\n<li>être accusé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγκαλέω-ῶ</b> <span>[ᾰ]</span> <span>(<i>f</i>. -έσω, <i>ao</i>. ἐνεκάλεσα, <i>pf</i>. ἐγκέκληκα ; <i>f. pass</i>. ἐγκληθήσομαι)</span><br><b>      1</b> réclamer : τι, XÉN. <i>An. 7, 7, 33 ;</i> DÉM. <i>877, 21 ; 949, 1,</i> qqe ch. ; χρέος, ISOCR. <i>402</i> c, une dette ;<br><b>      2</b> reprocher, accuser ; adresser un reproche, une accusation ; <i>avec double rég</i>. ἐγκ. τινί τι, SOPH. <i>El. 768 ;</i> PLAT. <i>Ap. 26</i> c ; PLUT. <i>Lyc. 18 ;</i> LUC. <i>Abd. 7, etc. ;</i> τι κατά τινος, SOPH. <i>Ph. 328,</i> accuser qqn de qqe ch. ; τινι ὅτι, XÉN. <i>An. 7, 5, 7, ou</i> τινι <i>avec l’inf</i>. THC. <i>4, 123,</i> accuser qqn de, <i>etc. ; avec un part</i>. ἐγκ. αὐτοῖς ἀμελοῦσιν, PLAT. <i>Prot. 346</i> a, les accuser de négligence ; <i>avec un seul acc. de chose :</i> ἐγκ. τι, THC. <i>5, 46 ;</i> PLAT. <i>Theæt. 168</i> e, blâmer qqe ch. ; ἐγκ. νεῖκος, SOPH. <i>O.R. 702,</i> accuser qqn d’être l’auteur d’une querelle ; <i>particul</i>. accuser en justice : <i>abs</i>. DÉM. <i>907, 6 ; avec un dat</i>. ἐγκ. τινι, A. TAT. <i>7, 13,</i> accuser qqn ; <i>avec double rég</i>. τινί τι, PLAT. <i>Ap. 27</i> e ; DH. <i>9, 8,</i> qqn de qqe ch. ; τινι δίκην, DÉM. <i>1014, 18,</i> intenter une accusation à qqn ; τινι περί τινος, ISOCR. <i>48</i> c, à qqn sur qqe ch. ; <i>au pass</i>. être accusé : ὑπέρ τινος, DH. <i>7, 46 ;</i> τινος, DC. <i>58, 4,</i> de qqe ch. ; <i>impers</i>. ἐγκαλεῖται τῇ τύχῃ ὅτι, ARSTT. <i>Nic. 4, 1, 21,</i> on fait un crime à la fortune de ce que ; τὰ ἐγκαλούμενα, POL. <i>5, 27, 5,</i> les griefs allégués ;<br><b>      3</b> invoquer, implorer qqe ch. (une faveur, un secours) <i>acc</i>. STR. <i>649</i>.<br><span><b>Étym</b>. ἐν, κ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκαλεω - ἐγκαλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (6)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G1459":"<h1>egkataleipo</h1>\n<p>Strong n° 1459 <i>Prononciation [eng-kat-al-i'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>abandon, désert\n<ol type=\"a\">\n<li>laisser sans aide,</li>\n<li>totalement abandonné, absolument seul</li>\n</ol>\n</li>\n<li>laisser derrière soi, laisser subsister</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·καταλείπω</b> <span>(<i>ao.2</i> ἐγκατέλιπον, <i>pf</i>. ἐγκαταλέλοιπα)</span><br><b>      1</b> laisser dans : ἐγκ. τὸ κέντρον, PLAT. <i>Phæd. 91</i> c, laisser l’aiguillon dans (la plaie) <i>en parl. d’une abeille ; avec le dat</i>. τὸ κέντρον ἐγκ. τοῖς ἀκροωμένοις, EUP. <i>2-1, 458 Meineke</i> laisser l’aiguillon dans l’esprit de ses auditeurs ; <i>ou</i> ἐν <i>et le dat</i>. ἐν νήσῳ φρουρὰν ἐγκ. THC. <i>3, 51,</i> laisser une garnison dans une île ;<br><b>      2</b> laisser après soi <i>ou</i> derrière soi dans une course, <i>d’où au pass</i>. rester en arrière, HDT. <i>8, 59 ; en parl. de survivants,</i> HÉS. <i>O. 376 ;</i> DÉM. <i>1087 ;</i><br><b>      3</b> abandonner, délaisser : νεκρούς, THC. <i>4, 44,</i> abandonner ses morts ; τὴν ἀκρόπολιν, XÉN. <i>Hell. 5, 4, 13,</i> abandonner l’acropole ; τὰ τέκνα καὶ τοὺς τῶν φίλων παῖδας ὁμήρους ἐγκ. XÉN. <i>Cyr. 8, 8, 4,</i> laisser en otage ses enfants et ceux de ses amis ; <i>cf</i>. PLAT. <i>Conv. 179</i> a ; DÉM. <i>1316, 25 ; etc</i>.<br><span><b>Étym</b>. ἐν. κ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκαταλειπω - ἐγκαταλείπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G1460":"<h1>egkatoikeo</h1>\n<p>Strong n° 1460 <i>Prononciation [eng-kat-oy-keh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>demeurer parmi, habiter parmi</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·κατοικέω-ῶ</b>, habiter dans <i>ou</i> parmi, <i>dat</i>. HDT. <i>4, 204 ;</i> EUR. <i>fr. 188 ; fig</i>. résider dans (l’âme) <i>en parl. de la conscience,</i> POL. <i>18, 26, 13 ; de la douceur,</i> THÉM. <i>51</i> d.<br><span><b>Étym</b>. ἐν, κ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκατοικεω - ἐγκατοικέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1461":"<h1>egkentrizo</h1>\n<p>Strong n° 1461 <i>Prononciation [eng-ken-trid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>inciser pour une greffe ou insérer un scion</li>\n<li>inoculer, greffer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·κεντρίζω :<br>      1</b> aiguillonner, éperonner, SPT. <i>Sap. 16, 11 ;</i><br><b>      2</b> greffer, ARSTT. <i>Plant. 1, 6, 2 ;</i> TH. <i>H.P. 2, 2, 5, etc</i>.<br><span><b>Étym</b>. ἐν, κ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκεντριζω - ἐγκεντρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Romains (6)</li>\n</ul>\n</td></tr>\n</table>","G1462":"<h1>egklema</h1>\n<p>Strong n° 1462 <i>Prononciation [eng'-klay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>accusation : le crime dont quelqu'un est accusé, grief, chef d'accusation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔγκλημα, ατος (τὸ) :<br>      1</b> chef d’accusation, grief, accusation, SOPH. <i>Ph. 323, etc. ;</i> PLAT. <i>Phil. 22</i> c ; ὑπέρ τινος, LYS. <i>3, 1 Baiter-Sauppe,</i> au sujet de qqe ch. ; ποιεῖν, THC. <i>3, 43, ou</i> ποιεῖσθαι, THC. <i>1, 126,</i> porter une accusation ; ἔς τινα, THC. <i>1, 79 ;</i> πρός τινα, PLAT. <i>Leg. 685</i> c, contre qqn ; ἐν ἐγκλήματι γίγνεσθαι, DÉM. <i>311, 2 ;</i> ARSTT. <i>Nic. 9, 1,</i> être l’objet d’une accusation ; <i>avec le gén. de la pers. :</i> τὰ ἀλλήλων ἐγκλήματα διαιρεῖν, PLAT. <i>Pol. 305</i> c, trancher les griefs mutuels, <i>ou</i> réciproques ; <i>ou avec le gén. du grief :</i> πάντων τούτων ἐγκλήματα ἔχοντες, THC. <i>1, 26,</i> ayant sur tout cela des griefs ; γίγνεται παισὶ πρὸς ἀλλήλους ἐγκλήματα, XÉN. <i>Cyr. 1, 2, 6,</i> il arrive que les enfants s’accusent les uns les autres ; ἐγκλήματα διαλύεσθαι, THC. <i>1, 140 ou</i> λύειν ἔγκλημα, POL. <i>2, 52, 4,</i> détruire (<i>litt</i>. dissoudre) des accusations ; ἀπολῦσαί τινα τῶν ἐγκλημάτων, DS. <i>16, 52 ; 17, 15,</i> décharger qqn des accusations portées contre lui ;<br><b>      2</b> <i>particul</i>. plainte écrite remise par le plaignant aux magistrats, DÉM. <i>912, 2 ; 950, 21, etc. ;</i><br><b>      3</b> sujet de reproche, motif de honte, PALÆPH. <i>49, 1</i>.<br><span><b>Étym</b>. ἐγκαλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκλημα - ἔγκλημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – accuser avec en première référence la base de l'accusation, le crime\n<br><br> – procéder à un assaut verbal qui atteint son but\n<br><br> – accuser formellement devant un tribunal, apporter publiquement une charge</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G1463":"<h1>egkomboomai</h1>\n<p>Strong n° 1463 <i>Prononciation [eng-kom-bo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lien ou bande par laquelle deux choses sont liées ensemble, se revêtir ou se ceindre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·κομϐόομαι-οῦμαι</b>, boutonner sur soi, <i>càd</i>. s’envelopper en se boutonnant, A. CARYST. <i>fr. 3 ; fig</i>. ἐ. ταπεινοφροσύνην, NT. <i>1Petr. 5, 5,</i> s’envelopper de modestie.<br><span><b>Étym</b>. ἐν, κ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκομβοομαι - ἐγκομβόομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1464":"<h1>egkope</h1>\n<p>Strong n° 1464 <i>Prononciation [eng-kop-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une coupure (de route pour empêcher l'avance de l'ennemi)</li>\n<li>un obstacle, une entrave, empêchement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγκοπή, ῆς (ἡ) :<br>   I</b> incision, <i>d’où :</i><br><b>      1</b> entaille, GAL. <i>4, 399 ;</i><br><b>      2</b> crevasse (dans un rocher) DS. <i>1, 32 ;</i><br><b>      3</b> sorte de fracture, SOR. <i>Fract. 249, 5 Id. ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> interruption, DH. <i>Comp. 22 ;</i> LGN <i>41, 3 ;</i><br><b>      2</b> <i>p. suite,</i> obstacle, NT. <i>1Cor. 9, 12</i>.<br><span><b>Étym</b>. ἐγκόπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκοπη - ἐγκοπή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1465":"<h1>egkopto</h1>\n<p>Strong n° 1465 <i>Prononciation [eng-kop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>couper, arrêter une marche en coupant la route</li>\n<li>empêcher, faire obstacle, contrarier</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·κόπτω :<br>      1</b> enfoncer (un clou, <i>etc</i>.) en frappant dans, <i>dat</i>. TH. <i>H.P. 2, 7, 6 ;</i><br><b>      2</b> faire une incision dans, HPC. <i>28, 35 ;</i><br><b>      3</b> faire obstacle, barrer le chemin à, <i>dat</i>. POL. <i>24, 1, 12</i>.<br><span><b>Étym</b>. ἐν, κ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκοπτω - ἐγκόπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Galates (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G1466":"<h1>egkrateia</h1>\n<p>Strong n° 1466 <i>Prononciation [eng-krat'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>contrôle de soi, vertu de ceux qui sont maîtres de leurs désirs et de leurs passions, en particulier des appétits des sens, maîtrise de soi empire sur soi-même, modération</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγκράτεια, ας (ἡ)</b> <span>[ρᾰ]</span> empire sur soi-même, modération, XÉN. <i>Mem. 1, 5, 4 ;</i> ARSTT. <i>Nic. 7, 4 ; joint à</i> καρτερία, ARSTT. <i>Nic. 7, 2 ;</i> PLUT. <i>M. 1040</i> f, <i>etc</i>. ἐγκρ. τινος, XÉN. <i>Ages. 4, 3 ;</i> ISOCR. <i>6</i> c, <i>etc. ; ou</i> πρός τι, XÉN. <i>Mem. 2, 1, 1 ;</i> PLAT. <i>Def. 412</i> a ; PLUT. <i>T. Gracch. 3,</i> modération en qqe ch. (plaisirs, désirs, <i>etc</i>.).<br><span><b>Étym</b>. ἐγκρατής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκρατεια - ἐγκράτεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Galates (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G1467":"<h1>egkrateuomai</h1>\n<p>Strong n° 1467 <i>Prononciation [eng-krat-yoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se contrôler, se contenir, être continent, se dominer\n<ol type=\"a\">\n<li>montrer sa maîtrise de soi, se conduire avec tempérance</li>\n<li>image des athlètes se préparant à des jeux et s'abstenant de certaines nourritures, de vin, et de contacts sexuels</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγκρατεύομαι</b> <span>[ᾰ]</span><br><b>      1</b> <i>abs</i>. être maître de soi, ARSTT. <i>Eud. 2, 7, 6 ;</i> SPT. <i>Gen. 43, 30 ;</i> NT. <i>1Cor. 7, 9 ; 9, 25 ;</i><br><b>      2</b> <i>avec le gén</i>. s’abstenir de, CLÉM. <i>566 ;</i><br><b>      3</b> être le plus fort, l’emporter sur, SPT. <i>1Reg. 13, 12</i>.<br><span><b>Étym</b>. ἐγκρατής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκρατευομαι - ἐγκρατεύομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G1468":"<h1>egkrates</h1>\n<p>Strong n° 1468 <i>Prononciation [eng-krat-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fort, robuste, vigoureux</li>\n<li>ayant du pouvoir sur, qui est en possession du pouvoir, puissant</li>\n<li>maîtrise, contrôle, maître de, être bridé, se contenir, maîtrise de soi, qui se gouverne ou se contrôle soi-même, maître de soi-même, continent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·κρατής, ής, ές</b> <span>[ᾰ]</span><br><b>   I</b> qui a de la force en soi-même, <i>d’où :</i><br><b>      1</b> fort, vigoureux, ESCHL. <i>Pr. 55 ;</i> SOPH. <i>Ant. 474 ;</i> XÉN. <i>Hell. 7, 1, 23 ; Eq. 1, 8 ; etc. ;</i><br><b>      2</b> qui est en possession du pouvoir, puissant, SOPH. <i>O.R. 941 ;</i><br><b>   II</b> maître de, <i>gén. :</i> τῆς Ἑλλάδος, HDT. <i>9, 106 (cf</i>. HDT. <i>8, 49 ;</i> THC. <i>5, 35, etc</i>.) maître de la Grèce ; <i>abs</i>. ἐγκρατής, qui se gouverne <i>ou</i> se contrôle soi-même, PLAT. <i>Def. 415</i> d ; ἐγκρ. ἑαυτοῦ, PLAT. <i>Phædr. 256</i> b, maître de soi-même ; ἐγκρ. γαστρὸς καὶ ποτοῦ, XÉN. <i>Cyr. 1, 2, 8 ;</i> γαστρὸς καὶ οἴνου, XÉN. <i>Œc. 9, 11 ;</i> ἀφροδισίων καὶ γαστρός, XÉN. <i>Mem. 1, 2, 1,</i> qui maîtrise son appétit et son désir de boire ; modéré dans l’usage de la nourriture et du vin, du sexe et de la nourriture ; <i>abs</i>. ἐγκρατής, maître de soi, tempérant, continent, ARSTT. <i>Nic. 7, 4, 4</i>.<br><span>•<i> Cp</i>. -έστερος, THC. <i>1, 118 ;</i> DH. <i>3, 28 ;</i> PLUT. <i>Arist. 25</i>. <i>• Sup</i>. -έστατος, SOPH. <i>Ant. 474 ;</i> XÉN. <i>Mem. 1, 2, 1 ; Hell. 7, 1, 23 ; Eq. 1, 8 ; Cyn. 10, 1 ; etc</i>.<br><span><b>Étym</b>. ἐν, κράτος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκρατης - ἐγκρατής</font>\n<br><br>Voir définition \n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G1469":"<h1>egkrino</h1>\n<p>Strong n° 1469 <i>Prononciation [eng-kree'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>compter parmi, juger entre, mettre au nombre de, compter au nombre de</li>\n<li>juger quelqu'un digne d'être admis à une certaine classe, comparer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·κρίνω</b> <span>[ῑ]</span><br><b>      1</b> choisir dans <i>ou</i> parmi : τινὰ ἄριστον ἐγκρ. EUR. <i>H.f. 183,</i> choisir qqn comme le meilleur entre tous ; <i>p. opp. à</i> ἀποκρίνω, PLAT. <i>Leg. 936</i> a ;<br><b>      2</b> <i>p. suite,</i> admettre après examen, décider d’admettre parmi : εἰς τὸ στάδιον, XÉN. <i>Hell. 4, 1, 40,</i> dans le stade ; εἰς τὴν γερουσίαν, DÉM. <i>489, 19,</i> dans le sénat ; <i>cf</i>. PLAT. <i>Leg. 755</i> d ; <i>d’où abs</i>. accepter après examen <i>ou</i> après réflexion, approuver, POL. <i>9, 2, 4 ;</i> PLUT. <i>Lyc. 18, M. 11</i> f ;<br><b><i>Moy.</i></b> (<i>seul. ao. poét. de forme pass</i>. ἐνικρινθῆναι) se mêler à, <i>dat</i>. A. RH. <i>1, 48 et 227</i>.<br><span><b>Étym</b>. ἐν, κρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκρινω - ἐγκρίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1470":"<h1>ekgrupto</h1>\n<p>Strong n° 1470 <i>Prononciation [eng-kroop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>cacher dans quelque chose</li>\n<li>mêler une chose avec une autre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·κρύπτω</b> <span>(<i>f</i>. -κρύψω, <i>ao</i>. ἐνέκρυψα ; <i>pf. pass</i>. ἐγκέκρυμμαι)</span> cacher dans : τί τινι, OD. <i>5, 488 ;</i> τι ἔν τινι, ARSTT. <i>H.A. 9, 33 ;</i> τι εἴς τι, APD. <i>1, 5, 1, 4,</i> cacher une chose dans une autre ; πῦρ ἔγκ. AR. <i>Av. 841,</i> tenir du feu caché (sous la cendre) ;<br><b><i>Moy.</i></b> se cacher dans, <i>dat</i>. NONN. <i>D. 2, 74</i>.<br><span><b>Étym</b>. ἐν, κ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκρυπτω - ἐγκρύπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1471":"<h1>egkuos</h1>\n<p>Strong n° 1471 <i>Prononciation [eng'-koo-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>grosse d'un enfant, enceinte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔγ·κυος, ος, ον</b>, <i>c</i>. ἐγκύμων <i>au pr. en parl. de pers</i>. ARSTT. <i>H.A. 3, 20 ;</i> DH. <i>9, 22 ;</i> DS. <i>4, 2 ; d’animaux,</i> ARSTT. <i>H.A. 5, 5 ; fig</i>. ANTH. <i>9, 156 ;</i> NONN. <i>D. 3, 29, etc</i>.<br><span><b>Étym</b>. ἐν, κυέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγκυος - ἔγκυος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1472":"<h1>egchrio</h1>\n<p>Strong n° 1472 <i>Prononciation [eng-khree'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>frotter, tacher, oindre</li>\n<li>se oindre soi-même</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγ·χρίω</b> <span>[ῑ]</span><br><b>      1</b> étendre un enduit : ἐγχρ. τινά, ANTH. <i>11, 117, 1 ; 122, 2 ; 126, 5,</i> oindre qqn ; τινι ἐγχρ. τινά (ATH. <i>542</i> d) ; <i>ou</i> τί τινι, DC. <i>72, 14 ;</i> SPT. <i>Jer. 3, 30 ;</i> ἐγχρ. τι εἴς τι, SPT. <i>Tob. 11, 7 ;</i> τὶ ἐγχρ. τι, NT. <i>Apoc. 3, 18,</i> enduire qqn <i>ou</i> qqe ch. d’une substance ; <i>fig</i>. LYC. <i>1455 ;</i><br><b>      2</b> enduire dans, <i>càd</i>. enfoncer le suc, le venin, <i>etc</i>. EL. <i>N.A. 1, 54 ; 6, 20 ; d’où abs</i>. piquer, mordre, PLAT. <i>Phædr. 251</i> d ;<br><b><i>Moy.</i></b> s’enduire de, <i>gén</i>. STR. <i>699 ; abs</i>. ARR. <i>Epict. 2, 21, 20</i>.<br><span><b>Étym</b>. ἐν, χρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγχριω - ἐγχρίω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1473":"<h1>ego</h1>\n<p>Strong n° 1473 <i>Prononciation [eg-o']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>Je, moi, mon, ma, mes ...</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐγώ</b>, <i>pron. pers. de la 1<sup>re</sup> pers. se décline : sg</i>. ἐγώ ; ἐμοῦ, μοῦ ; ἐμοί, μοί ; ἐμέ, μέ ; <i>plur</i>. ἡμεῖς, ἡμῶν, ἡμῖν, ἡμᾶς ; <i>duel</i> νώ, νῷν. ;<br><b>A</b> <i>Singul. :</i><br><b>   I</b> <i>Le nomin. s’exprime qqf. sans intention apparente,</i> SOPH. <i>O.R. 317, 599 ; O.C. 269, 948, etc. ; mais d’ord. on ne l’ajoute au verbe que lorsqu’on veut désigner avec plus de force la personne qui parle, particul. :</i><br><b>      1</b> <i>lorsque le pron. est déterminé par un relat</i>. ἐγὼ (<i>var</i>. ἐγών) τόν, THCR. <i>Idyl. 14, 34,</i> moi que, <i>etc. ;</i><br><b>      2</b> <i>lorsqu’il est joint à un n. propre :</i> ἐγὼ Δάφνις, THCR. <i>Idyl. 1, 116 ; ou</i> Δάφνις ἐγώ, THCR. <i>Idyl. 27, 41,</i> moi Daphnis ;<br><b>      3</b> <i>p. opp. à d’autres pers</i>. νῶϊ δ', ἐγὼ Σθένελός τε μαχησόμεθ', IL. <i>9, 48,</i> tous deux, Sthénélos et moi, nous combattrons ; ἐγὼ καὶ σύ, XÉN. <i>Cyr. 1, 6, 7,</i> toi et moi ; <i>cf</i>. THCR. <i>Idyl. 7, 1 ; 22, 175 ;</i><br><b>      4</b> <i>dans les réponses, il s’exprime souv. sans verbe, pour marquer l’affirmation (au sens de notre oui), précédé de οὐκ pour marquer la négation (au sens de notre non), en s.-e. le verbe que suppose la question :</i> ἐξ αὐλᾶς, ὦ μᾶτερ ; ἐγών, ὦ τέκνα, THCR. <i>Idyl. 15, 60,</i> viens-tu du palais, la mère ? oui, mes enfants (<i>cf</i>. ἔγωγε) ;<br><b>      5</b> <i>dans les réponses qui procèdent par interrogation :</i> ὅσα με δέδρακας ἀγάθ'… — ἐγώ ; ἀλλ' <i>etc</i>. AR. <i>Eq. 1336,</i> (vois) quel service tu m’as rendu… — moi ? mais, <i>etc. ;</i><br><b>   II</b> ἐγώ, μοῦ, <i>etc. peuvent se construire :</i><br><b>      1</b> <i>avec un adj. démonstr. seul ou renforcé par un autre adj. démonstr. :</i> οὗτος ἐγώ, ATT. moi que voici, moi-même ; ὅδ' αὐτὸς ἐγώ, OD. <i>21, 207,</i> moi-même ici présent ; ὅδ' ἐκεῖνος ἐγώ, SOPH. <i>O.C. 138,</i> je suis celui-là ;<br><b>      2</b> <i>rar. avec l’article :</i> τίς ὢν οὗτος ὁ ἐγὼ τυγχάνω, PLUT. <i>M. 1149</i> a, qui je suis ; τὸν ἐμέ, PLAT. <i>Theæt. 166</i> a, <i>Soph. 239</i> a, <i>Phil. 20</i> b, <i>etc</i>. moi, ma personne ;<br><b>   III</b> ἐμοί, μοί, <i>sont qqf. explétifs,</i> SOPH. <i>O.R. 242, O.C. 81, Ph. 349 ;</i><br><b>   IV</b> ἐγώ <i>déterminatif d’un adj. peut être s.-entendu :</i> δύστηνος (<i>pour</i> δύστηνος ἐγώ) SOPH. <i>O.R. 1155,</i> malheureux (que je suis) ! ὦ τάλας (<i>pour</i> ὦ τάλας ἐγώ) SOPH. <i>Ph. 1083,</i> ô malheureux (que je suis) ! ;<br><b>B</b> <i>Plur</i>. ἡμεῖς <i>s’emploie :</i><br><b>      1</b> <i>d’ord. en parl. de plus de deux pers</i>. IL. <i>3, 101 ; etc. ;</i> OD. <i>24, 169, etc. ;</i> ATT. <i>etc. ;</i><br><b>      2</b> <i>qqf. pour</i> νώ, <i>en parl. de deux pers</i>. THCR. <i>Idyl. 1, 15 ; 2, 35 ; 5, 25 ; 7, 2 et 126 ; 8, 13, etc. ;</i><br><b>      3</b> <i>en parl. d’une seule pers</i>. SOPH. <i>O.R. 435, 1458 ;</i> THCR. <i>Idyl. 1, 102 ; 5, 106 ; 10, 38, etc. ;</i><br><b>C</b> <i>Duel :</i> νώ, νῷν <i>s’emploient qqf. au sens du plur</i>. IL. <i>11, 347 ; 13, 326, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Formes poét. et dialect. ;</i><br><b>A</b> <i>sing. :</i><br><b>   I</b> <i>Nomin. épq. ἐγών dev. une voy</i>. IL. <i>1, 76 ;</i> OD. <i>1, 88, etc. ; rar. att</i>. ESCHL. <i>Suppl. 748. Dor</i>. ἐγών, THCR. <i>Idyl. 1, 120 ; 15, 60 ; 21, 56 ;</i> EPICH. <i>fr. 64 Ahrens ;</i> SOPHR. <i>39 ;</i> AR. <i>Ach. 748, 754. Éol</i>. ἔγων, DYSC. <i>Pron. p. 64 ;</i><br><b>   II</b> <i>Cas obliques : les formes monosyll. μου, μοι, με sont enclit. :</i><br><b>      1</b> <i>Gén. épq. et ion</i>. ἐμεῖο, IL. <i>1, 301, etc. (37 fois dans l’IL., 12 fois dans l’OD</i>.) ; THCR. <i>Idyl. 20, 2 ;</i> ἐμέο, IL. <i>10, 124 ;</i> ἐμεῦ, IL. <i>1, 88, etc. (16 fois IL., 9 fois OD</i>.) ; THCR. <i>Idyl. 7, 86 ; 14, 21 ; 16, 73 ; 20, 10 ; avec -ευ bref,</i> THCR. <i>Idyl. 16, 21 ; 22, 61 ;</i> μευ, IL. <i>4, 37, etc. (23 fois IL. ; 36 fois OD</i>.) ; THCR. <i>Idyl. 2, 88, etc. ; avec -ευ bref,</i> THCR. <i>Ad. 32 ; Idyl. 3, 37. Éol</i>. ἐμέθεν, IL. <i>1, 525, etc. (8 fois IL. ; 9 fois OD</i>.) ; EUR. <i>Hel. 177 ; avec</i> ἐ- <i>initial long,</i> THCR. <i>Idyl. 30, 10 ;</i> μέθεν, SOPHR. <i>46 Ahrens. Dor</i>. ἐμέος, EPICH. (DYSC. <i>Pron. p. 365</i>) ; ἐμεῦς, <i>ibid. ; béot</i>. ἐμοῦς, COR. <i>33 ;</i> ἐμείω, DYSC. <i>Pron. p. 365 ;</i> ἐμείως <i>et</i> ἐμῶς, <i>Pron. ;</i><br><b>      2</b> <i>Dat</i>. ἐμοί <i>avec -οι long,</i> THCR. <i>Idyl. 4, 30 ; 25, 252, etc. ; enclit. μοι avec -οι long,</i> THCR. <i>Idyl. 2, 1 ; 4, 49, etc. ; avec -οι bref,</i> THCR. <i>Idyl. 2, 154 ; 5, 18, etc. Dor</i>. ἐμίν <span>[ῑ]</span> EPICH. <i>fr. 94, 9 Ahrens ;</i> AR. <i>Ach. 733 ;</i> THCR. <i>Idyl. 2, 144 et 156 ; 6, 37 ; 11, 44, etc. ; tarent</i>. ἐμίνη, RHINTHON (DYSC. <i>104</i> b) ;<br><b>      3</b> <i>Acc. éol</i>. ἔμε, THCR. <i>Idyl. 30, 32 ; avec élis</i>. ἔμ', THCR. <i>Idyl. 12, 8 ; 25, 238 ;</i><br><b>B</b> <i>Plur. :</i><br><b>      1</b> <i>nomin. épq. ancien éol. et dor</i>. ἄμμες, IL. <i>21, 432 ;</i> OD. <i>9, 303 ;</i> ALC. <i>18 ;</i> THCR. <i>Idyl. 5, 67 ; 14, 20, etc. Dor</i>. ἅμες, EPICH. <i>fr. 94, 6 Ahrens ;</i> AR. <i>Lys. 168 ;</i> ἁμές <span>[ᾱ]</span> THCR. <i>Idyl. 15, 132 ;</i><br><b>      2</b> <i>Gén. ion</i>. ἡμέων (<i>dissyll. par syniz</i>.) OD. <i>1, 33, etc. ;</i> ἡμείων, OD. <i>24, 158, 170. Éol</i>. ἀμμέων, ALC. <i>93 ;</i> THCR. <i>Idyl. 30, 27 Bgk (vulg</i>. ἄμμ'). <i>Dor</i>. ἁμέων <span>[ᾱ]</span> ALCM. <i>50 ; dissyll. par syniz</i>. THCR. <i>Idyl. 8, 25 ;</i> ἁμῶν, THCR. <i>Idyl. 2, 158 ; 15, 94 ;</i><br><b>      3</b> <i>Dat. ion</i>. ἧμιν <span>[ῐ]</span> IL. <i>17, 415, 417 ;</i> OD. <i>8, 569, etc. ;</i> ESCHL. <i>Eum. 347 ;</i> SOPH. <i>O.R. 53, etc. ;</i> AR. <i>Av. 386 ; enclit</i>. ἥμιν, IL. <i>1, 147, 579. Éol. et dor</i>. ἄμμι <span>[ῐ]</span> IL. <i>1, 384, etc. ;</i> THCR. <i>Idyl. 1, 102, etc. Dor</i>. ἧμιν, THCR. <i>Idyl. 25, 179 ;</i> ἁμῖν, AR. <i>Ach. 821 ;</i> THCR. <i>Idyl. 7, 11 et 145 ; 11, 7 ; 18, 28 ;</i> ἇμιν, THCR. <i>Idyl. 8, 13 ; 15, 76 ;</i> ἁμίν, ESCHL. <i>Eum. 347 ;</i> AR. <i>Lys. 1081 ;</i> THCR. <i>Idyl. 5, 25 ; 7, 2 ;</i><br><b>      4</b> <i>Acc. épq</i>. ἧμας, OD. <i>16, 372. Ion</i>. ἡμέας (<i>dissyll. par syniz</i>.) IL. <i>8, 211, etc. Épq. et ancien éol</i>. ἄμμε, IL. <i>1, 59, etc. ;</i> THCR. <i>Idyl. 5, 61 ; 8, 25, etc. Dor</i>. ἁμέ <span>[ᾱ]</span> AR. <i>Ach. 759, Lys. 95, 1099 ;</i> THCR. <i>Idyl. 11, 42 ;</i><br><b>C</b> <i>Duel :</i><br><b>      1</b> <i>nomin. épq. ion. et dor</i>. νῶϊ (<i>mais aussi νώ dans</i> OD. <i>15, 475 ; 16, 306, etc</i>.) IL. <i>4, 418 ; 5, 34, 224, 235, etc. ;</i> OD. <i>3, 168 ; 4, 160, etc. ;</i><br><b>      2</b> <i>Gén.-dat. épq. ion. et dor</i>. νῶϊν, IL. <i>11, 347 ; 13, 326, etc. ;</i> Q. SM. <i>1, 213 ;</i> THCR. <i>Idyl. 12, 10 ;</i><br><b>D</b> <i>Crases :</i><br><b>   I</b> <i>Sing. :</i><br><b>      1</b> <i>Nomin. :</i> ἐγώ <i>se joint par crase à</i> καί, <i>d’où</i> κἀγώ, κἠγώ, κἤγω (<i>pour</i> κἠγώ), <i>etc., v</i>. καί ; <i>à l’interj</i>. ἅ : ἁγώ = ἃ ἐγώ, ESCHL. <i>Suppl. 980 ; à l’article</i> ὁ : ὡγώ = ὁ ἐγώ, THCR. <i>Idyl. 2, 54 ; aux verbes</i> οἶδα (<i>d’où</i> ἐγᾦδα) <i>et</i> οἶμαι (<i>d’où</i> ἐγᾦμαι) ; <i>v. ces mots ;</i><br><b>      2</b> <i>Gén</i>. ἐμοῦ : κἀμοῦ = καὶ ἐμοῦ : <i>v</i>. καί ;<br><b>      3</b> <i>Dat</i>. μοί : μοὐστί = μοί ἐστι, ESCHL. <i>Ch. 122, etc. ;</i><br><b>      4</b> <i>Acc</i>. ἐμέ : κἀμέ, κἠμέ, κἤμε : <i>v</i>. καί ;<br><b>   II</b> <i>Plur. nomin</i>. κἄμμες <i>et acc</i>. κἄμμε : <i>v</i>. καί ;<br><b>E</b> ἐγώ <i>devient</i> 'γώ <i>par aphérèse dans</i> οἲ 'γώ, ESCHL. <i>Sept. 808, Pers. 517 ; Ch. 691, 887, 893, 928</i>.<br><span><b>Étym</b>. <i>Pour</i> ἐγώ, <i>indo-europ</i>. *h₁eǵ- + e/oH, -h₁om, <i>cf. lat</i>. egō, <i>sscr</i>. ahám ; <i>pour le th</i>. ἐμε-, <i>indo-europ</i>. *h₁me, <i>cf. lat</i>. mē, <i>sscr</i>. mā ; <i>pour le th. plur</i>. ἡμε- <i>p</i>. *ἀσμε, <i>indo-europ</i>. *n̥sme, <i>d’où épq. et éol</i>. ἄμμε, <i>cf. sscr</i>. asmā́n ; <i>pour le th. duel</i> νω-, <i>indo-europ</i>. *neh₃, <i>cf. lat</i>. nōs.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εγω - ἐγώ</font>\n<br><br>pronom de la première personne Je (seulement exprimé avec emphase)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n365 fois dans 331 versets de 23 livres bibliques (NT)\n<ul>\n<li>Matthieu (29)</li>\n<li>Marc (17)</li>\n<li>Luc (23)</li>\n<li>Jean (142)</li>\n<li>Actes (43)</li>\n<li>Romains (18)</li>\n<li>1 Corinthiens (25)</li>\n<li>2 Corinthiens (11)</li>\n<li>Galates (8)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (4)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (3)</li>\n<li>Tite (2)</li>\n<li>Philémon (4)</li>\n<li>Hébreux (7)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>2 Jean (2)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (15)</li>\n</ul>\n</td></tr>\n</table>","G1474":"<h1>edaphizo</h1>\n<p>Strong n° 1474 <i>Prononciation [ed-af-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jeter à terre, poser à même le sol\n<ol type=\"a\">\n<li>pour les villes et maisons : raser, mettre au niveau du sol</li>\n<li>métaph : des hommes</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐδαφίζω</b> <span>[ᾰ]</span> <span>(<i>f. att</i>. ιῶ, <i>ao</i>. ἠδάφισα)</span><br><b>      1</b> paver, garnir d’un pavé, TH. <i>H.P. 9, 3, 1 ; 9, 4, 4 ;</i> POL. <i>6, 33, 6 ; au pass</i>. TH. <i>C.P. 4, 8, 2 ;</i><br><b>      2</b> niveler au ras du sol, <i>d’où</i> raser, détruire de fond en comble, SPT. <i>Ps. 136, 9 ;</i> NT. <i>Luc. 19, 44</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut</i>. ἐδαφιῶ, SYN. <i>Ep. 57. Ao. 3 pl</i>. ἠδάφισαν, POL. <i>l. c. ; ou</i> ἐδάφισαν, HSCH. ; <i>sbj. 3 pl</i>. ἐδαφίσωσι, TH. <i>H.P. 9, 3, 1. Pass. prés. part. fém</i>. ἐδαφιζομένης, TH. <i>C.P. 4, 8, 2 ; pf. inf</i>. ἠδαφίσθαι, TH. <i>H.P. 9, 4, 4</i>.<br><span><b>Étym</b>. ἔδαφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εδαφιζω - ἐδαφίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1475":"<h1>edaphos</h1>\n<p>Strong n° 1475 <i>Prononciation [ed'-af-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le fond, le bas, la terre, le sol</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔδαφος, εος-ους (τὸ)</b> <span>[ᾰ]</span><br><b>   I</b> fondement (du sol, d’une maison, <i>etc</i>.) : καθαιρεῖν εἰς τὸ ἔδαφος, THC. <i>3, 68 ;</i> εἰς ἔδαφος καταϐάλλειν, PLUT. <i>M. 5</i> f, détruire jusqu’aux fondements ; ἐχθρὸς τῷ τῆς πόλεως ἐδάφει, DÉM. <i>99, 19 ; 134, 14,</i> ennemi du fondement même de l’État, <i>càd</i>. ennemi mortel ; <i>p. suite :</i><br><b>      1</b> le sol lui-même, <i>au point de vue de la qualité,</i> TH. <i>C.P. 4, 11, 8 ;</i><br><b>      2</b> le sol, <i>considéré comme propriété (cf. franç</i>. fonds de terre, biens-fonds) IS. <i>88, 22 ;</i> DÉM. <i>803 fin ;</i><br><b>   II</b> <i>p. suite,</i> fond solide (de la mer, ARSTT. <i>H.A. 4, 8, 18 ;</i> d’un fleuve, XÉN. <i>Cyr. 7, 5, 18</i>) ; fond de cale d’un navire, OD. <i>5, 249 ;</i> DÉM. <i>883, 22 ;</i> fond d’un vase à boire, PHÉRÉCR. (ATH. <i>481</i> b) ;<br><b>   III</b> <i>p. ext. sans idée de profondeur,</i> ce qui sert de fondement <i>ou</i> de support, <i>d’où :</i><br><b>      1</b> pavé (d’une maison) HDT. <i>8, 137 ;</i><br><b>      2</b> plate-forme, plancher, horizon de scène (d’un théâtre) HÉRON <i>Aut. 244, 265, etc. ;</i><br><b>      3</b> <i>fig. en parl. d’un ouvrage,</i> texte fondamental, texte original, GAL. <i>12, 91</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εδαφος - ἔδαφος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1476":"<h1>hedraios</h1>\n<p>Strong n° 1476 <i>Prononciation [hed-rah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>assis, sédentaire</li>\n<li>ferme, inébranlable, immuable, constant, solide</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑδραῖος, α</b> <i>ou</i> <b>ος, ον :<br>      1</b> qui sert de siège, <i>en parl. du dos d’un cheval, d’un animal,</i> EUR. <i>Rhes. 783 ;</i><br><b>      2</b> sédentaire, <i>en parl. de pers</i>. XÉN. <i>Lac. 1, 3 ;</i> ARSTT. <i>H.A. 7, 9 ; en parl. de choses (genre de vie, travail, fonctions, etc</i>.) HPC. <i>Art. 820 ;</i> PLAT. <i>Rsp. 407</i> b ; ANTH. <i>11, 42 ;</i><br><b>      3</b> ferme dans son assiette, solide, PLAT. <i>Tim. 59</i> d ; EUR. <i>Andr. 266 ;</i> PLUT. <i>M. 288</i> d, <i>954</i> d ; <i>en parl. d’une coupe,</i> ATH. <i>496</i> a ; <i>fig</i>. ἑδρ. ὕπνος, HPC. <i>1180</i> e, sommeil calme.<br><span>•<i> Sup</i>. ἑδραιότατος, T. LOCR. <i>98</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, PLAT. <i>Tim. 59</i> d, <i>Rsp. 407</i> b.<br><span><b>Étym</b>. ἕδρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εδραιος - ἑδραῖος</font>\n<br><br>vient d'un dérivé de hezomai (se poser)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1477":"<h1>hedraioma</h1>\n<p>Strong n° 1477 <i>Prononciation [hed-rah'-yo-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rester, support, appui, fondement, soutien, soutènement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑδραίωμα, ατος (τὸ)</b> base solide, soutien, NT. <i>1Tim. 3, 16</i>.<br><span><b>Étym</b>. ἑδραιόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εδραιωμα - ἑδραίωμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1478":"<h1>Ezekias</h1>\n<p>Strong n° 1478 <i>Prononciation [ed-zek-ee'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Ezéchias (Angl. Hezekiah) = « la puissance de l'Eternel »\n<ol><li>le douzième roi de Juda</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἐζεκίας (ὁ)</b> <i>c</i>. Ἐζεκείας JOS. <i>A.J. 9, 12, 3, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εζεκιας</font> &lt; יחזקיהו - <font face=\"Georgia\">Ἑζεκίας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G1479":"<h1>ethelothreskeia</h1>\n<p>Strong n° 1479 <i>Prononciation [eth-el-oth-race-ki'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>culte volontaire, arbitraire, dévotion\n<ol type=\"a\">\n<li>culte que quelqu'un prescrit et réalise de lui-même, contraire aux contenus et à la nature de la foi qui doit être mise en Christ</li>\n<li>se dit du zèle excessif et des pratiques des ascètes</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐθελο·θρησκεία, ας (ἡ)</b> religion qu’on se crée à soi-même, superstition, NT. <i>Col. 2, 23</i>.<br><span><b>Étym</b>. ἐθέλω, θρησκεία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εθελοθρησκεια - ἐθελοθρησκία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT).\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1480":"<h1>ethizo</h1>\n<p>Strong n° 1480 <i>Prononciation [eth-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>usage, coutume, ce qu'ordonne la loi, usage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐθίζω</b> <span>(<i>f</i>. ἐθίσω, <i>att</i>. ἐθιῶ ; <i>ao</i>. εἴθισα, <i>pf</i>. εἴθικα ; <i>pass. f</i>. ἐθισθήσομαι, <i>ao</i>. εἰθίσθην, <i>pf</i>. εἴθισμαι, <i>pl.q.pf</i>. εἰθίσμην)</span><br><b>      1 <i>tr.</i></b> habituer, accoutumer : τινά τι, XÉN. <i>Mem. 2, 1, 2 ; Eq. 7, 7 ; 9, 9 ;</i> τινὰ πρός τι, LUC. <i>Anach. 20,</i> qqn à qqe ch. ; τὶ ἔθος τινὰ ἐθ. PLAT. <i>Men. 70</i> b, donner à qqn l’habitude de qqe ch. ; τοὺς μετ' αὐτοῦ δὲ ταὐτὰ εἴθικεν, XÉN. <i>Hell. 6, 1, 15,</i> à ceux qui étaient avec lui il donna les mêmes habitudes ; ἐθ. τινά, <i>avec l’inf</i>. PLAT. <i>Gorg. 510</i> d ; ISOCR. <i>276</i> e, <i>etc</i>. habituer qqn à faire qqe ch. ; <i>au pass</i>. ἐθίζεσθαι, être accoutumé à : τι, XÉN. <i>Eq. 8, 6 ;</i> PLAT. <i>Leg. 681</i> b ; τινι, TH. <i>C.P. 5, 9, 11,</i> à qqe ch. ; σὺν τοιούτῳ ἔθει ἐθισθέντες, XÉN. <i>Cyr. 1, 6, 19,</i> ayant pris une telle habitude ; ἐθίζεσθαι <i>avec l’inf</i>. XÉN. <i>Cyr. 2, 3, 22 ; 3, 2, 25,</i> être habitué à, <i>etc. ; abs</i>. PLAT. <i>Leg. 653</i> b ; <i>pf</i>. εἴθισμαι, avoir été habitué, <i>d’où</i> avoir l’habitude de, être accoutumé à, <i>avec l’inf</i>. THC. <i>1, 77 ;</i> XÉN. <i>Cyr. 2, 1, 16 ; part</i>. εἰθισμένος, η, ον, <i>en parl. de choses,</i> dont on a l’habitude, habituel, XÉN. <i>Lac. 6, 4 ; Hier. 9, 7 ;</i> παλαιὰ καὶ εἰθισμένα καὶ ἔννομα, XÉN. <i>Cyr. 8, 7, 10,</i> choses anciennes, accoutumées et régulières ; <i>en parl. de pers</i>. qui a pris l’habitude de, <i>d’où</i> accoutumé à, <i>inf</i>. AND. <i>20, 16 ;</i><br><b>      2 <i>intr.</i></b> s’habituer à, <i>avec l’inf</i>. PLUT. <i>Lyc. 12 (vulg. ; corr</i>. εἰθίζοντο <i>Bkk. Sint</i>.).<br><span><b><span class=\"arrow\"></span></b> <i>Prés. poét</i>. εἰθίζω, PYTHAG. <i>9, 35. Fut</i>. ἐθιῶ, XÉN. <i>Cyr. 3, 3, 53. Ao</i>. εἴθισα, DÉM. <i>477, 21. Pf</i>. εἴθικα, XÉN. <i>Hell. 6, 1, 15 ;</i> PLAT. <i>Men. 70</i> b. <i>Pass. f. réc</i>. ἐθισθήσομαι, DH. <i>4, 11 ;</i> ARSTD. <i>t. 1, 518. Ao</i>. εἰθίσθην, AR. <i>Vesp. 512 ;</i> PLAT. <i>Leg. 681 ; sbj</i>. ἐθισθῶ, HPC. <i>1, 305 Erm. Pf</i>. εἴθισμαι, <i>d’où part</i>. εἰθισμένον, CIA. <i>2, 624, 15 (200/150 av. J.C.) (v. ci-dessus) ; 3 pl. ion</i>. εἰθίδαται, HPC. <i>1, 307. Pl.q.pf. 3 sg</i>. εἴθιστο, HPC. <i>2, 294 ;</i> XÉN. <i>Ages. 11, 2</i>.<br><span><b>Étym</b>. ἔθος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εθιζω - ἐθίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1481":"<h1>ethnarches</h1>\n<p>Strong n° 1481 <i>Prononciation [eth-nar'-khace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui gouverne le peuple, mais sans l'autorité ni le nom de roi, ethnarque</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐθν·άρχης, ου (ὁ) :<br>      1</b> gouverneur <i>ou</i> chef d’un peuple, LUC. <i>Macr. 17 ;</i><br><b>      2</b> gouverneur d’une province, ethnarque, SPT. <i>1Macc. 14, 47 ; 15, 1 et 2 ;</i> NT. <i>2Cor. 11, 32 ;</i> JOS. <i>A.J. 13, 6, 6, etc</i>.<br><span><b>Étym</b>. ἔθνος, ἄρχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εθναρχης - ἐθνάρχης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1482":"<h1>ethnikos</h1>\n<p>Strong n° 1482 <i>Prononciation [eth-nee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>adapté au génie ou aux coutumes d'un peuple, ce qui est national</li>\n<li>manières ou langage des étrangers, ce qui est étranger</li>\n<li>dans le N.T. il s'agit de la nature des païens, par rapport au culte du vrai Dieu, le paganisme\n<ol type=\"a\">\n<li>le païen, le Gentil</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐθνικός, ή, όν :<br>      1</b> national, POL. <i>4, 21, 2 ; 30, 10, 6 ;</i> DS. <i>18, 13, etc. ;</i><br><b>      2</b> Gentil (<i>cf. lat</i>. gentilis) <i>par rapport aux Hébreux,</i> NT. <i>Matth. 5, 47, etc. ;</i><br><b>      3</b> <i>t. de gr</i>. ethnique, qui indique la nation <i>ou</i> le lieu d’origine, STR. <i>2, 3, 1 Kram. ;</i> D. THR. <i>636, 11 ;</i> DYSC. <i>Synt. 19, 24</i>.<br><span><b>Étym</b>. ἔθνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εθνικος - ἐθνικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (3)</li>\n</ul>\n</td></tr>\n</table>","G1483":"<h1>ethnikos</h1>\n<p>Strong n° 1483 <i>Prononciation [eth-nee-koce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>comme les païens, comme les Gentils</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐθνικῶς</b>, <i>adv. :</i><br><b>      1</b> selon l’usage <i>ou</i> le caractère d’une nation, DYSC. <i>Synt. 190, 5 ;</i> DL. <i>7, 56 ;</i><br><b>      2</b> à la manière des Gentils, NT. <i>Gal. 2, 14 ;</i> CLÉM. <i>2, 261 Migne</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εθνικως - ἐθνικῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G1484":"<h1>ethnos</h1>\n<p>Strong n° 1484 <i>Prononciation [eth'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une multitude (d'hommes ou d'animaux) vivant ensemble\n<ol type=\"a\">\n<li>une compagnie, une troupe, un essaim</li>\n</ol>\n</li>\n<li>une multitude d'individus de même nature\n<ol type=\"a\">\n<li>la race humaine</li>\n</ol>\n</li>\n<li>une race, une nation, un peuple, le mot ayant donné « ethnie »</li>\n<li>dans le N.T., ceux qui n'adorent pas le vrai Dieu, les païens, les Gentils</li>\n<li>Paul utilise le terme pour les Chrétiens gentils (non Juifs)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔθνος, εος-ους (τὸ)</b> <i>propr</i>. toute classe d’êtres d’origine <i>ou</i> de condition commune, <i>d’où :</i><br><b>   I</b> peuple, nation, tribu, <i>en gén. :</i><br><b>      1</b> <i>en parl. de pers</i>. βρότεον ἔθνος, PD. <i>N. 3, 71 ;</i> θνατὸν ἔ. PD. <i>N. 11, 42, etc</i>. la race des mortels ; ἔθνεα νεκρῶν, OD. <i>10, 526,</i> le peuple des morts ; ἔθνος ἀνέρων, PD. <i>O. 1, 36 ;</i> γυναικῶν, PD. <i>P. 4, 252,</i> la race des hommes, des femmes ; ἔθνεα λαῶν, IL. <i>13, 495,</i> les races des peuples ;<br><b>      2</b> <i>en parl. d’animaux :</i> θηρῶν ἔθνη, SOPH. <i>Ant. 345,</i> les races des bêtes sauvages ; ἔθνος μελισσάων, ὀρνίθων, IL. <i>2, 87, 459 ;</i> ἰχθύων, PLAT. <i>Tim. 92</i> c, la race des abeilles, des oiseaux, des poissons ;<br><b>      3</b> <i>p. anal</i>. classe, corporation, <i>selon la profession : en parl. de la caste des Brahmanes indous,</i> DS. <i>17, 102 ;</i> δημιουργικὸν ἔθνος, PLAT. <i>Gorg. 455</i> b, la race des artisans ; ῥαψῳδῶν ἔθνος, XÉN. <i>Conv. 3, 6,</i> la race des rhapsodes (<i>cf. lat</i>. genus vatum) ; ἢ κλέπτας ἢ ἄλλο τι ἔθνος, PLAT. <i>Rsp. 351</i> c, les voleurs ou qqe autre race semblable ; <i>selon le rang ou la fortune,</i> PLAT. <i>Rsp. 420</i> b, <i>etc. ;</i><br><b>      4</b> sexe : τὸ θῆλυ ἔθνος, XÉN. <i>Œc. 7, 26,</i> le sexe féminin ;<br><b>   II</b> <i>abs</i>. nation, HDT. <i>1, 101 ;</i> THC. <i>1, 3 ;</i> XÉN. <i>Cyr. 1, 1, 4 ;</i> κατὰ ἔθνη, THC. <i>2, 68 ;</i> XÉN. <i>An. 1, 8, 9, etc</i>. par nations ; <i>p. opp. à</i> γένος (<i>subdiv. de</i> ἔθνος) HDT. <i>1, 56 ; postér., à Rome,</i> τὰ ἔθνη :<br><b>      1</b> peuples des provinces, DC. <i>36, 24 ; 37, 50 ;</i><br><b>      2</b> les Gentils (<i>cf</i>. ἐθνικός) <i>par rapport aux Hébreux,</i> SPT. <i>1Esdr. 7, 13 ; 8, 67 ; Ps. 2, 1, etc. ;</i> NT. <i>Matth. 10, 5 ; Rom. 11, 13</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εθνος - ἔθνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n163 fois dans 151 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (15)</li>\n<li>Marc (6)</li>\n<li>Luc (13)</li>\n<li>Jean (5)</li>\n<li>Actes (43)</li>\n<li>Romains (29)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (10)</li>\n<li>Ephésiens (5)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (2)</li>\n<li>1 Pierre (3)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (23)</li>\n</ul>\n</td></tr>\n</table>","G1485":"<h1>ethos</h1>\n<p>Strong n° 1485 <i>Prononciation [eth'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>coutume</li>\n<li>usage prescrit par la loi, institution, prescription, rite, manière</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔθος, εος-ους (τὸ)</b> coutume, usage, ESCHL. <i>Ag. 728 ;</i> SOPH. <i>Ph. 894 ;</i> XÉN. <i>Cyr. 1, 6, 33, etc. ;</i> ἔθος (<i>s.-e</i>. ἐστίν) <i>avec l’inf</i>. BATR. <i>34,</i> c’est la coutume de, <i>etc. ;</i> ἔθος ἐστί τινι, ATH. <i>12</i> a, c’est l’habitude de qqn de, <i>etc. ;</i> ἐν ἔθει τῇ πόλει ἦν, THC. <i>2, 64,</i> c’était la coutume de la cité ; ἔθος ἔχειν <i>avec l’inf</i>. PLUT. <i>Them. 4,</i> avoir l’habitude ; ἐν ἔθει γενέσθαι τινός, PLUT. <i>Demetr. c. Ant. 4 ;</i> HDN <i>5, 5,</i> avoir pris l’habitude de qqe ch. ; ἔθει, d’habitude, habituellement, <i>p. opp. à</i> φύσει, ARSTT. <i>Nic. 10, 9, 6 ;</i> κατὰ τὸ ἔθος, PLUT. <i>Cic. 4 et 32 ;</i> ἐξ ἔθους, PLAT. <i>Phæd. 82</i> b ; PLUT. <i>Alex. 57 ;</i> δι' ἔθος, ARSTT. <i>Nic. 7, 14, 4,</i> d’après la coutume.<br><span><b>Étym</b>. <i>p.-ê. p</i>. ϝέθος, <i>de la R. indo-europ</i>. *sued<sup>h</sup>-, habitude, caractère ; <i>cf. lat</i>. sodālis, <i>sscr</i>. svadhā́-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εθος - ἔθος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (7)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1486":"<h1>etho</h1>\n<p>Strong n° 1486 <i>Prononciation [eth'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir coutume de</li>\n<li>ce qui est coutumier</li>\n<li>usage, coutume</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔθω</b> <span>(<i>seul. part. prés</i>. ἔθων, <i>pf.2</i> εἴωθα, <i>pl.q.pf</i>. εἰώθειν)</span> avoir coutume : κακὰ ἔρρεζε ἔθων, IL. <i>9, 540,</i> il faisait le mal selon son habitude ; <i>cf</i>. IL. <i>16, 260 ; pf</i>. εἴωθα, j’ai l’habitude de, <i>avec l’inf</i>. IL. <i>5, 766 ;</i> HDT. <i>3, 36 ;</i> THC. <i>1, 97, etc. ; avec le verbe s.-e</i>. THC. <i>1, 132 et 139 ; impers</i>. ὥσπερ εἰώθει (<i>s.-e</i>. γενέσθαι) PLUT. <i>Syll. 9,</i> comme cela avait coutume d’avoir lieu, selon la coutume ; <i>partic</i>. εἰωθώς, -υῖα, -ός, accoutumé, habituel, <i>rar. en parl. de pers</i>. IL. <i>5, 231 ; d’ord. en parl. de choses,</i> THC. <i>1, 67 ; 3, 82 et 84 ;</i> PLAT. <i>Pol. 337</i> a, <i>Ap. 40</i> a ; ἐν τῷ εἰωθότι τρόπῳ, PLAT. <i>Ap. 27</i> b, de la façon accoutumée ; κατὰ τὸ εἰωθός, THC. <i>4, 67,</i> selon la coutume ; παρὰ τὸ εἰωθός, THC. <i>4, 17 et 55,</i> contre l’usage.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. ion</i>. ἔωθα, IL. <i>8, 408 ;</i> HDT. <i>1, 133, etc. ; part</i>. ἐωθώς, HDT. <i>3, 27, 31 ; pl.q.pf. ion</i>. ἐώθεα, HDT. <i>4, 127 ; etc</i>.<br><span><b>Étym</b>. <i>incert. ; cf. p.-ê</i>. ἔθος, <i>mais probabl. l’interprétation de</i> ἔθων <i>c. part. prés. du pf</i>. εἴωθα <i>est à rejeter</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εθω - ἔθω</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1487":"<h1>ei</h1>\n<p>Strong n° 1487 <i>Prononciation [i]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>si, soit que</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἰ</b>, <i>épq. et dor</i>. <b>αἰ</b>, <i>conj</i>. si, <i>usitée dans les prop. conditionnelles, dans les prop. d’interr. indirecte, et pour marquer une simple éventualité :</i><br><b>A Propositions conditionnelles.<br>   I</b> <i>avec l’indicatif d’un temps principal :</i><br><b>      1</b> <i>lorsque la supposition indiquée dans la prop. conditionnelle est considérée comme possible et réalisable ; dans ce cas, le verbe de la prop. conditionnelle ou antécédente</i> (πρότασις) <i>et celui de la prop. conséquente</i> (ἀπόδοσις) <i>se mettent au présent :</i> εἰ δοκεῖ, πλέωμεν, SOPH. <i>Ph. 526,</i> si tu en es d’avis, embarquons-nous et partons ; εἰ δ' οὕτω τοῦτ' ἔστιν, ἐμοὶ μέλλει φίλον εἶναι, IL. <i>1, 564,</i> s’il en est comme tu le dis, c’est qu’apparemment cela m’est agréable ;<br><b>      2</b> <i>lorsqu’on fait une supposition conforme ou non à la réalité, pour en déduire une conclusion logique ; dans ce cas, la prop. conditionnelle ou antécédente se construit avec l’indicatif, et, si elle est négative, avec</i> μή, <i>et la prop. conséquente également à l’indicatif, et, si elle est négative, avec</i> οὐ : εἰ θεοί τι δρῶσιν αἰσχρόν, οὐκ εἰσὶ θεοί, EUR. <i>fr. 294, 7,</i> si les dieux font qqe chose de honteux, ils ne sont pas dieux ; εἰ μὲν θεοῦ ἦν, οὐκ ἦν αἰσχροκερδής· εἰ δ' αἰσχροκερδής, οὐκ ἦν θεοῦ, PLAT. <i>Rsp. 408</i> c, si (Asklèpios) était fils d’un dieu, il n’était pas cupide ; s’il était cupide, il n’était pas fils d’un dieu. <i>L’indicatif de la prop. conséquente peut être remplacé par l’opt. avec</i> ἄν, <i>si l’on veut exprimer la pensée sous une forme moins affirmative :</i> εἰ οὗτοι ὀρθῶς ἀπέστησαν, ὑμεῖς ἂν οὐ χρεὼν ἄρχοιτε, THC. <i>3, 40,</i> s’ils ont eu le droit de se révolter, c’est qu’alors vous commanderiez sans droit ; πολλὴ ἄν τις εὐδαιμονία εἴη περὶ τοὺς νέους, εἰ εἷς μὲν μόνος αὐτοὺς διαφθείρει, οἱ δ' ἄλλοι ὠφελοῦσιν, PLAT. <i>Ap. 25</i> b, ce serait un grand bonheur pour les jeunes gens, s’il était vrai qu’un seul homme les corrompt, tandis que tous les autres leur sont utiles ;<br><b>   II</b> <i>avec l’indicatif d’un temps secondaire, lorsque la condition marquée dans la prop. commençant par</i> εἰ <i>n’a pas été remplie ; dans ce cas, on emploie dans les deux prop. (antécédente et conséquente) l’indic. d’un temps secondaire, sans</i> ἄν <i>dans la prop. antécédente, avec</i> ἄν <i>dans la prop. conséquente ; en outre, avec</i> μή <i>dans la prop. antécédente, si cette prop. est négative. Le temps de l’indicatif employé est :</i><br><b>      1</b> <i>l’imparfait, si l’action indiquée dans la prop. conditionnelle, bien que se rapportant au présent, suppose une idée de durée antérieure :</i> ταῦτα οὐκ ἂν ἐδύναντο ποιεῖν, εἰ μὴ διαίτῃ μετρίᾳ ἐχρῶντο, XÉN. <i>Cyr. 1, 2, 16,</i> ils ne pourraient faire cela, s’ils n’avaient pas un régime de vie sobre ; <i>ou si l’action se rapporte au passé avec une idée de durée :</i> οὐκ ἂν νήσων ἐκράτει, εἰ μή τι καὶ ναυτικὸν εἶχεν, THC. <i>1, 9</i> (Agamemnon) n’aurait pas commandé aux îles, s’il n’avait pas eu en même temps une certaine force navale ;<br><b>      2</b> <i>à l’aoriste, si l’action se rapporte au passé sans idée de durée :</i> εἰ μὴ ὑμεῖς ἤλθετε, ἐπορευόμεθα ἂν ἐπὶ βασιλέα, XÉN. <i>An. 2, 1, 4,</i> si vous n’étiez pas venus, nous aurions marché contre le grand roi ;<br><b>      3</b> <i>au plus-que-parfait, si l’action est considérée comme achevée et que l’effet dure encore :</i> εἰ τριάκοντα μόναι μετέπεσον τῶν ψήφων, ἀπεπεφεύγη ἄν, PLAT. <i>Ap. 36</i> a, s’il y avait eu seulement trente suffrages de plus déposés (dans l’urne) en ma faveur, j’aurais été acquitté, <i>càd</i>. je serais acquitté à l’heure qu’il est ;<br><b>   III</b> <i>avec l’indicatif futur, lorsque l’action exprimée par la prop. conséquente est subordonnée à un événement futur incertain, indiqué dans la prop. conditionnelle ; dans ce cas, la prop. conditionnelle peut se construire avac le subjonctif accompagné de</i> ἄν, <i>la conj</i>. εἰ <i>se fondant alors avec</i> ἄν <i>en</i> ἐάν <i>(v. ce mot), mais souvent aussi avec l’indicatif futur, et, si cette proposition est négative, avec</i> μή ; <i>la prop. conséquente se construit toujours avec l’indicatif futur :</i> εἰ τιμωρήσεις Πατρόκλῳ τῷ ἑταίρῳ τὸν φόνον καὶ Ἕκτορα ἀποκτενεῖς, αὐτὸς ἀποθανεῖ, PLAT. <i>Ap. 28</i> c, si tu venges la mort de ton compagnon Patrocle, et que tu fasses périr Hector, tu mourras toi-même ; εἰ μὴ βοηθήσετε, οὐ περιέσται τἀκεῖ, THC. <i>6, 91,</i> si vous n’envoyez pas de secours, la situation là-bas sera intenable ; εἰ μὴ καθέξεις γλῶσσαν, ἔσται σοι κακά, EUR. <i>fr. 5,</i> si tu ne contiens pas ta langue, il t’arrivera malheur. <i>En poésie, on trouve qqf. le sbj. prés. (avec κε pour ἄν) au lieu de l’indic. fut. dans la prop. conditionnelle et le sbj. ao. (avec κε pour ἄν) dans la prop. conséquente :</i> εἰ δέ κε μὴ δώῃσιν, ἐγὼ δέ κεν αὐτὸς ἕλωμαι, IL. <i>1, 324,</i> si (Achille) ne veut pas donner (Briséis), eh bien ! j’irai moi-même la prendre de force ;<br><b>   IV</b> <i>avec le subjonctif accompagné de</i> ἄν (εἰ <i>se fondant avec</i> ἄν <i>en</i> ἐάν <i>ou</i> ἤν) <i>lorsque la condition exprimée dans la prop. antécédente se trouve remplie, et que la prop. conséquente marque une action qui, dans ce cas, s’accomplit toujours ou se répète chaque fois que se reproduit la réalisation de la condition exprimée (sur ce cas, voy</i>. ἐάν). <i>En poésie, κεν étant substitué à ἄν, εἰ persiste :</i> εἰ δέ κεν ὣς ἔρξῃς καί τοι πείθωνται Ἀχαιοί, γνώσῃ, <i>etc</i>. IL. <i>2, 364,</i> si tu agissais ainsi et que les Grecs t’obéissent, tu apprendrais, <i>etc. Si la condition se rapporte au passé, et que, dès lors, le verbe de la prop. conséquente soit à un temps secondaire, le subjonctif avec ἄν de la prop. conditionnelle est remplacé par l’optatif sans</i> ἄν : ποτὸν δὲ πᾶν ἡδὺ ἦν τῷ Σωκράτει διὰ τὸ μὴ πίνειν, εἰ μὴ διψῴη, XÉN. <i>Mem. 1, 3, 5,</i> toute boisson était agréable à Socrate, parce qu’il ne buvait que s’il avait soif ; — <i>au lieu de l’opt. on trouve l’impf. sans</i> ἄν : ἐμίσει οὐκ εἴ τις κακῶς πάσχων ἠμύνετο, ἀλλ' εἴ τις εὐεργετούμενος ἀχάριστος φαίνοιτο, XÉN. <i>Ages. 11, 3,</i> Agésilas haïssait non celui qui, maltraité, se vengeait, mais celui qui, recevant un bienfait, se montrait ingrat ; <i>cf</i>. XÉN. <i>An. 5, 1, 16 ; 5, 5, 14 ;</i><br><b>   V</b> <i>avec l’optatif sans ἄν dans la prop. conditionnelle auquel répond l’optatif avec ἄν dans la prop. conséquente :</i><br><b>      1</b> <i>lorsque la condition marquée dans la prop. conditionnelle est présentée comme une opinion ou une supposition de la personne qui parle :</i> εἰ μὲν νῦν ἐπὶ ἄλλῳ ἀεθλεύοιμεν, ἦ τ' ἂν ἐγὼ τὰ πρῶτα φεροίμην, IL. <i>23, 274,</i> si en ce moment nous luttions en l’honneur de quelque autre (que Patrocle), certes je remporterais le premier prix ; οὐδὲ γὰρ ἄν με ἐπαινοίη, εἰ ἐξελαύνοιμι τοὺς εὐεργέτας, XÉN. <i>An. 7, 7, 11,</i> car il ne me ferait pas compliment, si je renvoyais mes bienfaiteurs ; εἰ δ' ἀναγκαῖον εἴη ἢ ἀδικεῖν ἢ ἀδικεῖσθαι, ἑλοίμην ἂν μᾶλλον ἀδικεῖσθαι, PLAT. <i>Gorg. 469</i> c, s’il me fallait absolument ou commettre ou subir une injustice, j’aimerais mieux la subir ;<br><b>      2</b> <i>lorsque la prop. conditionnelle marque une action qui se répète ou un fait habituel ; dans ce cas, les deux prop. se construisent sans ἄν, et le verbe de la prop. conséquente se met à un temps passé de l’indic. (impf. ou pl.q.pf</i>.) : εἴ του φίλων βλέψειεν οἰκετῶν δέμας, ἔκλαιεν ἡ δύστηνος εἰσορωμένη, SOPH. <i>Tr. 908,</i> apercevait-elle quelqu’un des serviteurs qui lui étaient chers, l’infortunée pleurait en le regardant ; εἴ τις ἀντείποι, εὐθὺς ἐτεθνήκει, THC. <i>8, 66,</i> tout homme qui contredisait était un homme mort. <i>Au lieu de l’optatif dans la prop. conditionnelle, on trouve qqf. l’impf. de l’indic</i>. εἴ τίς τι ἐπηρώτα, ἀπεκρίνοντο, THC. <i>7, 10,</i> quelqu’un demandait-il quelque chose, ils répondaient ;<br><b>      3</b> <i>lorsque les deux prop. (antécédente et conséquente) dépendent d’une prop. principale dont le verbe est à l’impf</i>. ἐλογίζοντο ὡς, εἰ μὴ μαχοῖντο, ἀποστήσοιντο αἱ πόλεις, XÉN. <i>Hell. 6, 4, 6,</i> ils calculaient que, s’ils ne combattaient pas, les villes feraient défection ; <i>dans ce cas, les deux prop. se construisent sans</i> ἄν, <i>et, si la prop. antécédente est négative, la négation s’exprime par</i> μή : ἔλεγεν ὅτι, εἰ βλαϐερὰ πεπραχὼς εἴη, δίκαιος εἴη ζημιοῦσθαι, XÉN. <i>Hell. 5, 2, 32,</i> il disait que, s’il avait fait tort (à qqn), il méritait d’être puni. <i>Par attract., au lieu de l’opt., on trouve en prose ion</i>. εἰ <i>avec l’inf., sans</i> ἄν : εἰ γὰρ δὴ δεῖν πάντως περιθεῖναι ἄλλῳ τέῳ τὴν βασιληΐην, (ἔφη) δικαιότερον εἶναι, HDT. <i>1, 129 (pour</i> εἰ δεῖ <i>ou</i> εἰ δέοι), car, s’il fallait absolument attribuer la royauté à quelque autre, il serait plus juste, disait-il (<i>litt</i>. il disait que, s’il fallait, <i>etc.,</i> il serait plus juste) ; <i>cf</i>. HDT. <i>2, 64, 172 ; 3, 105, 108 ;</i><br><b>   VI Remarque</b>. <i>La prop. conditionnelle commençant par εἰ est qqf. exprimée seule sans la prop. conséquente qui l’accompagne d’ordinaire :</i><br><b>      1</b> <i>lorsque la prop. conditionnelle dépend d’un verbe impliquant l’idée de la prop. conséquente :</i> ᾤκτειρον εἰ ἁλώσοιντο, XÉN. <i>An. 1, 4, 7,</i> ils s’apitoyaient sur eux-mêmes pour le cas où ils seraient pris, <i>càd</i>. sur le sort (qui les attendait) s’ils venaient à être pris ;<br><b>      2</b> <i>lorsque la prop. conditionnelle suppose par elle-même une prop. conséquente nécessaire au développement du sens :</i> εἴ περ γάρ κ' ἐθέλῃσιν Ὀλύμπιος στυφελίξαι, IL. <i>1, 580,</i> car si le dieu de l’Olympe voulait (nous) précipiter (de nos trônes) (<i>s.-e</i>. il le pourrait bien) ; <i>particul. lorsque la prop. conditionnelle est suivie d’une autre prop. conditionnelle impliquant la négation de l’idée contenue dans la première ; dans ce cas, la première prop. suppose une conséquente comme</i> « εὖ <i>ou</i> καλῶς ἔχει, c’est bien » : εἰ μὲν δώσουσι γέρας· εἰ δέ κε μὴ δώωσιν, ἐγὼ δέ κεν αὐτὸς ἕλωμαι, IL. <i>1, 135,</i> s’ils me donnent la récompense, (rien de mieux) ; sinon, je saurai la prendre moi-même ; εἰ μὲν σύ τι ἔχεις πρὸς ἡμᾶς λέγειν· εἰ δὲ μή, ἡμεῖς πρὸς σὲ ἔχομεν, XÉN. <i>An. 7, 7, 15,</i> si tu as quelque chose à nous dire, (c’est bien) ; sinon, nous avons, nous, à te parler ;<br><b>      3</b> <i>dans les prop. optatives commençant par</i> εἰ γάρ (<i>épq</i>. αἲ γάρ) <i>ou qqf</i>. εἰ <i>seul, et qui supposent une prop. antérieure telle que</i> « ce serait chose souhaitable, <i>etc</i>. » ; αἲ γὰρ ἐμοὶ τοσσήνδε θεοὶ δύναμιν παραθεῖεν, OD. <i>3, 205,</i> oh ! si les dieux (m’)avaient doté d’une telle puissance ! εἰ γὰρ γενοίμην ἀντὶ σοῦ νεκρός, EUR. <i>Hipp. 1410,</i> ah ! puissé-je mourir à ta place ! <i>on rencontre qqf. l’opt. même avec</i> εἰ <i>seul :</i> ἀλλ' εἴ τις καλέσειεν, IL. <i>10, 111,</i> mais si quelqu’un appelait, <i>càd</i>. je voudrais qu’on appelât, <i>etc. ;</i><br><b>   VII</b> <i>À l’emploi de εἰ conditionnel se rattache l’usage de cette conjonction après les verbes ou les loc. qui marquent l’étonnement</i> (θαυμάζω), <i>la satisfaction</i> (ἀγαπῶ), <i>la honte ou la confusion</i> (αἰσχύνομαι, αἰσχρόν ἐστιν), <i>l’indignation ou le mécontentement</i> (ἀγανακτῶ, βαρέως <i>ou</i> χαλεπῶς φέρω, λυπεῖ με), <i>etc. ; en ce sens εἰ exprime avec une sorte d’atténuation le même rapport d’idées que</i> ὅτι (<i>cf. lat</i>. miror si) ; <i>si la prop. conditionnelle est négative, la négation s’exprime par</i> μή : ἐθαύμαζε δ' εἴ τις ἀρετὴν ἐπαγγελλόμενος ἀργύριον πράττοιτο, XÉN. <i>Mem. 1, 2, 7,</i> il s’étonnait qu’on fît sonner bien haut ses prétentions à la vertu et qu’on battît monnaie ; οὐκ ἀγαπᾷ εἰ μὴ δίκην δέδωκεν, ἀλλ' εἰ μὴ καὶ χρυσῷ στεφάνῳ στεφανωθήσεται ἀγανακτεῖ, ESCHN. <i>74, 28,</i> il ne se contente pas de n’avoir pas été puni, il s’indigne encore à la pensée de n’être pas couronné de la couronne d’or ; ἀγανακτῶ εἰ τὰ μὲν χρήματα λυπεῖ τινας ὑμῶν εἰ διαρπασθήσεται, τὴν δ' Ἑλλάδα πᾶσαν οὑτωσὶ Φίλιππος ἐφεξῆς ἁρπάζων οὐ λυπεῖ, DÉM. <i>8, 55 Baiter-Sauppe,</i> je m’indigne qu’il y en ait parmi vous qui s’affligent à la pensée que leurs biens seront pillés, tandis que le spectacle présent de la Grèce entière ainsi pillée par Philippe ne les afflige pas ;<br><b>B Interrogation indirecte</b>, <i>avec l’indicatif, le subjonctif ou l’optatif. :</i><br><b>   I</b> <i>Avec l’indicatif :</i><br><b>      1</b> <i>après les temps principaux, lorsqu’on emploierait le présent, l’imparfait ou le parfait dans l’interr. dir. :</i> σάφα δ' οὐκ οἶδ' εἰ θεός ἐστιν, IL. <i>5, 183,</i> je ne sais pas clairement si c’est un dieu ; <i>de même, lorsque la prop. commençant par εἰ équivaut au franç</i>. si… ne pas (<i>lat</i>. dubito <i>ou</i> haud scio… an) : οἶδεν οὐδεὶς τὸν θάνατον οὐδ' εἰ τυγχάνει πάντων μέγιστον ὂν τῶν ἀγαθῶν, PLAT. <i>Ap. 29</i> a, au sujet de la mort, personne ne sait ce qu’elle est, ni si elle n’est pas le plus grand de tous les biens ; <i>en parl. d’une action passée :</i> σκέψασθε εἰ ἄρα τοῦτο καὶ μωρότατον πεποιήκασιν οἱ βάρϐαροι, XÉN. <i>An. 3, 2, 22,</i> examinez si vraiment ce n’est pas la plus grande folie que les barbares aient commise ;<br><b>      2</b> <i>après un temps secondaire, lorsque l’interrogation se rapporte à un événement futur :</i> ψῆφον ἐϐούλοντο ἐπαγαγεῖν, εἰ χρὴ πολεμεῖν, THC. <i>1, 119,</i> ils voulaient faire voter sur la question de savoir s’il fallait faire la guerre ;<br><b>   II</b> <i>avec le subjonctif :</i><br><b>      1</b> <i>après les temps principaux, lorsqu’on emploierait le futur dans une interr. dir</i>. τὰ δ' ἐκπώματα οὐκ οἶδ' εἰ Χρυσάντᾳ τούτῳ δῶ, XÉN. <i>Cyr. 8, 4, 16,</i> quant aux coupes, je ne sais si je ne dois pas les donner à Khrysantas que voilà ;<br><b>      2</b> <i>après un temps secondaire, si la question se rapporte à un événement futur :</i> ἐϐουλεύοντο εἴτε κατακαύσωσιν… εἴτε τι ἄλλο χρήσωνται, THC. <i>2, 4, 6</i> (les Platéens) délibéraient s’ils devaient faire périr (les Thébains) par le feu en incendiant l’édifice, ou les traiter de qqe autre façon ;<br><b>   III</b> <i>avec l’optatif après un temps secondaire, avec ou sans</i> ἄν, <i>selon qu’on emploierait ou non cette particule dans l’interr. dir. :</i> ἤρετο εἴ τις ἐμοῦ εἴη σοφώτερος, PLAT. <i>Ap. 21</i> a, il demandait s’il y avait quelqu’un plus sage que moi (<i>interr. dir</i>. ἔστι τίς σόφ. ;) ; ἠρώτων εἰ δοῖεν ἂν τούτων τὰ πιστά, XÉN. <i>An. 4, 8, 7,</i> ils demandaient s’ils consentiraient à donner des gages de ces promesses (<i>interr. dir</i>. δοίητε ἄν ;) ;<br><b>   IV</b> <i>Lorsque la prop. d’interr. indir. est négative, la négation est représentée, selon le cas, par οὐ ou par μή, comme si l’interr. était directe :</i><br><b>      1</b> <i>par</i> οὐ : ἐνετέλλετο εἰρωτᾶν εἰ οὔ τι ἐπαισχύνεται, HDT. <i>1, 90,</i> il (leur) ordonna de demander (au dieu) s’il n’avait pas quelque honte, <i>etc. (interr. dir</i>. οὐ) ;<br><b>      2</b> <i>par</i> μή : ἐρωτῶ, εἰ τοῦ μὲν δικαίου μὴ ἀξιοῖ πλέον ἔχειν μηδὲ βούλεται ὁ δίκαιος, τοῦ δὲ ἀδίκου, PLAT. <i>Rsp. 349</i> b, je (te) demande si le juste aurait la prétention ou la volonté de l’emporter non sur un autre juste, mais seulement sur celui qui est injuste (<i>interr. dir. μή, à cause de la réponse négative qu’implique la question). Dans les interr. indir. à deux membres</i> (εἰ… ἤ) <i>la prop. négat. admet indifféremment οὐ et</i> μή : σκοπῶμεν εἰ ἡμῖν πρέπει, ἢ οὔ, PLAT. <i>Rsp. 451</i> d, examinons si cela nous sied ou non ; νῦν ἔμαθον ὃ λέγεις· εἰ δὲ ἀληθές, ἢ μή, πειράσομαι μαθεῖν, PLAT. <i>Rsp. 339</i> a, à présent je sais ce que tu dis, mais cela est-il vrai ou non ? c’est ce que je vais tâcher d’apprendre ;<br><b>C Idée d’éventualité incertaine</b>. — <i>La conj</i>. εἰ <i>se rencontre sans idée de condition, ni d’interrogation proprement dite, et simplement pour marquer une éventualité incertaine, par exemple, lorsqu’on peut sous-entendre devant la proposition commençant par</i> εἰ <i>les mots</i> « pour voir », « pour savoir », <i>ou les mots</i> « au cas que », « pour le cas où » : παρέζεο καὶ λαϐὲ γούνων, αἴ κέν πως ἐθέλῃσιν ἐπὶ Τρώεσσιν ἀρῆξαι, IL. <i>1, 407,</i> va t’asseoir près de (Zeus) et embrasse ses genoux, pour voir s’il voudrait par hasard porter secours aux Troyens ; ἔδοξεν οὖν Κλεάρχῳ συγγενέσθαι τῷ Τισσαφέρνει, εἴ πως δύναιτο παῦσαι τὰς ὑποψίας, XÉN. <i>An. 2, 5, 2,</i> Cléarque jugea bon de s’aboucher avec Tissapherne pour tâcher, s’il le pouvait, de faire cesser ces soupçons ; ἄκουσον καὶ ἐμοῦ, ἐάν σοι ταὐτὰ δοκῇ, PLAT. <i>Rsp. 358</i> b, écoute-moi aussi pour voir si tu seras du même avis que moi. <i>Dans cette construction la prop. commençant par εἰ se rapportant toujours à l’avenir, le verbe de cette prop. peut être à l’optatif après un présent historique :</i> ἐκπλαγεὶς ἵεται, εἴ τι δύναιτο βοηθῆσαι, XÉN. <i>Cyr. 7, 3, 15,</i> Cyrus consterné s’avance pour voir s’il pourrait porter quelque secours, <i>ou</i> en cas qu’il puisse porter quelque secours ;<br><b>D</b> εἰ <b>joint à des pronoms ou particules</b>. — εἰ <i>forme avec certains pronoms ou particules diverses locutions :</i><br><b>   I</b> <i>avec</i> μή :<br><b>      1</b> εἰ μή, si… ne pas (<i>lat</i>. nisi), <i>elliptiq. sans verbe après une négation au sens de</i> « sinon » : οὐδὲν ἄλλο σιτέονται εἰ μὴ ἰχθῦς μοῦνον, HDT. <i>1, 200,</i> ils ne mangent d’autre plat que du poisson ; τὸ στράτευμα ὁ σῖτος ἐπέλιπε καὶ πρίασθαι οὐκ ἦν εἰ μὴ ἐν τῇ Λυδίᾳ ἀγορᾷ, XÉN. <i>An. 1, 5, 6,</i> l’armée manqua de vivres, et il n’y avait pas moyen d’en acheter sinon au marché lydien ; <i>avec un gén. abs</i>. κἂν διεφθάρησαν, εἰ μὴ Ἀθηνίωνος κακώσαντος Ἡρώδην καὶ τοὺς Ἰουδαίους, JOS. <i>A.J. 15, 5, 1,</i> et ils auraient péri, si Athénion n’eût malmené Hérode et les Juifs. <i>De même dans les locut</i>. εἰ μὴ ὅσον, excepté seulement, HDT. <i>2, 73 ;</i> εἰ μὴ εἰ (<i>cf. lat</i>. nisi si) <i>m. sign</i>. THC. <i>1, 17 ;</i> PLAT. <i>Gorg. 480</i> b ; εἰ μή τι οὖν, <i>m. sign</i>. PLAT. <i>Men. 86</i> e ; εἰ μὴ διά (<i>v</i>. διά) ; πλὴν εἰ (<i>v</i>. πλήν) ;<br><b>      2</b> εἰ δὲ μή (<i>lat</i>. si minus, sin aliter) sinon, autrement : εἰ βούλεσθε συναπιέναι, ἥκειν ἤδη κελεύει τῆς νυκτός· εἰ δὲ μή, αὔριον πρωῒ ἀπιέναι φησίν, XÉN. <i>An. 2, 2, 1,</i> si vous voulez partir avec (Ariée), il vous prie de venir cette nuit même ; sinon, dit-il, il partira demain de bonne heure ; <i>qqf. après une prop. elle-même négative :</i> μὴ οὕτω λέγε· εἰ δὲ μή, οὐ θαρροῦντά με ἕξεις, XÉN. <i>Cyr. 3, 1, 35,</i> ne parle pas ainsi, autrement (ou sinon) tu vas me décourager ; εἰ δὲ μή <i>s’emploie même par opp. à</i> ἐὰν μέν, <i>au lieu de</i> ἐὰν δὲ μή, DÉM. <i>129, 14 ;</i><br><b>      3</b> εἰ μὴ ἄρα (<i>lat</i>. nisi forte) εἰ μή πέρ γε, à moins toutefois que, <i>formules ironiques, toujours construites avec l’indic. :</i> πῶς ἂν ὁ τοιοῦτος ἀνὴρ διαφθείροι τοὺς νέους ; εἰ μὴ ἄρα ἡ τῆς ἀρετῆς ἐπιμέλεια διαφθορά ἐστιν, XÉN. <i>Mem. 1, 2, 8,</i> comment un tel homme corromprait-il les jeunes gens ? à moins qu’il ne soit vrai de dire que l’étude de la vertu est un moyen de corruption ; οὐδαμῶς εἰ μή πέρ γε, XÉN. <i>Œc. 1, 13,</i> nullement, à moins qu’en vérité, <i>etc. ;</i><br><b>   II</b> <i>avec</i> δέ :<br><b>      1</b> εἰ δέ <i>au sens de</i> εἰ δὲ μή, <i>surt. après une prop. où se trouve le verbe</i> βούλομαι : λέγω πάλιν, εἰ μὲν βούλεσθε, ὡς παίζων· εἰ δ', ὡς σπουδάζων, PLAT. <i>Leg. 688</i> b, je le répète, si vous le voulez, en manière de plaisanterie ; sinon, sérieusement ; εἰ μὲν βούλεται, ἑψέτω· εἰ δ', ὅ τι βούλεται τοῦτο ποιείτω, PLAT. <i>Euthyd. 285</i> c, qu’il (me) fasse bouillir, s’il veut ; s’il ne veut pas, qu’il me fasse subir tout autre traitement qu’il lui plaira ;<br><b>      2</b> <i>souv. dans les locut</i>. εἰ δ' ἄγε (<i>19 fois dans Homère</i>), εἰ δ' ἄγετε (<i>1 fois), simpl</i>. εἰ δέ (<i>2 fois) au sens d’une interj</i>. eh bien ! voyons ! εἰ δ' ἄγ' ἐγὼν αὐτὸς δικάσω, IL. <i>23, 579,</i> eh bien ! voyons, je proposerai pour ma part une décision ; Ἀντίλοχ', εἰ δ' ἄγε δεῦρο, IL. <i>17, 685,</i> eh bien ! voyons, Antilokhos, viens ici ; εἰ δ' ἄγε μήν, πείρησαι, IL. <i>1, 302,</i> eh bien ! voyons, essaie ; <i>cf</i>. IL. <i>1, 524 ; 8, 18 ; 19, 107 ;</i> OD. <i>1, 271 ; 9, 37 ; 21, 217, etc. ; de même,</i> εἰ δ' ἄγετε, IL. <i>22, 381 ;</i> εἰ δέ : εἰ δέ, σὺ μέν μευ ἄκουσον, IL. <i>9, 262,</i> mais voyons, toi, écoute-moi ; εἰ δὲ καὶ αὐτοὶ φευγόντων, IL. <i>9, 46,</i> eh bien ! qu’ils fuient eux aussi ;<br><b>   III</b> <i>avec divers pronoms, conjonctions ou particules :</i><br><b>      1</b> <i>avec</i> τις <i>ou</i> τι : εἴ τις (<i>lat</i>. si quis) s’il en fut jamais : ὄτλον ἄλγιστον ἔσχον, εἴ τις Αἰτωλὶς γυνή, SOPH. <i>Tr. 8</i> (moi qui) avais à redouter, si jamais femme d’Étolie eut à le craindre, le joug (de l’hymen) le plus douloureux ; <i>particul. avec</i> ἄλλος : εἴ τις ἄλλος, εἴ τις καὶ ἄλλος (<i>v</i>. ἄλλος) : ἔκαιον καὶ χιλὸν καὶ εἴ τι ἄλλο χρήσιμον ἦν, XÉN. <i>An. 1, 6, 1,</i> ils brûlaient le fourrage et tout ce qui pouvait être de quelque utilité ;<br><b>      2</b> εἴ ποτε, si jamais (il en fut ainsi) : εἴ ποτέ τοι ἐπὶ νηὸν ἔρεψα, τόδε μοι κρήηνον ἐέλδωρ, IL. <i>1, 39,</i> s’il est vrai que (<i>litt</i>. si jamais) je t’ai construit un temple, exauce mon désir ; <i>dans le disc. indir</i>. IL. <i>2, 97 ;</i> εἴ ποτ' ἔην γε, IL. <i>3, 180 ; 11, 762 ; 24, 426 ;</i> OD. <i>15, 268 ; 19, 315 ; 24, 289 ;</i> XÉN. <i>An. 6, 4, 12, etc. ;</i><br><b>      3</b> εἴ ποθι, si jamais (il en fut ainsi) OD. <i>12, 96 ; 17, 195 ;</i> SOPH. <i>Aj. 886 ;</i><br><b>      4</b> εἴ ποθεν, si de quelque lieu, IL. <i>9, 380 ;</i> OD. <i>1, 115, etc. ;</i> SOPH. <i>Ph. 1204 ;</i><br><b>      5</b> εἴ που, si en qqe façon, IL. <i>6, 330, etc. ;</i> εἴ τί που, OD. <i>4, 193, m. sign. ;</i><br><b>      6</b> εἴ πως, si en qqe manière, si par hasard, OD. <i>4, 388, 800 ;</i> XÉN. <i>An. 2, 3, 11 ;</i><br><b>      7</b> <i>avec</i> γάρ : εἰ γάρ (<i>v. ci-dessus</i> A. VI, 3) ;<br><b>      8</b> avec -θε (<i>v</i>. εἴθε) ;<br><b>      9</b> <i>avec</i> καί : εἰ καί (<i>par fusion avec</i> ἄν, ἐὰν καί), <i>ou</i> καὶ εἰ (<i>par fusion avec</i> ἄν (καὶ ἐάν) même si, quand bien même, alors même que, <i>etc. (cf. lat</i>. etsi, etiamsi) : πάντες ποταμοὶ εἰ καὶ πρόσω τῶν πηγῶν ἄποροί εἰσι, προΐουσι πρὸς τὰς πηγὰς διαϐατοὶ γίγνονται, XÉN. <i>An. 3, 2, 22,</i> tous les fleuves, alors même qu’on ne peut les franchir loin de leur source, deviennent guéables, si l’on s’avance dans le voisinage des sources ; Μυσοῖς βασιλεὺς πολλοὺς μὲν ἡγεμόνας ἂν δοίη καὶ ὁδοποιήσειέ γ' ἂν αὐτοῖς, καὶ εἰ σὺν τεθρίπποις βούλοιντο ἀπιέναι, XÉN. <i>An. 3, 2, 24,</i> le roi donnerait aux Mysiens des guides nombreux ; bien plus, il leur fraierait des routes, alors même qu’ils voudraient se retirer avec des attelages à quatre chevaux ; <i>avec un présent ou un passé, au sens du lat</i>. quippe : εἰ καὶ πρότερον μὴ εἴθισται λέγειν ἐν ἀνδράσι, LYS. <i>32, 11 Baiter-Sauppe,</i> alors même qu’elle n’a jamais eu l’habitude de parler devant des hommes :<br><b>      10</b> <i>avec</i> ὡς <i>ou</i> ὥσπερ : ὡς εἰ, ὡς εἴ τις, ὥσπερ εἰ (<i>v</i>. ὡς <i>et</i> ὥσπερ) :<br><b>      11</b> <i>avec</i> δή : εἰ δή (<i>v</i>. δή) :<br><b>      12</b> <i>avec</i> περ : εἴπερ :<br><b>      13</b> <i>avec</i> γε : εἴ γε (<i>v</i>. γε) :<br><b>      14</b> <i>avec</i> τε (<i>v</i>. εἴτε) ;<br><b>   IV</b> <i>postér. et par transcript. d’un hébraïsme, dans les formules de serment :</i> (que je cesse d’être le Seigneur) si jamais, <i>etc</i>. SPT. <i>Gen. 14, 23, Num. 14, 30 ; 1Reg. 3, 14 ; Ps. 86, 36 ; 94, 11. ;</i><br><b>E Crases</b>. εἰ <i>se joint par crase :</i><br><b>      1</b> <i>à</i> ἄν, <i>d’où</i> ἐάν, <i>par contract</i>. ἤν (<i>v</i>. ἐάν <i>et ci-dessus</i>) ;<br><b>      2</b> <i>à</i> καί, <i>d’où</i> κεἰ (<i>v</i>. καί).<br><span><b><span class=\"arrow\"></span></b> <i>Épq. et dor</i>. αἰ, HOM. <i>ll. cc. ;</i> THCR. <i>Idyl. 5, 64 ; 8, 85 ; etc. ; d’où</i> αἴπερ, THCR. <i>Idyl. 8, 37 ;</i> αἴτε, THCR. <i>Idyl. 5, 74 ;</i> αἴκα (<i>p</i>. αἴκε) THCR. <i>Idyl. 1, 9 ; 5, 21, etc</i>.<br><span><b>Étym</b>. <i>inconnue ; cf. p.-ê</i>. εἶ-τα, <i>d’un</i> εἰ <i>démonstr</i>. « alors ».</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ει - εἰ</font>\n<br><br>article primaire de condition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n291 fois dans 270 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (37)</li>\n<li>Marc (14)</li>\n<li>Luc (33)</li>\n<li>Jean (34)</li>\n<li>Actes (32)</li>\n<li>Romains (32)</li>\n<li>1 Corinthiens (33)</li>\n<li>2 Corinthiens (11)</li>\n<li>Galates (14)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (5)</li>\n<li>2 Timothée (4)</li>\n<li>Philémon (2)</li>\n<li>Hébreux (14)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (10)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (5)</li>\n</ul>\n</td></tr>\n</table>","G1488":"<h1>ei</h1>\n<p>Strong n° 1488 <i>Prononciation [i]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tu es, vous êtes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἶ</b>, <i>2 sg. de</i> εἰμί, être.<br><i>2 sg. prés. ind. ou impér. poét. de</i> εἶμι, aller.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ει - εἶ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n92 fois dans 89 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (17)</li>\n<li>Marc (10)</li>\n<li>Luc (16)</li>\n<li>Jean (26)</li>\n<li>Actes (6)</li>\n<li>Romains (3)</li>\n<li>Galates (1)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (2)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G1489":"<h1>eige</h1>\n<p>Strong n° 1489 <i>Prononciation [i'-gheh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>si, en effet, d'autant plus que, comme, puisque</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ει γε - εἴγε</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1490":"<h1>ei de me (ge)</h1>\n<p>Strong n° 1490 <i>Prononciation [i deh may'-gheh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>autrement, sinon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ει δε μη (γε) - εἰ δὲ μή (γε)</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (5)</li>\n<li>Jean (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1491":"<h1>eidos</h1>\n<p>Strong n° 1491 <i>Prononciation [i'-dos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'apparence extérieure, la forme du visage, l'aspect</li>\n<li>forme, genre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἶδος, εος-ους (τὸ) :<br>   I</b> aspect extérieur, <i>d’où :</i><br><b>      1</b> forme du corps, air d’une personne <i>ou</i> d’une chose, IL. <i>2, 57 ; 3, 39, etc. ;</i> PLAT. <i>Conv. 715</i> b ; <i>au plur</i>. les traits (du visage) XÉN. <i>Cyr. 4, 5, 57 ; en parl. d’animaux,</i> OD. <i>17, 308 ;</i> HDT. <i>3, 107 ;</i> XÉN. <i>Cyn. 3, 3 ; 4, 2 ; particul</i>. beauté, OD. <i>17, 454 ;</i> HDT. <i>1, 199, etc. ;</i><br><b>      2</b> <i>p. ext. en poésie,</i> la personne elle-même (<i>cf</i>. δέμας) SOPH. <i>El. 1177 ;</i><br><b>   II</b> forme, <i>en gén. :</i><br><b>      1</b> <i>p. opp. à la</i> « matière » <i>ou</i> « substance (ὕλη) » ARSTT. <i>Phys. 1, 4, 1, etc. ;</i><br><b>      2</b> forme d’une chose dans l’esprit, idée, PLAT. <i>Conv. 210</i> b ; <i>au plur</i>. PLAT. <i>Phæd. 103</i> e, <i>etc. ;</i><br><b>      3</b> forme propre à une chose, <i>d’où :</i> genre, sorte, HDT. <i>1, 94 ;</i> PLAT. <i>Phæd. 91</i> d, <i>etc. ;</i> caractère d’une maladie, THC. <i>2, 50 ;</i> caractère spécifique d’une chose, PLAT. <i>Rsp. 576</i> a ; forme de gouvernement, THC. <i>8, 90 ;</i><br><b>      4</b> <i>p. suite,</i> espèce, PLAT. <i>Rsp. 544</i> d ; <i>p. opp. à</i> γένος, PLAT. <i>Parm. 129</i> c ;<br><b>      5</b> manière particulière de diriger qqe ch. (une opération, une discussion, <i>etc.) d’où</i> méthode, façon, THC. <i>6, 77 ; 8, 56</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Duel</i> εἴδη, PLAT. <i>Rsp. 572</i> a, <i>Pol. 258</i> c.<br><span><b>Étym</b>. <i>v</i>. *εἴδω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ειδος - εἶδος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G1492":"<h1>eido</h1>\n<p>Strong n° 1492 <i>Prononciation [i'-do]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>voir\n<ol type=\"a\">\n<li>percevoir avec les yeux</li>\n<li>apercevoir par n'importe quel sens</li>\n<li>remarquer, discerner, découvrir</li>\n<li>voir\n<ol>\n<li>tourner les yeux, l'esprit, l'attention vers quelque chose</li>\n<li>redoubler d'attention, observer</li>\n<li>voir à propos de quelque chose, ce qui va se passer</li>\n<li>examiner, inspecter</li>\n</ol>\n</li>\n<li>expérimenter un état ou une condition</li>\n<li>découvrir, avoir un entretien, visiter</li>\n</ol>\n</li>\n<li>connaître\n<ol type=\"a\">\n<li>connaître sur quelque chose</li>\n<li>la connaissance, la compréhension, percevoir\n<ol>\n<li>d'un fait</li>\n<li>le sens de quelque chose qui est défini</li>\n<li>être versé dans</li>\n</ol>\n</li>\n<li>avoir une attention sur, chérir, avoir de la considération pour (<a class=\"ref\" data-r=\"1TH5.12\">1 Thessaloniciens 5.12</a>)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>*εἴδω</b> <span>(<i>f</i>. εἴσομαι ; <i>ao.2</i> εἶδον, <i>d’où impér</i>. ἴδε <i>ou</i> ἰδέ, <i>sbj</i>. ἴδω, <i>opt</i>. ἴδοιμι, <i>inf</i>. ἰδεῖν, <i>part</i>. ἰδών ; <i>pf.2</i> οἶδα, <i>au sens d’un prés. ; pl.q.pf</i>. ᾔδειν, <i>att</i>. ᾔδη, <i>au sens d’un impf</i>.)</span><br><b>      1</b> voir : ὀφθαλμοῖσιν <i>ou</i> ἐν ὀφθαλμοῖσιν ἰδεῖν, IL. <i>1, 587, etc. ;</i> ἐν ὄμμασιν ἰδεῖν, EUR. <i>Or. 1020, etc</i>. voir de ses yeux ; οἰκτρὸς ἰδεῖν, ESCHL. <i>Pr. 238 ;</i> λαμπρὸς ἰδεῖν, PLAT. <i>Rsp. 620</i> a, <i>etc</i>. lamentable à voir, brillant à voir ;<br><b>      2</b> observer, examiner : ἔς τινα, IL. <i>2, 271 ;</i> εἴς τι, IL. <i>3, 364 ;</i> πρός τινα, OD. <i>12, 244 ;</i> ἐπί τι, IL. <i>23, 143,</i> regarder qqn <i>ou</i> qqe ch. (le ciel, la mer, <i>etc</i>.) ; εἰς ὦπα ἰδέσθαι, IL. <i>9, 373 ;</i> κατ' ἐνῶπα ἰδεῖν, IL. <i>15, 320 ;</i> ἄντα ἰδεῖν, IL. <i>13, 184 ; ou</i> ἔσαντα, IL. <i>17, 334 ; ou</i> ἄντην, OD. <i>5, 78,</i> regarder en face ;<br><b>      3</b> voir, avoir une entrevue : τινα, XÉN. <i>An. 2, 4, 5,</i> avec qqn ;<br><b>      4</b> <i>fig</i>. se représenter, se figurer : ἐνὶ φρεσίν, IL. <i>21, 61 ;</i> OD. <i>7, 327,</i> dans l’esprit ; ἰδεῖν τῇ διανοίᾳ, PLAT. <i>Rsp. 510</i> e, se représenter par la pensée ;<br><b><i>Moy</i>. εἴδομαι</b> <span>(<i>ao.2</i> εἰδόμην, <i>d’où impér</i>. ἰδοῦ, <i>sbj</i>. ἴδωμαι, <i>opt</i>. ἰδοίμην, <i>inf</i>. ἰδέσθαι, <i>part</i>. ἰδόμενος)</span><br><b>   I</b> se faire voir, <i>d’où :</i><br><b>      1</b> se montrer, paraître : εἴδεται ἦμαρ, IL. <i>13, 98,</i> le jour paraît ;<br><b>      2</b> paraître, sembler, <i>avec l’inf</i>. IL. <i>1, 228 ;</i> OD. <i>9, 11, etc. ; ou</i> sans <i>inf</i>. τόγε κέρδιον εἴσατο θυμῷ, OD. <i>19, 283, etc</i>. cela lui parut dans son cœur plus avantageux ;<br><b>      3</b> avoir l’air, faire semblant, feindre de : ἴμεν ἐς Λῆμνον, OD. <i>8, 283,</i> d’aller à Lemnos ;<br><b>   II</b> se rendre semblable, <i>d’où avec double rég</i>. εἴδεσθαι φθογγήν τινι, IL. <i>2, 791 ;</i> ὄψιν ἀνέρι, PD. <i>N. 10, 15,</i> se donner une voix semblable à celle de qqn, un air semblable à celui de qqn ; prendre la voix, les traits de qqn ; <i>cf</i>. IL. <i>20, 81 ;</i> OD. <i>1, 105 ;</i> PD. <i>P. 4, 51 ;</i> HDT. <i>6, 69 ; 7, 56, etc</i>.<br><i>Pf</i>. οἶδα (οἶσθα, οἶδε, ἴσμεν, ἴστε, ἴσασι, ἴστον, ἴστον, <i>impér</i>. ἴσθι, <i>sbj</i>. εἰδῶ, <i>opt</i>. εἰδείην, <i>inf</i>. εἰδέναι, <i>part</i>. εἰδώς) savoir, <i>càd. :</i><br><b>      1</b> être informé de, instruit de, <i>etc. :</i> τι, IL. <i>17, 219, etc. ;</i> OD. <i>18, 227, etc. ;</i> SOPH. <i>O.C. 24 ;</i> PLAT. <i>Ap. 21</i> d, <i>etc</i>. savoir, connaître qqe ch. ; περί τινος, OD. <i>17, 563,</i> être bien renseigné sur qqn ; <i>souv. renforcé par</i> εὖ <i>ou</i> σάφα, OD. <i>15, 211, etc</i>. bien savoir, savoir de science sûre ; εἰδέναι ὥς <i>ou</i> ὅτι, <i>précédé d’un acc. :</i> ἐάν τινα εἰδῶσιν ὅτι ἄδικός ἐστι, PLAT. <i>Prot. 323</i> b, s’ils savent que qqn est injuste <i>ou</i> déshonnête ; ᾔδει βασιλέα ὅτι μέσον ἔχοι τοῦ στρατεύματος, XÉN. <i>An. 1, 8, 21,</i> il savait que le roi occupait le centre de l’armée ; <i>avec un part. à l’acc</i>. τὸν Μῆδον ἴσμεν ἐκ περάτων γῆς ἐλθόντα, THC. <i>1, 69,</i> nous savons que le Mède est venu du bout du monde ; <i>avec le part. précédé de</i> ὡς : ὡς μηδὲν εἰδότ' ἴσθι μ' ὧν ἀνιστορεῖς, SOPH. <i>Ph. 253,</i> sache que je ne sais rien de ce que tu racontes ; <i>avec un part. au nom. par attract. du sujet :</i> ἴσθι μοι δώσων, ESCHL. <i>Ag. 1670,</i> sache que tu me donneras ; οἶδα κεκτημένος, EUR. <i>Hec. 401,</i> je sais que j’ai gagné, que j’ai, <i>etc. ; rar. avec une prop. inf</i>. ἴσθι μὴ ψευδῶς μ' ἐρεῖν, EUR. <i>I.A. 1005,</i> sache que je ne mentirai pas (que je ne te tromperai pas) ; <i>dans des loc. nég</i>. οὐκ οἶδ' ὅπως, ὅπῃ, <i>etc</i>. PLAT. <i>Rsp. 400</i> b, <i>etc</i>. je ne sais comment, par quel moyen ; οὐκ οἶδ' εἰ, ATT. je ne sais si ; <i>cf. la loc</i>. οὐκ οἶδ' εἰ <i>au mil. d’une phrase</i> (<i>v</i>. εἰ, B, I) ; οὐκ οἶδ' ἢ… ἤ, IL. <i>10, 342,</i> je ne sais si… ou si ; <i>abs. au part</i>. μετ' εἰδόσιν ἀγορεύειν, IL. <i>10, 250 ; ou</i> ἐν εἰδόσιν, THC. <i>2, 36 ; 4, 59,</i> parler au milieu de gens qui savent ; εἰδότι τοι ἐρέω, PD. <i>P. 4, 142,</i> je te le dirai à toi qui sais ; <i>souv. dans des formules d’attestation :</i> ἴστω νῦν Ζεύς, IL. <i>10, 329 ; béot</i>. ἴττω Δεύς, ἴττω Ἡρακλῆς, AR. <i>Ach. 860, 911, etc</i>. en ce moment que Zeus, qu’Hèraklès sache, <i>càd</i>. en ce moment j’atteste Zeus, Hèraklès ; <i>souv. entre parenth</i>. οἶδ' ἐγώ, EUR. <i>Med. 948 ;</i> οἶδα, ESCHL. <i>Pers. 838 ;</i> SOPH. <i>Aj. 560 ;</i> σάφ' οἶδα, ESCHL. <i>Pr. 504 ;</i> EUR. <i>Med. 94 ;</i> εὖ οἶδα, EUR. <i>Med. 963,</i> je le sais, je le sais très bien ; <i>de même,</i> οἶδ' ὅτι, SOPH. <i>Ant. 276 ;</i> εὖ οἶδ' ὅτι, DÉM. <i>110, 5,</i> je le sais, <i>litt</i>. je sais, je sais bien que (cela est) ; σάφ' ἴσθ' ὅτι, AR. <i>Pl. 889,</i> sache-le bien ; <i>de même encore dans les interr</i>. οἶσθ' ὡς, οἶσθ' ὅ <i>avec un impér</i>. οἶσθ' ὡς ποίησον ; SOPH. <i>O.R. 543,</i> sais-tu ce que tu as à faire (<i>litt</i>. fais sais-tu quoi ?) ; οἶσθ' οὖν ὃ δρᾶσον ; EUR. <i>I.A. 725, Hec. 225,</i> sais-tu donc ce que tu as à faire ? ;<br><b>      2</b> savoir, être habile à <i>ou</i> dans, <i>avec le gén. :</i> εἰδ. τεράων, IL. <i>12, 229 ; 15, 412,</i> être habile à interpréter les prodiges ; <i>particul. au partic</i>. τόξων εὖ εἰδώς, IL. <i>2, 718 ;</i> οἰωνῶν σάφα εἰδώς, OD. <i>1, 202,</i> habile à manier l’arc, à interpréter le vol des oiseaux ; μάχης εὖ εἰδότε πάσης, IL. <i>2, 823,</i> ayant tous deux l’expérience de toute sorte de combats ; <i>avec un inf</i>. IL. <i>7, 238 ;</i> SOPH. <i>Ph. 1010 ;</i> AR. <i>Vesp. 376,</i> savoir, être habile à, <i>etc. ;</i><br><b>      3</b> être en état de, pouvoir, <i>avec l’inf</i>. EUR. <i>Med. 664, Hipp. 729 ;</i> DÉM. <i>51, 28 ;</i><br><b>      4</b> avoir tels <i>ou</i> tels sentiments, <i>avec un acc. pl. neutre :</i> πεπνυμένα, κεχαρισμένα εἰδ., <i>etc</i>. HOM. être prudent, reconnaissant, <i>etc. ;</i> φίλα εἰδέναι τινί, OD. <i>3, 277,</i> avoir des sentiments d’amitié pour qqn : χάριν εἰδέναι τινί, IL. <i>14, 235 ;</i> HDT. <i>3, 21 ;</i> XÉN. <i>Cyr. 3, 1, 29 ; 6, 2, 2 ;</i> PLAT. <i>Menex. 241</i> e, savoir gré, <i>ou</i> être reconnaissant à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Act. Prés. inus., sauf p.-ê. dor</i>. εἴδομες, THCR. <i>Idyl. 2, 25. — Fut. ion. et att. réc</i>. εἰδήσω, OD. <i>7, 327,</i> HH. <i>2, 306 ; 3, 466 ;</i> HDT. <i>7, 234 ;</i> HPC. <i>7, 476 ; 8, 430 Littré ;</i> ARSTT. <i>Top. 1, 18, 2, etc. ; inf. épq</i>. εἰδησέμεν, OD. <i>6, 257 ; mais</i> εἰδήσειν, IL. <i>1, 546 ; f. dor</i>. ἰδησῶ <span>[ῐ]</span> THCR. <i>Idyl. 3, 37. — Ao.1 réc</i>. εἶδα, ORPH. <i>Arg. 119, ou</i> εἴδησα, HPC. <i>2, 436 ; 9, 230 Littré ;</i> ARSTT. <i>Probl. 19, 42, etc. ;</i> TH. <i>Char. 1. — Ao.2 ind. épq</i>. ἴδον, IL. <i>1, 262 ;</i> OD. <i>12, 244 ;</i> HÉS. <i>Th. 555 ;</i> PD. <i>P. 5, 84, etc. ; sbj. épq</i>. ἴδωμι, IL. <i>18, 63 ; inf. épq. et ion</i>. ἰδέειν, IL. <i>23, 463 ;</i> HDT. <i>1, 32 ; éol</i>. ἴδην, SAPPH. <i>101. Ao. itér. 3 sg</i>. ἴδεσκε, IL. <i>3, 217. — Pf. 1 réc</i>. εἴδηκα, ARSTT. <i>Top. 1, 24, 484 Sylb. — Pf. 2 au sens d’un prés</i>. οἶδα (<i>v. ci-dessus</i>) : <i>Ind. 2 sg. poét</i>. οἶδας, OD. <i>1, 337 ;</i> HH. <i>Merc. 456, 467 ;</i> THGN. <i>491, 957 ;</i> HDT. <i>3, 72 ;</i> EUR. <i>Alc. 780, etc. ; poét</i>. οἶσθας, CRAT. ALEX. PHILÉM. MÉN. (<i>Com. fr. 2, 80 ; 3, 389 ; 4, 14 et 174) ; 1 pl</i>. οἴδαμεν, HDT. <i>2, 17 ; 4, 46 ; 7, 214, etc. ;</i> HPC. <i>1, 622 Littré ;</i> XÉN. <i>An. 2, 4, 6 (var</i>. ἴσμεν) ; PLAT. <i>2 Alc. 141, etc. ; épq. et ion</i>. ἴδμεν, IL. <i>2, 486 ;</i> OD. <i>17, 78 ;</i> HÉS. <i>Th. 28 ;</i> HDT. <i>1, 6, 142, etc. ; 2 pl</i>. οἴδατε <span>[ᾰ]</span> AR. <i>Ach. 294 ;</i> ANTH. <i>12, 81, etc. ; 3 pl</i>. οἴδασι <span>[ᾱ]</span> HDT. <i>2, 43 ;</i> XÉN. <i>Œc. 20, 14 ; etc. Au lieu de</i> οἴδαμεν, <i>etc. les Att. emploient d’ord. les formes du prés. de</i> ἴσημι : ἴσμεν, ἴστε, ἴσασι, ἴστον, ἴστον (<i>v</i>. ἴσημι). — <i>Impér. 3 sg. béot</i>. ἴττω, AR. <i>Ach. 860 ;</i> PLAT. <i>Phæd. 62</i> a ; <i>postér</i>. ἰδέτω, PHALAR. <i>Ep. 5, p. 32 Valckenaer. — Sbj. épq</i>. εἰδέω, OD. <i>16, 236, ou</i> ἰδέω, IL. <i>14, 235 ; 1 pl</i>. εἴδομεν (<i>p</i>. -ωμεν) IL. <i>1, 363 ;</i> OD. <i>3, 18 ; 2 pl</i>. εἴδετε, IL. <i>8, 18 ;</i> OD. <i>9, 17. — Inf. épq</i>. ἴδμεναι, IL. <i>13, 273 ;</i> THGN. <i>221 ; ou</i> ἴδμεν, IL. <i>11, 719 ; poét</i>. ἰδέμεν, PD. <i>N. 7, 25. — Part. fém</i>. ἰδυῖα (<i>touj. avec</i> πραπίδεσσι) IL. <i>1, 608, etc. — Pl.q.pf. épq. et ion</i>. ᾔδεα, IL. <i>14, 71 ;</i> THGN. <i>853 ;</i> HDT. <i>2, 150 ; 2 sg</i>. ᾔδησθα, OD. <i>19, 93 ;</i> SOPH. <i>Ant. 447 ;</i> EUP. <i>2-1, 570 Meineke ;</i> PLAT. <i>Men. 80, etc. et</i> ᾔδεισθα, EUR. <i>El. 926, Cycl. 108 ; ou</i> ἠείδης, IL. <i>22, 280 ; 3 sg</i>. ᾔδειν <i>dev. une voy</i>. EUR. <i>Ion 1187 ;</i> AR. <i>Pax 1182, Vesp. 558 (ttf</i>. ᾔδει οὐδείς, THC. <i>6, 27) ou</i> ᾔδην, AR. <i>Vesp. 635 ; rar. dev. une cons</i>. AR. <i>Ach. 35 ; ou</i> ᾔδεεν, IL. <i>18, 404 ; ou</i> ἠείδη, OD. <i>9, 206 (sel. d’autres</i> ἠείδει, <i>23, 29 ; au plur. les poètes emploient</i> ε <i>au lieu de</i> ει : ᾔδεμεν (<i>p</i>. ᾔδειμεν) SOPH. <i>O.R. 1232, ou</i> ᾖσμεν, ESCHL. <i>Ag. 1099 ;</i> EUR. <i>Hec. 1112, Her. 658 ;</i> AR. <i>fr. 198 ;</i> ANT. <i>fr. 7, 3 ;</i> ESCHN. <i>3, 175 ;</i> ᾔδετε, EUR. <i>Bacch. 1345, ou</i> ᾖστε, SOPH. <i>fr. 317 ; 3 pl</i>. ᾔδεσαν, HDT. <i>8, 78 ;</i> XÉN. <i>An. 4, 3, 10 ; 6, 5, 31 ; etc. ou</i> ᾖσαν, ESCHL. <i>Pr. 451 ;</i> EUR. <i>Cycl. 231, Rhes. 855 ; épq</i>. ἴσαν, IL. <i>18, 405 ;</i> OD. <i>13, 170 ; postér</i>. ᾔδεισαν, STR. <i>15, 3, 23 ;</i> SPT. <i>Gen. 42, 23 ; Ex. 16, 15 ;</i> NT. <i>Marc. 1, 34 ; Joh. 2, 9, etc. ; duel</i> ᾔστην, AR. <i>Av. 19. — Moy. prés. poét</i>. ἐείδομαι, PD. <i>N. 10, 15 ;</i> A. RH. <i>4, 221 ;</i> THCR. <i>Idyl. 25, 58. — Fut., 2 sg</i>. εἴσει, SOPH. <i>O.C. 1149 ;</i> AR. <i>Vesp. 774 ;</i> XÉN. <i>Cyr. 7, 4, 12 ; épq</i>. εἴσεαι, IL. <i>21, 292 ;</i> OD. <i>2, 40. — Ao., 2 sg. épq</i>. ἐείσαο, IL. <i>9, 645 ; part. épq</i>. ἐεισάμενος, IL. <i>17, 326 ; 20, 82 ;</i> OD. <i>6, 24 ; 11, 241. — Ao. itér. 3 sg</i>. εἰσάσκετο, <i>ou</i> ἰσάσκετο, IL. <i>24, 607. — Ao.2 dor</i>. εἰδόμαν <span>[ᾱ]</span> SOPH. <i>O.R. 1217 ;</i> EUR. <i>I.A. 254, 295 ; épq. et lyr</i>. ἰδόμην, IL. <i>24, 484 ;</i> HÉS. <i>Th. 451 ; dor</i>. ἰδόμαν <span>[ᾱ]</span> EUR. <i>I.T. 150 ; impér. au sens exclam</i>. ἰδοῦ, SOPH. <i>Ph. 776 ; sbj. 2 sg. épq</i>. ἴδηαι, IL. <i>8, 105 ; opt. 3 pl. ion. et épq</i>. ἰδοίατο, OD. <i>1, 162 ;</i> HDT. <i>9, 51</i>.<br><span><b>Étym</b>. <i>p</i>. (ϝ)ειδ-, <i>de la R. indo-europ</i>. *ueid-, voir, savoir, <i>cf</i>. ἵστωρ, <i>sscr</i>. véda, <i>lat</i>. vīdī, <i>all</i>. wissen.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ειδω - εἴδω</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – une connaissance fondée sur une expérience personnelle\n<br><br> – voir avec les yeux de l'esprit, donc une pure et claire perception mentale\n<br><br> – une connaissance obtenue par la proximité de la chose connue, notre compréhension\n<br><br> – implique une perspicacité naturelle, une connaissance obtenue à travers les cinq sens</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n666 fois dans 622 versets de 26 livres bibliques (NT)\n<ul>\n<li>Matthieu (83)</li>\n<li>Marc (65)</li>\n<li>Luc (92)</li>\n<li>Jean (122)</li>\n<li>Actes (68)</li>\n<li>Romains (19)</li>\n<li>1 Corinthiens (30)</li>\n<li>2 Corinthiens (16)</li>\n<li>Galates (7)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (11)</li>\n<li>Colossiens (4)</li>\n<li>1 Thessaloniciens (16)</li>\n<li>2 Thessaloniciens (3)</li>\n<li>1 Timothée (7)</li>\n<li>2 Timothée (6)</li>\n<li>Tite (2)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (6)</li>\n<li>Jacques (4)</li>\n<li>1 Pierre (6)</li>\n<li>2 Pierre (3)</li>\n<li>1 Jean (17)</li>\n<li>3 Jean (2)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (70)</li>\n</ul>\n</td></tr>\n</table>","G1493":"<h1>eidoleion</h1>\n<p>Strong n° 1493 <i>Prononciation [i-do-li'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un temple d'idoles, temple consacré aux idoles</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἰδωλεῖον, ου (τὸ)</b> temple d’idoles, SPT. <i>1Macc. 1, 47, etc. ;</i> NT. <i>1Cor. 8, 10</i>.<br><span><b>Étym</b>. εἴδωλον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ειδωλειον - εἰδωλεῖον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1494":"<h1>eidolothuton</h1>\n<p>Strong n° 1494 <i>Prononciation [i-do-loth'-oo-ton]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sacrifié aux idoles : les viandes offertes en sacrifice et revendues sur les marchés</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἰδωλό·θυτον, ου (τὸ)</b> <span>[ῠ]</span> chair des victimes, NT. <i>Ap. 15, 29 ; 1Cor. 8, 1</i>.<br><span><b>Étym</b>. εἴδωλον, θύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ειδωλοθυτον - εἰδωλόθυτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>1 Corinthiens (6)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1495":"<h1>eidololatreia</h1>\n<p>Strong n° 1495 <i>Prononciation [i-do-lol-at-ri'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le culte de faux dieux, idolâtrie\n<ol type=\"a\">\n<li>fêtes sacrificielles données en honneur de faux dieux</li>\n<li>avarice : culte à Mammon</li>\n</ol>\n</li>\n<li>pluriel : les vices provenant de l'idolâtrie et qui lui sont particuliers</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἰδωλολατρεία, ας (ἡ)</b> culte des idoles, idolâtrie, NT. <i>Gal. 5, 20 ; 1Cor. 10, 14 ;</i> CLÉM. <i>2, 364 a Migne, etc</i>.<br><span><b>Étym</b>. εἰδωλολάτρης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ειδωλολατρεια - εἰδωλολατρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1496":"<h1>eidololatres</h1>\n<p>Strong n° 1496 <i>Prononciation [i-do-lol-at'-race]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'adorateur de faux dieux, l'idolâtre\n<ol type=\"a\">\n<li>pour tout participant, même chrétien, à toute adoration païenne en participant à des fêtes sacrificielles et en mangeant des morceaux des viandes sacrifiées</li>\n</ol>\n</li>\n<li>un homme cupide, idolâtre de Mammon</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἰδωλο·λάτρης, ου (ὁ)</b> idolâtre, NT. <i>1Cor. 5, 10, etc</i>.<br><span><b>Étym</b>. εἴδωλον, λατρεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ειδωλολατρης - εἰδωλολάτρης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 3 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (4)</li>\n<li>Ephésiens (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1497":"<h1>eidolon</h1>\n<p>Strong n° 1497 <i>Prononciation [i'-do-lon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une image, une ressemblance, reproduction des traits\n<ol type=\"a\">\n<li>ce qui représente la forme d'un objet, que cet objet soit réel ou imaginaire, image, portait</li>\n<li>les ombres des défunts, les apparitions, spectres, fantômes, ...</li>\n</ol>\n</li>\n<li>l'image d'un dieu païen, d'une idole</li>\n<li>un faux dieu</li>\n<li>image conçue dans l'esprit, d'où imagination</li>\n<li>image réfléchie (dans l'eau, dans un miroir)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἴδωλον, ου (τὸ)</b> reproduction des traits, image, <i>particul. :</i><br><b>      1</b> simulacre, fantôme, IL. <i>2, 451 ;</i> OD. <i>4, 796 ;</i> HDT. <i>5, 92, 32 ;</i> PLAT. <i>Leg. 959</i> b, <i>etc. ;</i> βροτῶν εἴδωλα καμόντων, OD. <i>11, 476,</i> fantômes des morts ;<br><b>      2</b> image, portrait, HDT. <i>1, 51 ;</i> ATT. <i>etc. ; postér</i>. image d’un dieu, idole, SPT. <i>4Reg. 17, 12, etc. ;</i> NT. <i>1Cor. 12, 2, etc. ; en parl. de choses,</i> εἴδωλα οὐράνια, A. RH. <i>3, 1004,</i> les constellations ;<br><b>      3</b> image réfléchie (dans l’eau, dans un miroir) ARSTT. <i>Div. per somn. 2, 12 ;</i><br><b>      4</b> <i>fig</i>. image conçue dans l’esprit, XÉN. <i>Conv. 4, 21 ; d’où</i> imagination, PLAT. <i>Phæd. 66</i> c ; <i>p. opp. à</i> τὸ ἀληθές, PLAT. <i>Theæt. 150</i> c ; <i>particul. t. stoïc</i>. idée, CIC. <i>Fam. 15, 16</i>.<br><span><b>Étym</b>. εἶδος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ειδωλον - εἴδωλον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 7 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1498":"<h1>eien</h1>\n<p>Strong n° 1498 <i>Prononciation [i'-ane]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être, exister, signifier, se trouver, être présent</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>εἴην</b>, <i>opt. de</i> εἰμί.<br><br>\n➁ <b>εἵην</b>, <i>v</i>. ἵημι. (ci-dessous)<br><br>\n<b>ἵημι</b> <span>(<i>impf</i>. ἵην, <i>f</i>. ἥσω, <i>ao.1</i> ἧκα, <i>seul. au sg. et à l’ind. ; ao.2 seul. au pl</i>. ἕμεν, ἕτε, ἕσαν, <i>ou avec augm</i>. εἷμεν, εἷτε, εἷσαν ; <i>pf</i>. εἷκα ; <i>pass. ao.1</i> ἕθην, <i>att</i>. εἵθην, <i>pf</i>. εἷμαι)</span> <span>[l’ι <i>initial est bref en gén. à l’act. dans HOM. et les épiques, long (excepté dans</i> ESCHL. <i>Sept. 310, 493 et dans</i> EUR. <i>I.A. 298) chez les Att</i>.]</span><br><b>   I <i>tr</i>. :<br>      1</b> mouvoir en avant : πόδας καὶ χεῖρε φέρεσθαι, OD. <i>12, 442,</i> mouvoir les pieds et les mains pour se porter en avant : πόδα, EUR. <i>Rhes. 798,</i> faire s’élancer en avant, faire fuir (des chevaux) ;<br><b>      2</b> <i>p. suite,</i> envoyer, lancer, jeter : ἄγγελόν τινι, IL. <i>18, 182,</i> envoyer, un messager à qqn ; ἴκμενον οὖρόν τινι, IL. <i>1, 479,</i> envoyer à qqn un vent favorable ; <i>en parl. de fleuves, de sources :</i> ῥόον, IL. <i>12, 25 ;</i> ῥέος, ESCHL. <i>Pr. 812 ;</i> ὕδωρ, IL. <i>21, 158,</i> envoyer un courant, de l’eau ; <i>en parl. du feu :</i> λιγνύν, ESCHL. <i>Sept. 475,</i> envoyer, jeter de la suie ; <i>en parl. du son :</i> ἔπεα, IL. <i>3, 222,</i> lancer des paroles ; ὄπα, IL. <i>3, 152, 221 ;</i> OD. <i>12, 192 ;</i> φωνήν, PLAT. <i>Leg. 890</i> d, faire entendre une parole ; Ἑλλάδα γλῶσσαν, HDT. <i>9, 16 ;</i> Δωρίδα γλῶσσαν, THC. <i>3, 112,</i> parler grec, parler dorien ; θρῆνον, ESCHL. <i>Sept. 865 ;</i> κωκυτόν, SOPH. <i>Aj. 851,</i> faire entendre des lamentations, des gémissements ; <i>abs</i>. ἧκε (<i>s.-e</i>. φωνήν) PLUT. <i>M. 973</i> d, il fit entendre sa voix ; <i>en parl. d’instruments :</i> μέλη τῶν χορδῶν ἱεισῶν, PLAT. <i>Leg. 812</i> d, les cordes faisant entendre des airs ;<br><b>      3</b> <i>avec idée d’hostilité :</i> λᾶαν, OD. <i>9, 538 ;</i> βέλος, IL. <i>4, 498 ;</i> ἐπ' ἀλλήλοις βέλεα, HÉS. <i>Th. 684,</i> lancer une pierre, un trait ; se lancer des traits les uns aux autres ; <i>avec un acc. de pers. :</i> τὸν δὲ ποταμόνδε ἧκε φέρεσθαι, IL. <i>21, 120,</i> il le lança dans le fleuve, pour qu’il fût emporté par les flots ; <i>avec le nom de la pers. frappée au gén. et celui de l’instrument à l’acc. :</i> ἀπιόντος ἵει ὀϊστόν, IL. <i>13, 650,</i> il frappa d’une flèche l’ennemi qui s’éloignait ; <i>avec le nom. de la pers. à l’acc. et celui de l’instr. au datif :</i> τινὰ ἀξίνῃ, XÉN. <i>An. 1, 5, 12,</i> frapper quelqu’un d’une hache ; <i>fig</i>. τῶν μεγάλων ψυχῶν ἱείς, SOPH. <i>Aj. 154,</i> s’attaquant aux grandes âmes ; <i>abs</i>. lancer un trait, IL. <i>17, 515 ;</i> OD. <i>9, 499 ;</i> XÉN. <i>An. 3, 4, 17 ;</i> PLAT. <i>Theæt. 194</i> a ; ἱ. ἐπὶ σκοπόν, XÉN. <i>Ages. 1, 25,</i> lancer un trait au but ;<br><b>      4</b> laisser tomber : ἐκ χειρὸς φάσγανον, OD. <i>22, 84,</i> son couteau de sa main ; κόμας, OD. <i>6, 231,</i> laisser flotter sa chevelure ;<br><b>   II <i>intr</i></b><i>. (ou s.-e</i>. ἑαυτόν) <i>seul. en poésie (les Att. emploient en ce sens les composés de</i> ἱέναι) se jeter, s’élancer, s’épancher : ποταμὸς ἐπὶ γαῖαν ἵησιν, OD. <i>11, 239,</i> le fleuve se répand sur la terre ; κρήνη ἵησιν, OD. <i>7, 130,</i> la source s’épanche ;<br><b><i>Moy</i>. ἵεμαι</b> <span>(<i>impf</i>. ἱέμην, <i>rar. ao.1</i> ἡκάμην, <i>plus souv. ao.2</i> ἕμην, <i>att</i>. εἵμην)</span> <span>[<i>l’ι initial est long même dans HOM. (v. ci-dessus l’act</i>.) ἵει, IL. <i>3, 221 ; 16, 152 ;</i> ἱεῖσαι, OD. <i>12, 192</i>]</span><br><b>      1</b> s’élancer : οἴκαδε, ἄστυδε, Τροίηνδε, OD. <i>19, 187, etc</i>. vers la maison, la ville, Troie ; <i>avec le gén</i>. ἱ. πόλιος, s’élancer vers la ville ; IL. <i>11, 168 ;</i> πρός τινα, HDT. <i>9, 78 ;</i> ἐπί τινα, HDT. <i>6, 112 ; etc</i>. vers qqn ; πρὸς λέχη, SOPH. <i>O.R. 1242,</i> vers la couche ; εἰς ὄρεα, EUR. <i>Bacch. 140,</i> vers les montagnes ; <i>en parl. de choses : abs</i>. ἱέμενος ῥεῖ, PLAT. <i>Crat. 419</i> e, il s’avance en coulant ;<br><b>      2</b> <i>fig</i>. se porter de désir vers, désirer, souhaiter : τινός, IL. <i>11, 168 ; 23, 371,</i> qqe ch. (victoire, retour dans la patrie, <i>etc</i>.) ; <i>avec un inf. :</i> βαλέειν δέ ἑ ἵετο θυμός, IL. <i>8, 301,</i> il souhaitait ardemment en son cœur de l’atteindre.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind. 3 pl. épq</i>. ἱεῖσι, IL. <i>3, 152 ; part. acc. pl</i>. ἱέντας, <i>Sol. 36, 10 ;</i> THC. <i>3, 112. Sbj. 3 sg. poét</i>. ἱῇσι, THGN. <i>94, Impf. 3 pl. épq. sync</i>. ἵεν, IL. <i>12, 33 ;</i> PD. <i>I. 1, 25, Fut. dor</i>. ἡσῶ, <i>d’où 2 pl</i>. ἡσεῖτε, AR. <i>Ach. 747, Ao.1, 3 pl</i>. ἧκαν, XÉN. <i>An. 4, 5, 18. Ao.2</i> ἧν ; <i>sbj. 3 sg. épq</i>. ᾗσι, IL. <i>15, 359 ; opt</i>. εἵην, IL. <i>3, 221 ; inf</i>. εἷναι, AR. <i>Ran. 133 ; inf. épq</i>. ἱέμεναι, IL. <i>22, 206 ;</i> ἱέμεν, HÉS. <i>O. 596. — Moy. impf. 1 pl. poét</i>. ἱέμεσθα, SOPH. <i>Ant. 432. Ao.2, 3 pl</i>. ἕντο, IL. <i>9, 92 ;</i> OD. <i>17, 99</i>.</span><br><span><b>Étym</b>. <i>R. indo-europ</i>. *(H)ieh₁-, lancer, <i>d’où</i> *ϳε-, *hε- ; <i>avec redoubl</i>. *hι-hε- <i>d’où le th. du prés</i>. ἱε- ; <i>cf</i>. ἑσμός, <i>lat</i>. jaciō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ειεη - εἴην</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (7)</li>\n<li>Jean (1)</li>\n<li>Actes (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1499":"<h1>ei kai</h1>\n<p>Strong n° 1499 <i>Prononciation [i kahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>même, si, bien que</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἰ καί</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ει και - εἰ καί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 20 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (3)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (11)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>"};
